window.__MDETAIL__['chinese']={"topics":{"cnc_p001":{"desc":"认识天、地、人、你、我、他，分清人与入、天与夫。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"一年级语文从识字「天地人」开始。按2024年修订的统编教材，识字排在汉语拼音前面，前面没有更早的小学语文知识点。","pre":[],"q":{"type":"choice","difficulty":"basic","prompt":"下面哪个字是「人」？","answer":"C","explanation":"「人」是一撇一捺，撇捺分得开。入的撇捺收得更拢，八和大都不是「人」。","choices":[{"key":"A","text":"入"},{"key":"B","text":"八"},{"key":"C","text":"人"},{"key":"D","text":"大"}]}},"cnc_p002":{"desc":"读《金木水火土》，分清土与士、木与禾，记准一二三四五和上下。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p001","k":0,"why":"按统编教材的常见教学顺序，先学「识字：天地人」，再学「识字：金木水火土」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"下面哪个字是「土」？","answer":"D","explanation":"「土」上面一横短，下面一横长。「士」正好相反，干和工的笔画也不一样。","choices":[{"key":"A","text":"士"},{"key":"B","text":"干"},{"key":"C","text":"工"},{"key":"D","text":"土"}]}},"cnc_p003":{"desc":"认识口、耳、目、手、足，读懂站如松、坐如钟、行如风、卧如弓。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p002","k":0,"why":"按统编教材的常见教学顺序，先学「识字：金木水火土」，再学「识字：口耳目手足」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一个字表示眼睛？","answer":"A","explanation":"「目」是眼睛，里面有两横。「日」是太阳，「口」是嘴巴，「耳」是耳朵。","choices":[{"key":"A","text":"目"},{"key":"B","text":"日"},{"key":"C","text":"口"},{"key":"D","text":"耳"}]}},"cnc_p004":{"desc":"用图画认识象形字日、月、山、川、水、火、田、禾，分清日与目、山与川、木与禾。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p003","k":0,"why":"按统编教材的常见教学顺序，先学「识字：口耳目手足」，再学「识字：日月山川」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一个字表示太阳？","answer":"B","explanation":"「日」是太阳。「目」是眼睛，「月」是月亮，「田」是田地。","choices":[{"key":"A","text":"目"},{"key":"B","text":"日"},{"key":"C","text":"月"},{"key":"D","text":"田"}]}},"cnc_p005":{"desc":"会说我是中国人，认识五星红旗和北京天安门，读《上学歌》，愿意读书、写字、听故事。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p004","k":0,"why":"按统编教材的常见教学顺序，先学「识字：日月山川」，再学「入学教育：我上学了」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"下面哪一句和「我是中国人」的意思一致？","answer":"C","explanation":"我是中国人，也可以说我们都是中国人。天安门和小书包都不是这句话的意思。","choices":[{"key":"A","text":"我们不是中国人"},{"key":"B","text":"我们是天安门"},{"key":"C","text":"我们都是中国人"},{"key":"D","text":"我们是小书包"}]}},"cnc_p006":{"desc":"发指令时声音洪亮、吐字清楚；听指令时认真听，再照着做。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p005","k":0,"why":"按统编教材的常见教学顺序，先学「入学教育：我上学了」，再学「语文园地一·我说你做」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"做「我说你做」时，发指令的人要怎样说话？","answer":"D","explanation":"别人要听得见、听得清，才做得对。声音太小或完全不说，游戏就做不成。","choices":[{"key":"A","text":"声音很轻，含含糊糊"},{"key":"B","text":"背对着大家不说话"},{"key":"C","text":"只做动作，一个字也不说"},{"key":"D","text":"声音洪亮，吐字清楚"}]}},"cnc_p007":{"desc":"喜欢和大人一起读图画书、讲故事，知道学了拼音就能认更多的字。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p006","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地一·我说你做」，再学「快乐读书吧：读书真快乐」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「读书真快乐」是在说什么？","answer":"A","explanation":"这一栏就是让大家感到读书快乐，愿意打开书。","choices":[{"key":"A","text":"读书是一件高兴的事"},{"key":"B","text":"书只能用来垫桌子"},{"key":"C","text":"读完书应该难过"},{"key":"D","text":"书不能打开"}]}},"cnc_p008":{"desc":"读准单韵母 a、o、e，并分清四声。","criteria":["能分辨声母、韵母和声调","能拼读常见音节"],"root":"","pre":[{"id":"cnc_p007","k":0,"why":"按统编教材的常见教学顺序，先学「快乐读书吧：读书真快乐」，再学「单韵母 a、o、e 和四声」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「妈」的第一声该怎么读？","answer":"B","explanation":"妈是第一声 mā。麻是第二声，马是第三声，骂是第四声。","choices":[{"key":"A","text":"má（麻，第二声）"},{"key":"B","text":"mā（妈，第一声）"},{"key":"C","text":"mǎ（马，第三声）"},{"key":"D","text":"mà（骂，第四声）"}]}},"cnc_p009":{"desc":"读准单韵母 i、u、ü，分清 u 和 ü。","criteria":["能分辨声母、韵母和声调","能拼读常见音节"],"root":"","pre":[{"id":"cnc_p008","k":0,"why":"按统编教材的常见教学顺序，先学「单韵母 a、o、e 和四声」，再学「单韵母 i、u、ü」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"下面哪个是单韵母 ü？","answer":"C","explanation":"鱼的韵母是 ü。乌的韵母是 u，衣的韵母是 i，鹅的韵母是 e。","choices":[{"key":"A","text":"u（乌的韵母）"},{"key":"B","text":"i（衣的韵母）"},{"key":"C","text":"ü（鱼的韵母）"},{"key":"D","text":"e（鹅的韵母）"}]}},"cnc_p010":{"desc":"认读声母 b、p、m、f，分清不送气的 b 和送气的 p。","criteria":["能分辨声母、韵母和声调","能拼读常见音节"],"root":"","pre":[{"id":"cnc_p009","k":0,"why":"按统编教材的常见教学顺序，先学「单韵母 i、u、ü」，再学「声母 b、p、m、f」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「八」的声母是哪一个？","answer":"D","explanation":"八是 bā，声母是不送气的 b。爬才是送气的 p。","choices":[{"key":"A","text":"声母 p（坡）"},{"key":"B","text":"声母 m（摸）"},{"key":"C","text":"声母 f（佛）"},{"key":"D","text":"声母 b（玻）"}]}},"cnc_p011":{"desc":"认读声母 d、t、n、l，分清不送气的 d 和送气的 t，也分清 n 和 l。","criteria":["能分辨声母、韵母和声调","能拼读常见音节"],"root":"","pre":[{"id":"cnc_p010","k":0,"why":"按统编教材的常见教学顺序，先学「声母 b、p、m、f」，再学「声母 d、t、n、l」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「大」的声母是哪一个？","answer":"A","explanation":"大是 dà，声母是不送气的 d。兔才是送气的 t。","choices":[{"key":"A","text":"声母 d（得）"},{"key":"B","text":"声母 t（特）"},{"key":"C","text":"声母 n（讷）"},{"key":"D","text":"声母 l（勒）"}]}},"cnc_p012":{"desc":"背园地里的《画》：远看山有色，近听水无声，春去花还在，人来鸟不惊。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p011","k":0,"why":"按统编教材的常见教学顺序，先学「声母 d、t、n、l」，再学「语文园地二·日积月累《画》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「远看山有色」的下一句是哪一句？","answer":"B","explanation":"先写远远看见山有颜色，接着是走近了也听不见水声。","choices":[{"key":"A","text":"春去花还在"},{"key":"B","text":"近听水无声"},{"key":"C","text":"人来鸟不惊"},{"key":"D","text":"春去花不在"}]}},"cnc_p013":{"desc":"认读声母 g、k、h，分清不送气的 g 和送气的 k。","criteria":["能分辨声母、韵母和声调","能拼读常见音节"],"root":"","pre":[{"id":"cnc_p012","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·日积月累《画》」，再学「声母 g、k、h」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「哥」的声母是哪一个？","answer":"C","explanation":"哥是 gē，声母是不送气的 g。科才是送气的 k。","choices":[{"key":"A","text":"声母 k（科）"},{"key":"B","text":"声母 h（喝）"},{"key":"C","text":"声母 g（哥）"},{"key":"D","text":"声母 d（得）"}]}},"cnc_p014":{"desc":"认读声母 j、q、x，分清它们和平舌音、翘舌音。","criteria":["能分辨声母、韵母和声调","能拼读常见音节"],"root":"","pre":[{"id":"cnc_p013","k":0,"why":"按统编教材的常见教学顺序，先学「声母 g、k、h」，再学「声母 j、q、x」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「鸡」的声母是哪一个？","answer":"D","explanation":"鸡是 jī，声母是 j。七的声母才是 q。","choices":[{"key":"A","text":"声母 q（欺）"},{"key":"B","text":"声母 x（希）"},{"key":"C","text":"声母 g（哥）"},{"key":"D","text":"声母 j（基）"}]}},"cnc_p015":{"desc":"认读平舌声母 z、c、s，读的时候舌头放平，不翘起来。","criteria":["能分辨声母、韵母和声调","能拼读常见音节"],"root":"","pre":[{"id":"cnc_p014","k":0,"why":"按统编教材的常见教学顺序，先学「声母 j、q、x」，再学「平舌声母 z、c、s」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「字」的声母是哪一个？","answer":"A","explanation":"字是平舌音 zì。翘舌音 zh 会读成「知」一类。","choices":[{"key":"A","text":"平舌声母 z"},{"key":"B","text":"翘舌声母 zh"},{"key":"C","text":"平舌声母 c"},{"key":"D","text":"平舌声母 s"}]}},"cnc_p016":{"desc":"认读翘舌声母 zh、ch、sh、r，分清和平舌音，认识整体认读音节 zhī。","criteria":["能分辨声母、韵母和声调","能拼读常见音节"],"root":"","pre":[{"id":"cnc_p015","k":0,"why":"按统编教材的常见教学顺序，先学「平舌声母 z、c、s」，再学「翘舌声母 zh、ch、sh、r」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「中国」的「中」，声母是哪一个？","answer":"B","explanation":"中的声母是翘舌音 zh。平舌音 z 舌头放平，ch 和 sh 也不是 zh。","choices":[{"key":"A","text":"平舌声母 z"},{"key":"B","text":"翘舌声母 zh"},{"key":"C","text":"翘舌声母 ch"},{"key":"D","text":"翘舌声母 sh"}]}},"cnc_p017":{"desc":"认读 y、w，知道 yi、wu、yu 是整体认读，yu 里的 u 仍读 ü。","criteria":["能分辨声母、韵母和声调","能拼读常见音节"],"root":"","pre":[{"id":"cnc_p016","k":0,"why":"按统编教材的常见教学顺序，先学「翘舌声母 zh、ch、sh、r」，再学「声母 y、w」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「鸭」的声母是哪一个？","answer":"C","explanation":"鸭是 yā，声母是 y。蛙才是 wā。","choices":[{"key":"A","text":"声母 w（乌）"},{"key":"B","text":"声母 n（讷）"},{"key":"C","text":"声母 y（衣）"},{"key":"D","text":"声母 l（勒）"}]}},"cnc_p018":{"desc":"复习整体认读音节，分清哪些要整读，哪些要把声母和韵母拼起来。","criteria":["能分辨声母、韵母和声调","能拼读常见音节"],"root":"","pre":[{"id":"cnc_p017","k":0,"why":"按统编教材的常见教学顺序，先学「声母 y、w」，再学「语文园地三·整体认读音节」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"下面哪个看到就整读，不用再拼？","answer":"D","explanation":"yī 是整体认读。bā、mā、dà 都要把声母和韵母拼出来。","choices":[{"key":"A","text":"拼读音节 bā（八）"},{"key":"B","text":"拼读音节 mā（妈）"},{"key":"C","text":"拼读音节 dà（大）"},{"key":"D","text":"整体认读音节 yī（衣）"}]}},"cnc_p019":{"desc":"分辨复韵母 ai、ei、ui 和 ao、ou、iu。","criteria":["能分辨声母、韵母和声调","能拼读常见音节"],"root":"","pre":[{"id":"cnc_p008","k":1,"why":"复韵母里有 a、o、e，要先读准这些单韵母。"},{"id":"cnc_p009","k":1,"why":"复韵母里有 i、u、ü，要先读准这三个单韵母。"},{"id":"cnc_p018","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地三·整体认读音节」，再学「复韵母 ai、ei、ui、ao、ou、iu」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「白」的韵母是哪一个？","answer":"A","explanation":"白的韵母是 ai。ei 是「杯」一类的韵母，ao 是「高」，ou 是「欧」。","choices":[{"key":"A","text":"复韵母 ai"},{"key":"B","text":"复韵母 ei"},{"key":"C","text":"复韵母 ao"},{"key":"D","text":"复韵母 ou"}]}},"cnc_p020":{"desc":"读准 ie、üe、er，知道 er 自己就是一个音节。","criteria":["能分辨声母、韵母和声调","能拼读常见音节"],"root":"","pre":[{"id":"cnc_p019","k":0,"why":"按统编教材的常见教学顺序，先学「复韵母 ai、ei、ui、ao、ou、iu」，再学「特殊韵母 ie、üe、er」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「叶」的韵母是哪一个？","answer":"B","explanation":"叶是 yè，韵母是 ie。飞的韵母才是 ei。","choices":[{"key":"A","text":"复韵母 ei"},{"key":"B","text":"复韵母 ie"},{"key":"C","text":"特殊韵母 er"},{"key":"D","text":"复韵母 üe"}]}},"cnc_p021":{"desc":"分清前鼻韵母和后鼻韵母，不把 an 和 ang、in 和 ing 读混。","criteria":["能分辨声母、韵母和声调","能拼读常见音节"],"root":"","pre":[{"id":"cnc_p020","k":0,"why":"按统编教材的常见教学顺序，先学「特殊韵母 ie、üe、er」，再学「鼻韵母 an、en、in、un、ün 和 ang、eng、ing、ong…"}],"q":{"type":"choice","difficulty":"basic","prompt":"「方」的韵母是哪一个？","answer":"C","explanation":"方是后鼻韵母 ang。an 是前鼻音，像「翻」的韵母。","choices":[{"key":"A","text":"前鼻韵母 an"},{"key":"B","text":"后鼻韵母 eng"},{"key":"C","text":"后鼻韵母 ang"},{"key":"D","text":"前鼻韵母 en"}]}},"cnc_p022":{"desc":"把声母和韵母拼成音节，分清声调，读准 j、q、x 和 ü 相拼。","criteria":["能分辨声母、韵母和声调","能拼读常见音节"],"root":"","pre":[{"id":"cnc_p016","k":1,"why":"拼读音节之前，要先认识声母，包括翘舌音 zh、ch、sh、r。"},{"id":"cnc_p014","k":1,"why":"拼读 ju、qu、xu 之前，要先认识声母 j、q、x。"},{"id":"cnc_p017","k":1,"why":"拼读 yú 这类音节之前，要先认识 y、w。"},{"id":"cnc_p019","k":1,"why":"拼读音节之前，要先认识韵母。"},{"id":"cnc_p021","k":1,"why":"拼读带鼻音的音节之前，要先认识鼻韵母。"}],"q":{"type":"choice","difficulty":"basic","prompt":"声母 b 和韵母 ā 拼出来，是哪个字的读音？","answer":"D","explanation":"b 加 ā 是第一声 bā，就是「八」。爸是第四声 bà。","choices":[{"key":"A","text":"爸（bà，第四声）"},{"key":"B","text":"拔（bá，第二声）"},{"key":"C","text":"把（bǎ，第三声）"},{"key":"D","text":"八（bā，第一声）"}]}},"cnc_p023":{"desc":"给音节标调：有 a 标 a，没 a 找 o、e，i 和 u 并列时标在后面一个。","criteria":["能分辨声母、韵母和声调","能拼读常见音节"],"root":"","pre":[{"id":"cnc_p022","k":0,"why":"按统编教材的常见教学顺序，先学「拼读音节」，再学「语文园地四·给音节标调」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「高」gāo 的声调标在哪里？","answer":"A","explanation":"韵母 ao 里有 a，声调标在 a 上，所以是 gāo。","choices":[{"key":"A","text":"标在 a 上"},{"key":"B","text":"标在 o 上"},{"key":"C","text":"标在 g 上"},{"key":"D","text":"这个音节不标声调"}]}},"cnc_p024":{"desc":"借助拼音读懂《秋天》：树叶黄了，大雁往南飞。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p022","k":1,"why":"借助拼音读课文之前，要先会拼读音节。"},{"id":"cnc_p023","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地四·给音节标调」，再学「阅读《秋天》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《秋天》里，树叶变成了什么颜色，然后怎样了？","answer":"B","explanation":"课文写天气凉了，树叶黄了，一片片叶子从树上落下来。","choices":[{"key":"A","text":"变红了，还长在树上"},{"key":"B","text":"变黄了，从树上落下来"},{"key":"C","text":"变绿了，越长越多"},{"key":"D","text":"变成白色，飞到天上"}]}},"cnc_p025":{"desc":"读汉乐府《江南》，按东、西、南、北的顺序记住鱼戏莲叶的句子。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p024","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《秋天》」，再学「阅读《江南》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「鱼戏莲叶间」的下一句是哪一句？","answer":"C","explanation":"课文接着按东、西、南、北来写，紧跟着的是「鱼戏莲叶东」。","choices":[{"key":"A","text":"鱼戏莲叶西"},{"key":"B","text":"鱼戏莲叶南"},{"key":"C","text":"鱼戏莲叶东"},{"key":"D","text":"鱼戏莲叶北"}]}},"cnc_p026":{"desc":"读《雪地里的小画家》，对上小鸡、小狗、小鸭、小马画的图案，知道青蛙在洞里睡觉。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p025","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《江南》」，再学「阅读《雪地里的小画家》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"小鸡画的是什么？","answer":"D","explanation":"小鸡的脚印像竹叶。梅花是小狗画的。","choices":[{"key":"A","text":"梅花"},{"key":"B","text":"枫叶"},{"key":"C","text":"月牙"},{"key":"D","text":"竹叶"}]}},"cnc_p027":{"desc":"读《四季》，把草芽、荷叶、谷穗、雪人和春夏秋冬对上。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p026","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《雪地里的小画家》」，再学「阅读《四季》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"草芽尖尖，他对小鸟说自己是哪个季节？","answer":"A","explanation":"草芽尖尖说：我是春天。荷叶才说自己是夏天。","choices":[{"key":"A","text":"春天"},{"key":"B","text":"夏天"},{"key":"C","text":"秋天"},{"key":"D","text":"冬天"}]}},"cnc_p028":{"desc":"在园地里把话说完整：说清谁、在哪里、做什么。","criteria":["能把句子写通顺","能按要求选用或修改句子"],"root":"","pre":[{"id":"cnc_p001","k":1,"why":"把汉字连成句子之前，要先认识句中的常用字。"},{"id":"cnc_p027","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《四季》」，再学「语文园地五·把话说完整」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一句把意思说完整了？","answer":"B","explanation":"完整的句子要说出谁、在哪里、做什么。只说一个词还不完整。","choices":[{"key":"A","text":"小鸭。"},{"key":"B","text":"小鸭在河里游泳。"},{"key":"C","text":"游泳。"},{"key":"D","text":"河里。"}]}},"cnc_p029":{"desc":"读《对韵歌》，记准云对雨、雪对风、花对树、鸟对虫、山清对水秀、柳绿对桃红。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p028","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地五·把话说完整」，再学「识字：对韵歌」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「云对雨」后面紧接着的是哪一组？","answer":"C","explanation":"课文先写云对雨、雪对风，再写花对树、鸟对虫。","choices":[{"key":"A","text":"花对树"},{"key":"B","text":"鸟对虫"},{"key":"C","text":"雪对风"},{"key":"D","text":"柳绿对桃红"}]}},"cnc_p030":{"desc":"用熟字合起来记新字：日月明、田力男、二人从、三木森。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p004","k":1,"why":"「日月明」要用已经认识的日、月来记。"},{"id":"cnc_p029","k":0,"why":"按统编教材的常见教学顺序，先学「识字：对韵歌」，再学「识字：日月明」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「日」和「月」合在一起是哪个字？","answer":"D","explanation":"日加月是明亮的明。朋是两个月，不要看错。","choices":[{"key":"A","text":"朋"},{"key":"B","text":"胆"},{"key":"C","text":"期"},{"key":"D","text":"明"}]}},"cnc_p031":{"desc":"认识小书包里的橡皮、尺子、作业本、笔袋，知道文具要放进书包。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p030","k":0,"why":"按统编教材的常见教学顺序，先学「识字：日月明」，再学「识字：小书包」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"下面哪一种是小书包里的文具？","answer":"A","explanation":"橡皮是文具，放在小书包里。南瓜、荷叶和石子都不是文具。","choices":[{"key":"A","text":"橡皮"},{"key":"B","text":"南瓜"},{"key":"C","text":"荷叶"},{"key":"D","text":"石子"}]}},"cnc_p032":{"desc":"读《升国旗》，知道五星红旗升起时要立正、敬礼。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p031","k":0,"why":"按统编教材的常见教学顺序，先学「识字：小书包」，再学「阅读《升国旗》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文里的国旗是哪一面旗？","answer":"B","explanation":"五星红旗是我们的国旗。彩旗、队旗、校旗都不是国旗。","choices":[{"key":"A","text":"彩旗"},{"key":"B","text":"五星红旗"},{"key":"C","text":"队旗"},{"key":"D","text":"校旗"}]}},"cnc_p033":{"desc":"在园地里分清大与小、多与少，会用一头、一只、一群、一条。","criteria":["能理解词语在句子里的意思","能选出搭配恰当的词语"],"root":"","pre":[{"id":"cnc_p032","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《升国旗》」，再学「语文园地六·大小多少与量词」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「一头黄牛」的「头」可以换成下面哪一种说法？","answer":"C","explanation":"黄牛常用「头」。鸟才常用「只」，鱼常用「条」。","choices":[{"key":"A","text":"一只黄牛也可以"},{"key":"B","text":"一条黄牛也可以"},{"key":"C","text":"一头黄牛不能改成一只黄牛"},{"key":"D","text":"一群黄牛也可以"}]}},"cnc_p034":{"desc":"读叶圣陶《小小的船》，知道弯弯的月儿像小船。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p033","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地六·大小多少与量词」，再学「阅读《小小的船》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"弯弯的月儿被比作什么？","answer":"D","explanation":"课文说弯弯的月儿小小的船。桥、树都不是这篇课文的比方。","choices":[{"key":"A","text":"小小的桥"},{"key":"B","text":"圆圆的盘"},{"key":"C","text":"高高的树"},{"key":"D","text":"小小的船"}]}},"cnc_p035":{"desc":"读《影子》，知道影子会跟着人，像一条小黑狗。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p034","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《小小的船》」，再学「阅读《影子》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文把影子比作什么？","answer":"A","explanation":"影子常常跟着我，就像一条小黑狗。","choices":[{"key":"A","text":"一条小黑狗"},{"key":"B","text":"一只小白兔"},{"key":"C","text":"一艘小船"},{"key":"D","text":"一棵大树"}]}},"cnc_p036":{"desc":"读《两件宝》，知道双手会做工、大脑会思考，用手又用脑才能有创造。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p035","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《影子》」，再学「阅读《两件宝》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"人的两件宝是什么？","answer":"B","explanation":"课文说人有两件宝，双手和大脑。书包、太阳和影子都不是这两件宝。","choices":[{"key":"A","text":"书包和铅笔"},{"key":"B","text":"双手和大脑"},{"key":"C","text":"太阳和月亮"},{"key":"D","text":"影子和小狗"}]}},"cnc_p037":{"desc":"看场合决定声音大小：有时要大声，让人听见；有时要小声，不打扰别人。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p036","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《两件宝》」，再学「语文园地七·用多大的声音」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"在图书馆里，应该怎样说话？","answer":"C","explanation":"图书馆里要安静，说话用小声。喊叫会打扰别人看书。","choices":[{"key":"A","text":"大声喊叫"},{"key":"B","text":"敲着桌子说话"},{"key":"C","text":"小声说"},{"key":"D","text":"对着别人的耳朵大叫"}]}},"cnc_p038":{"desc":"读《比尾巴》，分清猴子、兔子、松鼠、鸭子、公鸡、孔雀的尾巴。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p037","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地七·用多大的声音」，再学「阅读《比尾巴》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"谁的尾巴长？","answer":"D","explanation":"猴子的尾巴长。兔子的尾巴短，松鼠的尾巴好像一把伞。","choices":[{"key":"A","text":"兔子"},{"key":"B","text":"松鼠"},{"key":"C","text":"鸭子"},{"key":"D","text":"猴子"}]}},"cnc_p039":{"desc":"读《乌鸦喝水》，知道乌鸦把小石子放进瓶子，水升高后才喝到水。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p038","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《比尾巴》」，再学「阅读《乌鸦喝水》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"乌鸦为什么一开始喝不着水？","answer":"A","explanation":"瓶子里有水，但是水不多，瓶口又小，嘴伸不进去。","choices":[{"key":"A","text":"瓶里水不多，瓶口又小"},{"key":"B","text":"瓶子里一滴水也没有"},{"key":"C","text":"瓶口太大，水都洒了"},{"key":"D","text":"水是热的，不能喝"}]}},"cnc_p040":{"desc":"读《雨点儿》，分清小雨点儿去有花有草的地方，大雨点儿去没有花没有草的地方。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p039","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《乌鸦喝水》」，再学「阅读《雨点儿》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"小雨点儿要到哪里去？","answer":"B","explanation":"小雨点儿说：我要去有花有草的地方。没有花草的地方是大雨点儿去的。","choices":[{"key":"A","text":"没有花没有草的地方"},{"key":"B","text":"有花有草的地方"},{"key":"C","text":"雪地里"},{"key":"D","text":"瓶子里"}]}},"cnc_p041":{"desc":"在园地里看图，按顺序说出谁在哪里、先做什么、后做什么。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p028","k":1,"why":"看图按顺序说之前，要先会说完整的句子。"},{"id":"cnc_p040","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《雨点儿》」，再学「语文园地八·看图说出谁在做什么」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"看图：小朋友先洗手，再吃饭。哪一种说法有顺序？","answer":"C","explanation":"先、然后把两件事的次序说清楚。只说一个词还不清楚。","choices":[{"key":"A","text":"他吃饭洗手。"},{"key":"B","text":"吃饭。"},{"key":"C","text":"他先洗手，然后吃饭。"},{"key":"D","text":"先吃饭，洗手没有说"}]}},"cnc_p042":{"desc":"认识春夏秋冬，会配春风吹、夏雨落、秋霜降、冬雪飘。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p041","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地八·看图说出谁在做什么」，再学「识字：春夏秋冬」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「秋霜降」的「霜」最常出现在哪个季节？","answer":"D","explanation":"霜出现在天冷的时候。课文把它和秋天、冬天放在一起，不和夏天放在一起。","choices":[{"key":"A","text":"夏天中午"},{"key":"B","text":"春天开花时"},{"key":"C","text":"每天下午"},{"key":"D","text":"秋天到冬天的寒冷时候"}]}},"cnc_p043":{"desc":"读《姓氏歌》，会用熟字记李、张、胡、吴等常见姓。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p042","k":0,"why":"按统编教材的常见教学顺序，先学「识字：春夏秋冬」，再学「识字：姓氏歌」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「木子李」的「李」是哪两个部分合成的？","answer":"A","explanation":"木加子是李。弓加长是张，古加月是胡，口加天是吴。","choices":[{"key":"A","text":"木和子"},{"key":"B","text":"弓和长"},{"key":"C","text":"古和月"},{"key":"D","text":"口和天"}]}},"cnc_p044":{"desc":"读《小青蛙》，分清清、晴、睛、情、请，知道青蛙保护禾苗。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p001","k":1,"why":"读《小青蛙》里的清、晴、睛、情、请之前，要先认识一批独体字。"},{"id":"cnc_p043","k":0,"why":"按统编教材的常见教学顺序，先学「识字：姓氏歌」，再学「识字：小青蛙」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《小青蛙》里，小青蛙做了什么好事情？","answer":"B","explanation":"诗里写它保护禾苗、吃害虫，做了不少好事情。","choices":[{"key":"A","text":"把禾苗咬坏"},{"key":"B","text":"保护禾苗，吃害虫"},{"key":"C","text":"只在河里睡觉"},{"key":"D","text":"让禾苗生病"}]}},"cnc_p045":{"desc":"读《猜字谜》，能根据偏旁猜出秋、请、情、晴、清。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p044","k":1,"why":"猜请、情、晴、清之前，要先在《小青蛙》里分清这些字。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「左边绿，右边红，左右相遇起凉风」打的是哪个字？","answer":"C","explanation":"左边禾苗绿，右边火红，合起来是秋。凉风也和秋天有关。","choices":[{"key":"A","text":"春"},{"key":"B","text":"明"},{"key":"C","text":"秋"},{"key":"D","text":"花"}]}},"cnc_p046":{"desc":"请人帮忙时说清请谁、帮什么，用上请和谢谢。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p045","k":0,"why":"按统编教材的常见教学顺序，先学「识字：猜字谜」，再学「口语交际：请你帮个忙」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"铅笔滚到桌下，想请同学帮忙。哪一种说法最合适？","answer":"D","explanation":"先说请，再说清帮什么忙，最后道谢。命令别人，或只说一个词，对方不知道该怎样帮。","choices":[{"key":"A","text":"你必须马上给我捡！"},{"key":"B","text":"铅笔。"},{"key":"C","text":"不许你捡。"},{"key":"D","text":"请你帮我捡一下铅笔，谢谢！"}]}},"cnc_p047":{"desc":"喜欢读童谣和儿歌，能按节奏朗读，并读给别人听。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p046","k":0,"why":"按统编教材的常见教学顺序，先学「口语交际：请你帮个忙」，再学「快乐读书吧：读读童谣和儿歌」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"童谣和儿歌最明显的特点是什么？","answer":"A","explanation":"童谣、儿歌句子短，常常押韵，适合朗读。","choices":[{"key":"A","text":"句子短，有节奏，读起来顺口"},{"key":"B","text":"每一句都很长，听不出节奏"},{"key":"C","text":"只能默写，不能出声读"},{"key":"D","text":"必须换成古文才算读过"}]}},"cnc_p048":{"desc":"读《热爱中国共产党》，说出课文表达的感情，不把它和旁边的课文记成同一篇。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p047","k":0,"why":"按统编教材的常见教学顺序，先学「快乐读书吧：读读童谣和儿歌」，再学「阅读《热爱中国共产党》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《热爱中国共产党》主要表达什么？","answer":"B","explanation":"题目和课文都在说热爱中国共产党，不是包粽子或借尾巴。","choices":[{"key":"A","text":"怎样包粽子"},{"key":"B","text":"对中国共产党的热爱"},{"key":"C","text":"小壁虎向谁借尾巴"},{"key":"D","text":"荷叶像摇篮"}]}},"cnc_p049":{"desc":"读懂沙洲坝的井是谁带领挖的，石碑上刻着什么。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p024","k":1,"why":"读稍长的故事之前，要先会借助拼音读懂短课文。"},{"id":"cnc_p048","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《热爱中国共产党》」，再学「阅读《吃水不忘挖井人》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这口井在什么地方？","answer":"C","explanation":"课文写瑞金城外有个村子叫沙洲坝，井就挖在那里。","choices":[{"key":"A","text":"北京的学校"},{"key":"B","text":"江南的荷塘"},{"key":"C","text":"瑞金城外的沙洲坝"},{"key":"D","text":"井里没有村子"}]}},"cnc_p050":{"desc":"读懂「我」想看天安门升旗，也想看天山的雪莲。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p049","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《吃水不忘挖井人》」，再学「阅读《我多想去看看》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"妈妈说，沿着弯弯的小路会走出哪里？","answer":"D","explanation":"妈妈说沿着弯弯的小路就会走出天山，远处是北京。","choices":[{"key":"A","text":"走出北京"},{"key":"B","text":"走出荷塘"},{"key":"C","text":"走出操场"},{"key":"D","text":"走出天山"}]}},"cnc_p051":{"desc":"分清青、清、请、晴、情，按偏旁选出要用的字。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p044","k":1,"why":"在园地里比较清、请、晴、情之前，要先在《小青蛙》里认识这些字。"},{"id":"cnc_p050","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《我多想去看看》」，再学「语文园地二·形近字和同音字」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「河水很清」该用哪个字？","answer":"A","explanation":"清水的清是三点水。青草的青没有三点水，请是言字旁，晴是日字旁。","choices":[{"key":"A","text":"清"},{"key":"B","text":"青"},{"key":"C","text":"请"},{"key":"D","text":"晴"}]}},"cnc_p052":{"desc":"读懂小公鸡会捉虫、小鸭子会游泳，他们互相帮助。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p051","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·形近字和同音字」，再学「阅读《小公鸡和小鸭子》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"在草堆旁，谁捉到了虫子？","answer":"B","explanation":"小公鸡的嘴尖，能捉虫子。小鸭子的嘴是扁的，捉不到虫子。","choices":[{"key":"A","text":"小鸭子"},{"key":"B","text":"小公鸡"},{"key":"C","text":"小壁虎"},{"key":"D","text":"小鱼"}]}},"cnc_p053":{"desc":"读懂从前只有一棵树、一只喜鹊时很孤单，后来有了邻居就快乐了。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p052","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《小公鸡和小鸭子》」，再学「阅读《树和喜鹊》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"从前这里有多少棵树、多少只喜鹊？","answer":"C","explanation":"从前只有一棵树，树上只有一个鸟窝、一只喜鹊。","choices":[{"key":"A","text":"很多树，很多喜鹊"},{"key":"B","text":"没有树，也没有喜鹊"},{"key":"C","text":"一棵树，一只喜鹊"},{"key":"D","text":"两棵树，三只喜鹊"}]}},"cnc_p054":{"desc":"读懂一个人玩也有趣，和大家一起玩更快乐。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p053","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《树和喜鹊》」，再学「阅读《怎么都快乐》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文觉得一个人玩怎么样？","answer":"D","explanation":"一个人玩，很好。许多人一起玩，课文说更快乐，不是说独自玩不算快乐。","choices":[{"key":"A","text":"一个人玩就完全不算快乐"},{"key":"B","text":"一个人玩是被禁止的"},{"key":"C","text":"一个人玩一定比许多人玩更快乐"},{"key":"D","text":"也很好，可以安安静静做自己的事"}]}},"cnc_p055":{"desc":"打电话先问好、说自己是谁，把事情说清楚，结束时说再见。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p054","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《怎么都快乐》」，再学「口语交际：打电话」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"打电话时，哪一种开头最合适？","answer":"A","explanation":"先问好，再说自己是谁。不报名、一上来就命令，对方不知道是谁。","choices":[{"key":"A","text":"喂，你好，我是小明"},{"key":"B","text":"你是谁，快说"},{"key":"C","text":"什么也不说就把电话挂了"},{"key":"D","text":"不报自己的名字就命令对方"}]}},"cnc_p056":{"desc":"背诵李白《静夜思》，不把字句和《古朗月行》记混。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p034","k":1,"why":"背《静夜思》之前，要先读过写月亮的《小小的船》，才不会把弯弯的月儿和床前明月装成同一篇。"},{"id":"cnc_p055","k":0,"why":"按统编教材的常见教学顺序，先学「口语交际：打电话」，再学「古诗《静夜思》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「床前明月光」的下一句是哪一句？","answer":"B","explanation":"先以为地上铺了一层霜，后面才是举头、低头。白玉盘是《古朗月行》里的。","choices":[{"key":"A","text":"呼作白玉盘"},{"key":"B","text":"疑是地上霜"},{"key":"C","text":"低头思故乡"},{"key":"D","text":"举头望明月"}]}},"cnc_p057":{"desc":"读《夜色》，知道小朋友从害怕黑夜到变得勇敢。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p056","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《静夜思》」，再学「阅读《夜色》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"故事开头，小朋友是什么样的？","answer":"C","explanation":"他从前胆子很小很小，天一黑就不敢往外瞧。","choices":[{"key":"A","text":"胆子很大，天天夜里出去跑"},{"key":"B","text":"已经不怕任何黑夜"},{"key":"C","text":"胆子很小，天一黑就不敢往外瞧"},{"key":"D","text":"白天也不敢睁眼"}]}},"cnc_p058":{"desc":"读懂粽子是用箬叶包的，端午节赛龙舟、吃粽子是为了纪念屈原。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p057","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《夜色》」，再学「阅读《端午粽》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文里，粽子外面是用什么包的？","answer":"D","explanation":"粽子用青青的箬叶包着，里面是白白的糯米。","choices":[{"key":"A","text":"红红的塑料纸"},{"key":"B","text":"厚厚的棉布"},{"key":"C","text":"硬硬的铁皮"},{"key":"D","text":"青青的箬叶"}]}},"cnc_p059":{"desc":"能按句子的意思选用句号、问号和感叹号。","criteria":["能把句子写通顺","能按要求选用或修改句子"],"root":"","pre":[{"id":"cnc_p028","k":1,"why":"给句子加标点之前，要先会说完整的句子。"},{"id":"cnc_p058","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《端午粽》」，再学「语文园地四·标点与词语」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「你叫什么名字」这句话末尾该用哪一个？","answer":"A","explanation":"这是在提问，末尾用问号。","choices":[{"key":"A","text":"问号（？）"},{"key":"B","text":"句号（。）"},{"key":"C","text":"感叹号（！）"},{"key":"D","text":"逗号（，）"}]}},"cnc_p060":{"desc":"读《动物儿歌》，对上蜻蜓、蝴蝶、蚯蚓、蚂蚁、蝌蚪、蜘蛛各在做什么。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p059","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地四·标点与词语」，再学「识字：动物儿歌」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"谁在半空展翅飞？","answer":"B","explanation":"蜻蜓半空展翅飞。蚯蚓在土里，蚂蚁在地上，蝌蚪在池中。","choices":[{"key":"A","text":"蚯蚓"},{"key":"B","text":"蜻蜓"},{"key":"C","text":"蚂蚁"},{"key":"D","text":"蝌蚪"}]}},"cnc_p061":{"desc":"读《古对今》，记准古对今、严寒对酷暑、和风对细雨这些对子。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p060","k":0,"why":"按统编教材的常见教学顺序，先学「识字：动物儿歌」，再学「识字：古对今」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「古对今」后面紧接着的是哪一组？","answer":"C","explanation":"课文先写古对今、圆对方，后面才是严寒对酷暑。","choices":[{"key":"A","text":"严寒对酷暑"},{"key":"B","text":"晨对暮"},{"key":"C","text":"圆对方"},{"key":"D","text":"桃对李"}]}},"cnc_p062":{"desc":"读《操场上》，分清提手旁的拍、拔、打和足字旁的跳、跑、踢。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p061","k":0,"why":"按统编教材的常见教学顺序，先学「识字：古对今」，再学「识字：操场上」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「打、拔、拍」这三个字都是什么旁？","answer":"D","explanation":"打、拔、拍都和手的动作有关，是提手旁。","choices":[{"key":"A","text":"足字旁"},{"key":"B","text":"言字旁"},{"key":"C","text":"三点水"},{"key":"D","text":"提手旁"}]}},"cnc_p063":{"desc":"读《三字经》节选，背准人之初、性本善、子不学、玉不琢。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p062","k":0,"why":"按统编教材的常见教学顺序，先学「识字：操场上」，再学「识字：《人之初》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「人之初」的下一句是哪一句？","answer":"A","explanation":"人之初，性本善。性相近、习相远是后面的句子。","choices":[{"key":"A","text":"性本善"},{"key":"B","text":"习相远"},{"key":"C","text":"非所宜"},{"key":"D","text":"不知义"}]}},"cnc_p064":{"desc":"邀请别人一起玩时说清规则，玩的时候轮流、守规则。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p063","k":0,"why":"按统编教材的常见教学顺序，先学「识字：《人之初》」，再学「口语交际：一起做游戏」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"邀请别人一起玩，哪一句最合适？","answer":"B","explanation":"先发出邀请，态度客气。只说一个词，别人不知道玩什么。","choices":[{"key":"A","text":"不许你玩"},{"key":"B","text":"我们一起做游戏，好吗"},{"key":"C","text":"你不能问规则"},{"key":"D","text":"游戏"}]}},"cnc_p065":{"desc":"背诵白居易《池上》，知道小娃采莲后浮萍留下了一道痕迹。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p064","k":0,"why":"按统编教材的常见教学顺序，先学「口语交际：一起做游戏」，再学「古诗《池上》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「小娃撑小艇」的下一句是哪一句？","answer":"C","explanation":"小娃撑着小船，偷偷采了白莲回去。浮萍一道开是最后一句。","choices":[{"key":"A","text":"浮萍一道开"},{"key":"B","text":"不解藏踪迹"},{"key":"C","text":"偷采白莲回"},{"key":"D","text":"早有蜻蜓立上头"}]}},"cnc_p066":{"desc":"背诵杨万里《小池》，分清它和白居易《池上》不是同一首。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p065","k":1,"why":"背《小池》之前，要先会背《池上》，才不会把偷采白莲和蜻蜓立上头记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「泉眼无声惜细流」的下一句是哪一句？","answer":"D","explanation":"先写泉眼和树阴，后两句才是小荷和蜻蜓。偷采白莲回是《池上》。","choices":[{"key":"A","text":"小荷才露尖尖角"},{"key":"B","text":"早有蜻蜓立上头"},{"key":"C","text":"偷采白莲回"},{"key":"D","text":"树阴照水爱晴柔"}]}},"cnc_p067":{"desc":"读懂浪花在沙滩上给脚丫挠痒，小朋友觉得又痒又想笑。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p066","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《小池》」，再学「阅读《浪花》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《浪花》里，「我」在哪里玩？","answer":"A","explanation":"小朋友走在沙滩上，浪花才跑到脚边来。","choices":[{"key":"A","text":"海边的沙滩上"},{"key":"B","text":"高山的雪地上"},{"key":"C","text":"教室的铅笔盒里"},{"key":"D","text":"端午节的龙舟上"}]}},"cnc_p068":{"desc":"读《荷叶圆圆》，分清小水珠、小蜻蜓、小青蛙、小鱼儿各把荷叶当成什么。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p067","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《浪花》」，再学「阅读《荷叶圆圆》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"小水珠说，荷叶是自己的什么？","answer":"B","explanation":"小水珠躺在荷叶上，说荷叶是我的摇篮。","choices":[{"key":"A","text":"停机坪"},{"key":"B","text":"摇篮"},{"key":"C","text":"歌台"},{"key":"D","text":"凉伞"}]}},"cnc_p069":{"desc":"读懂燕子低飞、小鱼透气、蚂蚁搬家，都是要下雨的迹象。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p068","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《荷叶圆圆》」，再学「阅读《要下雨了》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"燕子为什么飞得很低？","answer":"C","explanation":"空气潮湿，虫子翅膀沾了小水珠，飞不高。燕子正忙着低飞捉虫。","choices":[{"key":"A","text":"燕子的翅膀断了"},{"key":"B","text":"燕子在和小白兔比赛爬行"},{"key":"C","text":"要下雨了，虫子飞不高，燕子低飞捉虫"},{"key":"D","text":"天太干，燕子飞不起来"}]}},"cnc_p070":{"desc":"会用只、条、朵、头等量词，并读懂高高兴兴这类重叠词。","criteria":["能理解词语在句子里的意思","能选出搭配恰当的词语"],"root":"","pre":[{"id":"cnc_p033","k":1,"why":"继续积累量词之前，要先会用一头、一只、一条。"},{"id":"cnc_p069","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《要下雨了》」，再学「语文园地六·量词和重叠词」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「一（ ）鱼」横线处最合适的是哪一个？","answer":"D","explanation":"鱼常用「条」。青蛙常用「只」，花常用「朵」，牛常用「头」。","choices":[{"key":"A","text":"只"},{"key":"B","text":"朵"},{"key":"C","text":"头"},{"key":"D","text":"条"}]}},"cnc_p071":{"desc":"读《文具的家》，知道铅笔盒就是文具的家。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p070","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地六·量词和重叠词」，再学「阅读《文具的家》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"贝贝的铅笔和橡皮为什么常常不见？","answer":"A","explanation":"贝贝总是随手一放，所以文具常常找不着。","choices":[{"key":"A","text":"用完没有放回固定的地方"},{"key":"B","text":"文具自己跑出去玩"},{"key":"C","text":"妈妈把文具藏起来了"},{"key":"D","text":"铅笔盒太小，放不进去"}]}},"cnc_p072":{"desc":"读《一分钟》，知道元元多睡一分钟，到校晚了二十分钟。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p071","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《文具的家》」，再学「阅读《一分钟》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"元元早上多睡了多久？","answer":"B","explanation":"他打着哈欠说再睡一分钟。迟到二十分钟是后来的结果。","choices":[{"key":"A","text":"二十分钟"},{"key":"B","text":"一分钟"},{"key":"C","text":"一个小时"},{"key":"D","text":"一整天"}]}},"cnc_p073":{"desc":"读懂通知要说清什么事、什么时间、什么地点，大家才来得了。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p072","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《一分钟》」，再学「阅读《动物王国开大会》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"狗熊用喇叭叫大家来做什么？","answer":"C","explanation":"老虎让狗熊通知大家来开大会，不是去摘桃子或踢球。","choices":[{"key":"A","text":"一起去摘桃子"},{"key":"B","text":"帮棉花姑娘捉蚜虫"},{"key":"C","text":"参加动物王国的大会"},{"key":"D","text":"到操场上踢足球"}]}},"cnc_p074":{"desc":"读懂小猴子看见一样扔一样，最后空着手回家。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p073","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《动物王国开大会》」，再学「阅读《小猴子下山》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"小猴子下山，最先拿到的是什么？","answer":"D","explanation":"他先到玉米地，掰了一个玉米扛着走。桃子、西瓜和兔子都是后来看见的。","choices":[{"key":"A","text":"一个桃子"},{"key":"B","text":"一个西瓜"},{"key":"C","text":"一只兔子"},{"key":"D","text":"一个玉米"}]}},"cnc_p075":{"desc":"听故事时安静听完；讲故事时按顺序说清谁做了什么、结果怎样。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p074","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《小猴子下山》」，再学「口语交际：听故事，讲故事」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"听别人讲故事时，哪一种做法合适？","answer":"A","explanation":"先听清楚，才讲得出来。唱歌、捂耳朵，就没有在听。","choices":[{"key":"A","text":"安静地听完，不随便插话"},{"key":"B","text":"一边听一边大声唱歌"},{"key":"C","text":"没听完就抢着说别的事"},{"key":"D","text":"把耳朵捂住"}]}},"cnc_p076":{"desc":"读懂燕子、啄木鸟、青蛙帮不了棉花姑娘，七星瓢虫吃掉了蚜虫。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p075","k":0,"why":"按统编教材的常见教学顺序，先学「口语交际：听故事，讲故事」，再学「阅读《棉花姑娘》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"棉花姑娘身上长了什么，所以很难受？","answer":"B","explanation":"她的叶子上长了蚜虫。七星瓢虫是后来来帮她的，不是害虫。","choices":[{"key":"A","text":"七星瓢虫"},{"key":"B","text":"蚜虫"},{"key":"C","text":"小鱼"},{"key":"D","text":"燕子"}]}},"cnc_p077":{"desc":"读懂「咕咚」是木瓜掉进湖里的声音，不是怪物。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p076","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《棉花姑娘》」，再学「阅读《咕咚》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「咕咚」一声到底是什么？","answer":"C","explanation":"木瓜熟了，从树上掉进湖里，才发出咕咚一声。","choices":[{"key":"A","text":"一只叫咕咚的怪物"},{"key":"B","text":"兔子在喊救命"},{"key":"C","text":"熟木瓜掉进湖里发出的声音"},{"key":"D","text":"野牛在发脾气"}]}},"cnc_p078":{"desc":"读懂小壁虎向谁借尾巴、为什么借不到，以及后来长出了新尾巴。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p077","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《咕咚》」，再学「阅读《小壁虎借尾巴》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"小壁虎的尾巴是怎么断的？","answer":"D","explanation":"小壁虎在墙角捉蚊子，一条蛇咬住了它的尾巴，它挣断尾巴逃走了。","choices":[{"key":"A","text":"他自己剪掉的"},{"key":"B","text":"被小鱼借走了"},{"key":"C","text":"在河里游泳时掉了"},{"key":"D","text":"被蛇咬住，他一挣，尾巴断了"}]}},"cnc_p079":{"desc":"看图按顺序说清楚谁在哪里、先做什么、结果怎样。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p041","k":1,"why":"看图把事情说清楚之前，要先会按顺序说出谁在做什么。"},{"id":"cnc_p078","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《小壁虎借尾巴》」，再学「语文园地八·看图把事情说清楚」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"看图：小朋友先把文具放进铅笔盒，再背上书包。哪一种说法有顺序？","answer":"A","explanation":"先、然后把两步说清楚。只说一个词，别人不知道发生了什么。","choices":[{"key":"A","text":"他先放好文具，然后背上书包。"},{"key":"B","text":"他书包文具。"},{"key":"C","text":"然后先放文具。"},{"key":"D","text":"只说「书包」。"}]}},"cnc_p080":{"desc":"按顺序说清小蝌蚪先问谁、后来怎样找到青蛙妈妈。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p079","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地八·看图把事情说清楚」，再学「阅读《小蝌蚪找妈妈》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"鲤鱼阿姨说，蝌蚪的妈妈是什么样的？","answer":"B","explanation":"鲤鱼说：你们的妈妈四条腿，宽嘴巴。乌龟才有壳。","choices":[{"key":"A","text":"长脖子，尖嘴巴"},{"key":"B","text":"四条腿，宽嘴巴"},{"key":"C","text":"没有腿，圆壳"},{"key":"D","text":"两只大翅膀"}]}},"cnc_p081":{"desc":"读懂「我」就是水，能变成云、雨、冰雹和雪，有时温和，有时暴躁。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p080","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《小蝌蚪找妈妈》」，再学「阅读《我是什么》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文里的「我」到底是什么？","answer":"C","explanation":"太阳一晒变成汽，再变成云、雨、冰雹和雪。最后一句说：其实我就是水。","choices":[{"key":"A","text":"风"},{"key":"B","text":"太阳"},{"key":"C","text":"水"},{"key":"D","text":"石头"}]}},"cnc_p082":{"desc":"读懂蒲公英、苍耳、豌豆传播种子的办法不一样。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p081","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《我是什么》」，再学「阅读《植物妈妈有办法》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"蒲公英靠什么传播种子？","answer":"D","explanation":"蒲公英的孩子只要有风轻轻吹过，就乘着风出发。","choices":[{"key":"A","text":"太阳把豆荚晒炸"},{"key":"B","text":"动物的皮毛"},{"key":"C","text":"自己爬进泥土"},{"key":"D","text":"风"}]}},"cnc_p083":{"desc":"介绍动物时说出它有趣的地方。日积月累背王安石《梅花》：墙角数枝梅，凌寒独自开。遥知不是雪，为有暗香来。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p082","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《植物妈妈有办法》」，再学「语文园地一·有趣的动物」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"向同学介绍一种有趣的动物，哪一种说法清楚？","answer":"A","explanation":"口语交际要说出是什么动物、哪里有趣。只说「喜欢」或「有趣」，别人听不出样子。","choices":[{"key":"A","text":"长颈鹿脖子很长，能吃到高处的叶子"},{"key":"B","text":"我喜欢。"},{"key":"C","text":"动物很好。"},{"key":"D","text":"它有趣，别的我保密"}]}},"cnc_p084":{"desc":"知道童话里常有会说话的角色和想象出来的事，读完愿意讲给别人听。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p083","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地一·有趣的动物」，再学「快乐读书吧：读读童话故事」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"童话故事里常常有什么？","answer":"B","explanation":"童话用想象讲故事。课程表、白纸和账单都不是童话。","choices":[{"key":"A","text":"只抄当天的课程表"},{"key":"B","text":"会说话的动物，或想象出来的奇事"},{"key":"C","text":"一张没有字的白纸"},{"key":"D","text":"只写数字的账单"}]}},"cnc_p085":{"desc":"读《场景歌》，配准一条帆船、一艘军舰、一处港湾、一座石桥这些量词。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p084","k":0,"why":"按统编教材的常见教学顺序，先学「快乐读书吧：读读童话故事」，再学「识字：《场景歌》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「一艘军舰」旁边配的是哪一个？","answer":"C","explanation":"一只海鸥，一条帆船。一艘军舰，一处港湾。帆船不跟军舰配在一起。","choices":[{"key":"A","text":"一条帆船"},{"key":"B","text":"一方鱼塘"},{"key":"C","text":"一处港湾"},{"key":"D","text":"一群飞鸟"}]}},"cnc_p086":{"desc":"读《树之歌》，分清杨树、榕树、梧桐、枫树、松柏的特点。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p062","k":1,"why":"按偏旁记住树名之前，要先会分辨提手旁和足字旁。"},{"id":"cnc_p085","k":0,"why":"按统编教材的常见教学顺序，先学「识字：《场景歌》」，再学「识字：《树之歌》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"梧桐的叶子像什么？","answer":"D","explanation":"课文说梧桐树叶像手掌。","choices":[{"key":"A","text":"一把伞"},{"key":"B","text":"一根针"},{"key":"C","text":"圆圆的饼"},{"key":"D","text":"手掌"}]}},"cnc_p087":{"desc":"读《拍手歌》，对上孔雀、雁群、熊猫和「保护动物是大事」。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p086","k":0,"why":"按统编教材的常见教学顺序，先学「识字：《树之歌》」，再学「识字：《拍手歌》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「你拍二，我拍二」后面说的是什么？","answer":"A","explanation":"拍二写孔雀和锦鸡。熊猫是拍七，雁群是拍四。","choices":[{"key":"A","text":"孔雀锦鸡是伙伴"},{"key":"B","text":"竹林熊猫在嬉戏"},{"key":"C","text":"天空雁群会写字"},{"key":"D","text":"保护动物是大事"}]}},"cnc_p088":{"desc":"读《田家四季歌》，分清春夏秋冬田里的景象和农事。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p087","k":0,"why":"按统编教材的常见教学顺序，先学「识字：《拍手歌》」，再学「识字：《田家四季歌》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"春季里，课文写了哪些景象？","answer":"B","explanation":"春季是花开、草长、蝴蝶飞。稻谷是秋季，采桑养蚕、插秧是夏季。","choices":[{"key":"A","text":"稻上场，谷像黄金"},{"key":"B","text":"春风吹，花开草长蝴蝶飞，麦苗嫩，桑叶肥"},{"key":"C","text":"雪初晴，穿上新棉衣"},{"key":"D","text":"采桑养蚕又插秧"}]}},"cnc_p089":{"desc":"能说出常见词语的反义词，不把意思相近的词当成反义词。","criteria":["能理解词语在句子里的意思","能选出搭配恰当的词语"],"root":"","pre":[{"id":"cnc_p033","k":1,"why":"学习反义词之前，要先分清大与小、多与少。"},{"id":"cnc_p088","k":0,"why":"按统编教材的常见教学顺序，先学「识字：《田家四季歌》」，再学「语文园地二·反义词」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「高」说的是个子时，反义词是哪一个？","answer":"C","explanation":"高和矮相反。长的反义词是短，大的反义词是小。","choices":[{"key":"A","text":"低一点"},{"key":"B","text":"长"},{"key":"C","text":"矮"},{"key":"D","text":"大"}]}},"cnc_p090":{"desc":"按木字旁、草字头、三点水、足字旁给生字归类。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p001","k":1,"why":"按偏旁归类之前，要先认识木、水、火这类独体字。"},{"id":"cnc_p089","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·反义词」，再学「语文园地二·偏旁归类」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「树、林、枝」共有的偏旁是哪一个？","answer":"D","explanation":"树、林、枝都和树木有关，偏旁是木。","choices":[{"key":"A","text":"草字头"},{"key":"B","text":"三点水"},{"key":"C","text":"口字旁"},{"key":"D","text":"木字旁"}]}},"cnc_p091":{"desc":"读懂雨后的彩虹被想成一座桥，「我」想帮爸爸、妈妈和哥哥。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p090","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·偏旁归类」，再学「阅读《彩虹》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"天上那座美丽的桥指的是什么？","answer":"A","explanation":"雨停了，天上有一座美丽的桥。那是彩虹，不是真的能走上去的桥。","choices":[{"key":"A","text":"雨停后出现的彩虹"},{"key":"B","text":"门前树上的秋千"},{"key":"C","text":"妈妈的镜子"},{"key":"D","text":"爸爸的水壶"}]}},"cnc_p092":{"desc":"读懂外婆家在山脚下，有吃的、玩的、看的，「我」觉得那里最有乐趣。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p091","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《彩虹》」，再学「阅读《去外婆家》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「我」小时候最大的乐趣是什么？外婆家在哪里？","answer":"B","explanation":"开头就说：小时候，我最大的乐趣就是去外婆家。外婆的家在山脚下。","choices":[{"key":"A","text":"去学校。家在海边"},{"key":"B","text":"去外婆家。家在山脚下"},{"key":"C","text":"去黄山。家在城市中心"},{"key":"D","text":"去井里看天。家在树上"}]}},"cnc_p093":{"desc":"读懂张衡夜里数星星，听爷爷讲北斗七星绕着北极星转，自己又起来看。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p092","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《去外婆家》」，再学「阅读《数星星的孩子》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"数星星的孩子是谁？","answer":"C","explanation":"课文末尾说：这个数星星的孩子名叫张衡，是汉朝人。他后来成了天文学家。","choices":[{"key":"A","text":"周总理"},{"key":"B","text":"李白"},{"key":"C","text":"张衡，汉朝人"},{"key":"D","text":"刘胡兰"}]}},"cnc_p094":{"desc":"能按问题把句子补成谁做什么、怎么样。","criteria":["能把句子写通顺","能按要求选用或修改句子"],"root":"","pre":[{"id":"cnc_p059","k":1,"why":"把句子补充完整之前，要先分清陈述、提问和感叹。"},{"id":"cnc_p093","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《数星星的孩子》」，再学「语文园地三·把句子补充完整」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「弟弟____。」哪一种补法使句子完整？","answer":"D","explanation":"要补出在哪里、做什么，不能只重复一个词。","choices":[{"key":"A","text":"弟弟"},{"key":"B","text":"跑"},{"key":"C","text":"操场"},{"key":"D","text":"在操场上跑步"}]}},"cnc_p095":{"desc":"背诵王之涣《登鹳雀楼》，不把「千里目」写成「千里眼」。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p065","k":1,"why":"背诵五言绝句《登鹳雀楼》之前，要先会背《池上》，才不会把句子串到别的诗里。"},{"id":"cnc_p094","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地三·把句子补充完整」，再学「古诗《登鹳雀楼》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「白日依山尽」的下一句是哪一句？","answer":"A","explanation":"先写太阳靠着山落下，黄河流向大海，后面才是欲穷千里目。","choices":[{"key":"A","text":"黄河入海流"},{"key":"B","text":"欲穷千里目"},{"key":"C","text":"更上一层楼"},{"key":"D","text":"黄河入海去"}]}},"cnc_p096":{"desc":"背诵李白《望庐山瀑布》，不把「三千尺」和「九天」记错。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p095","k":1,"why":"背《望庐山瀑布》之前，要先会背《登鹳雀楼》，才不会把更上一层楼和飞流直下记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「日照香炉生紫烟」的下一句是哪一句？","answer":"B","explanation":"先写远远看见瀑布挂在山前，后面才写飞流直下。","choices":[{"key":"A","text":"飞流直下三千尺"},{"key":"B","text":"遥看瀑布挂前川"},{"key":"C","text":"疑是银河落九天"},{"key":"D","text":"遥看瀑布挂前山"}]}},"cnc_p097":{"desc":"抓住仙桃石、猴子观海、仙人指路、金鸡叫天都的样子。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p096","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《望庐山瀑布》」，再学「阅读《黄山奇石》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"仙桃石像什么？","answer":"C","explanation":"飞来石上好像有一只巨大的桃子，那就是仙桃石。","choices":[{"key":"A","text":"一只猴子"},{"key":"B","text":"一位仙人"},{"key":"C","text":"一个巨大的桃子"},{"key":"D","text":"一只金鸡"}]}},"cnc_p098":{"desc":"读懂日月潭在台湾，光华岛把湖分成北边的日潭和南边的月潭。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p097","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《黄山奇石》」，再学「阅读《日月潭》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"日月潭在哪里？","answer":"D","explanation":"课文写日月潭是台湾省最大的一个湖，在台中附近的高山上。","choices":[{"key":"A","text":"新疆吐鲁番"},{"key":"B","text":"井冈山茅坪"},{"key":"C","text":"黄山天都峰"},{"key":"D","text":"我国台湾省的高山上"}]}},"cnc_p099":{"desc":"读懂新疆吐鲁番的葡萄沟，葡萄颜色很多，有的运进阴房制成葡萄干。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p098","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《日月潭》」，再学「阅读《葡萄沟》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"葡萄沟在哪里？","answer":"A","explanation":"新疆吐鲁番有个地方叫葡萄沟。不要把它写成台湾或黄山。","choices":[{"key":"A","text":"新疆吐鲁番"},{"key":"B","text":"台湾日月潭"},{"key":"C","text":"江西井冈山"},{"key":"D","text":"安徽黄山"}]}},"cnc_p100":{"desc":"用雪白、火红这类词说出颜色的不同，能看出把一物比作另一物的句子。","criteria":["能理解词语在句子里的意思","能选出搭配恰当的词语"],"root":"","pre":[{"id":"cnc_p099","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《葡萄沟》」，再学「语文园地四·颜色和比喻」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「雪白、米白、奶白」都是在写什么？","answer":"B","explanation":"白字前面加上雪、米、奶，写出不一样的白。","choices":[{"key":"A","text":"不同样子的红"},{"key":"B","text":"不同样子的白"},{"key":"C","text":"三种动物的名字"},{"key":"D","text":"三座山的名字"}]}},"cnc_p101":{"desc":"读懂青蛙和小鸟对天有多大的争论，知道青蛙错在哪里。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p080","k":1,"why":"读寓言之前，要先会按顺序弄清故事里谁说了什么。"},{"id":"cnc_p100","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地四·颜色和比喻」，再学「阅读《坐井观天》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"青蛙说天有多大？","answer":"C","explanation":"青蛙天天坐在井里，说天不过井口那么大。","choices":[{"key":"A","text":"无边无际"},{"key":"B","text":"和大海一样大"},{"key":"C","text":"只有井口那么大"},{"key":"D","text":"比井还小得多"}]}},"cnc_p102":{"desc":"读懂寒号鸟不肯垒巢，冻死以前还在说明天再做。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p101","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《坐井观天》」，再学「阅读《寒号鸟》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"喜鹊劝寒号鸟做什么？","answer":"D","explanation":"冬天快到了，喜鹊劝寒号鸟别再睡，赶快垒窝。","choices":[{"key":"A","text":"跟着它到南方去"},{"key":"B","text":"把羽毛拔下来"},{"key":"C","text":"晚上不要睡觉"},{"key":"D","text":"趁天好快些垒窝"}]}},"cnc_p103":{"desc":"读懂种葫芦的人只盯着葫芦、不管叶子，葫芦后来全落了。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p102","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《寒号鸟》」，再学「阅读《我要的是葫芦》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"种葫芦的人最喜欢看什么？","answer":"A","explanation":"他每天盯着越长越大的葫芦，希望它们变成大葫芦。","choices":[{"key":"A","text":"小小的葫芦"},{"key":"B","text":"叶子上的蚜虫"},{"key":"C","text":"邻居的劝告"},{"key":"D","text":"整棵葫芦藤"}]}},"cnc_p104":{"desc":"跟别人商量时说清原因，语气客气；被拒绝了也不勉强。日积月累有「少年不知勤学苦，老来方知读书迟」。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p103","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《我要的是葫芦》」，再学「语文园地五·商量」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"想和同学调换值日，哪一句是在商量？","answer":"B","explanation":"商量要有礼貌，把原因说清楚。命令和沉默都不是商量。","choices":[{"key":"A","text":"你必须现在跟我换"},{"key":"B","text":"我想跟你商量一下，今天家里有事，能不能换个时间"},{"key":"C","text":"不说话，自己走掉"},{"key":"D","text":"大声命令对方立刻答应"}]}},"cnc_p105":{"desc":"读懂井冈山艰苦斗争的年代，毛主席在茅坪八角楼的清油灯下写文章。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p104","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地五·商量」，再学「阅读《八角楼上》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"八角楼在哪里？","answer":"C","explanation":"在井冈山艰苦斗争的年代，毛主席住在茅坪村的八角楼。屋顶是八角形的。","choices":[{"key":"A","text":"台湾日月潭"},{"key":"B","text":"新疆葡萄沟"},{"key":"C","text":"井冈山茅坪村"},{"key":"D","text":"黄山"}]}},"cnc_p106":{"desc":"读懂朱德在井冈山和战士们一起挑粮，扁担上写着字。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p105","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《八角楼上》」，再学「阅读《朱德的扁担》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"朱德和战士们挑粮，是在什么地方？","answer":"D","explanation":"井冈山山高路陡，粮食要靠人从山下挑上来。","choices":[{"key":"A","text":"西双版纳"},{"key":"B","text":"黄山"},{"key":"C","text":"沙洲坝的井边"},{"key":"D","text":"井冈山"}]}},"cnc_p107":{"desc":"读懂一九六一年周总理和傣族人民一起过泼水节。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p106","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《朱德的扁担》」，再学「阅读《难忘的泼水节》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"和傣族人民一起过泼水节的是谁？","answer":"A","explanation":"一九六一年的泼水节，周总理来到西双版纳，和大家互相泼水祝福。","choices":[{"key":"A","text":"周总理"},{"key":"B","text":"毛主席"},{"key":"C","text":"朱德"},{"key":"D","text":"李白"}]}},"cnc_p108":{"desc":"读懂刘胡兰在云周西面对敌人，不肯说出别的共产党员，毛主席为她题词。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p107","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《难忘的泼水节》」，再学「阅读《刘胡兰》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"刘胡兰英勇就义是在哪里？","answer":"B","explanation":"课文写敌人包围了云周西村。她在这里面对敌人，不肯说出别人。","choices":[{"key":"A","text":"井冈山八角楼"},{"key":"B","text":"云周西村"},{"key":"C","text":"西双版纳"},{"key":"D","text":"台湾日月潭"}]}},"cnc_p109":{"desc":"看几幅图要按顺序讲清谁在哪里、做什么。日积月累有「有志者事竟成」。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p108","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《刘胡兰》」，再学「语文园地六·看图讲故事」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"看图讲故事，哪一种讲法清楚？","answer":"C","explanation":"图有先后，故事要按顺序连起来。倒着讲、不讲人物，别人听不懂。","choices":[{"key":"A","text":"从最后一幅倒着讲，还说这是开头"},{"key":"B","text":"只说很好看，不说图上有谁"},{"key":"C","text":"先看第一幅谁在做什么，再按顺序讲到最后一幅"},{"key":"D","text":"每幅图各编一个互不相关的故事"}]}},"cnc_p110":{"desc":"背诵柳宗元《江雪》，不把它和《敕勒歌》《望庐山瀑布》记成同一首。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p109","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地六·看图讲故事」，再学「古诗《江雪》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「千山鸟飞绝」的下一句是哪一句？","answer":"D","explanation":"先写山和路都没有人鸟，后面才是江上的渔翁。","choices":[{"key":"A","text":"孤舟蓑笠翁"},{"key":"B","text":"独钓寒江雪"},{"key":"C","text":"风吹草低见牛羊"},{"key":"D","text":"万径人踪灭"}]}},"cnc_p111":{"desc":"背诵北朝民歌《敕勒歌》，知道「见牛羊」的「见」是出现。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p110","k":1,"why":"背《敕勒歌》之前，要先会背《江雪》，才不会把孤舟蓑笠翁和风吹草低见牛羊记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「敕勒川，阴山下」的下一句是哪一句？","answer":"A","explanation":"先把天比作毡帐，笼盖着四面的原野，后面才是天苍苍、野茫茫。","choices":[{"key":"A","text":"天似穹庐，笼盖四野"},{"key":"B","text":"天苍苍，野茫茫"},{"key":"C","text":"风吹草低见牛羊"},{"key":"D","text":"黄河入海流"}]}},"cnc_p112":{"desc":"读懂雾像淘气的孩子，把大海、海岸和城市藏起来，最后把自己也藏起来。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p111","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《敕勒歌》」，再学「阅读《雾在哪里》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"雾飞到海上，把什么藏了起来？","answer":"B","explanation":"他说我要把大海藏起来。海上的景物就看不见了。","choices":[{"key":"A","text":"把太阳摘下来放进口袋"},{"key":"B","text":"大海，连海水、船只和远处都看不见了"},{"key":"C","text":"把雪山全部搬回家"},{"key":"D","text":"只藏起一块小石头"}]}},"cnc_p113":{"desc":"读懂雪孩子陪小白兔，着火时把他救出，自己化成了白云。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p112","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《雾在哪里》」，再学「阅读《雪孩子》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"雪孩子是谁堆出来的？","answer":"C","explanation":"兔妈妈在门外空地上堆了雪孩子，给小白兔做伴。","choices":[{"key":"A","text":"小黑猫"},{"key":"B","text":"雾"},{"key":"C","text":"兔妈妈"},{"key":"D","text":"张衡"}]}},"cnc_p114":{"desc":"背诵园地里的李白《夜宿山寺》，不把「天上人」写成「天上神」。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p096","k":1,"why":"背《夜宿山寺》之前，要先会背《望庐山瀑布》，两首都是李白的，才不会把银河落九天和恐惊天上人记混。"},{"id":"cnc_p113","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《雪孩子》」，再学「语文园地七·《夜宿山寺》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「危楼高百尺」的下一句是哪一句？","answer":"D","explanation":"楼高得好像一伸手就能摘到星星，后面才写不敢高声说话。","choices":[{"key":"A","text":"不敢高声语"},{"key":"B","text":"恐惊天上人"},{"key":"C","text":"更上一层楼"},{"key":"D","text":"手可摘星辰"}]}},"cnc_p115":{"desc":"读懂小刺猬称赞小獾的板凳一个比一个好，称赞让小獾有了自信。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p114","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地七·《夜宿山寺》」，再学「阅读《称赞》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"小刺猬看见小獾在做什么？","answer":"A","explanation":"小板凳做得还粗糙。小刺猬没有笑话他。","choices":[{"key":"A","text":"学做木工，已经做成了三个小板凳"},{"key":"B","text":"在井里看天"},{"key":"C","text":"在江上钓鱼"},{"key":"D","text":"在葡萄沟晒葡萄"}]}},"cnc_p116":{"desc":"读懂松鼠用纸船、小熊用风筝互相祝福，吵架后又主动和好。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p115","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《称赞》」，再学「阅读《纸船和风筝》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"松鼠和小熊分别住在哪里？","answer":"B","explanation":"山上的小溪往下流，正好经过小熊家门口。所以纸船能漂到小熊那里。","choices":[{"key":"A","text":"两个都住在井里"},{"key":"B","text":"松鼠住山顶，小熊住山脚"},{"key":"C","text":"松鼠住山脚，小熊住山顶"},{"key":"D","text":"他们住在同一间屋子"}]}},"cnc_p117":{"desc":"读懂小河撞上大山后不再只抱怨，和泉水、瀑布一起向前流。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p116","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《纸船和风筝》」，再学「阅读《快乐的小河》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"小河一开始为什么哭？","answer":"C","explanation":"他唱着歌向前流，太着急，撞在大山上。沙地和草地都跟他好，只有这次撞疼了。","choices":[{"key":"A","text":"泉水不让他过去"},{"key":"B","text":"瀑布把他冻成了冰"},{"key":"C","text":"太着急，迎面撞上大山，觉得疼，就抱怨"},{"key":"D","text":"野花不跟他说话"}]}},"cnc_p118":{"desc":"看图写几句连贯的话，写清谁在哪里、做什么。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p079","k":1,"why":"看图写几句连贯的话之前，要先会按顺序把事情说清楚。"},{"id":"cnc_p117","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《快乐的小河》」，再学「语文园地八·看图写话」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"看图写话，哪一段写得连贯？","answer":"D","explanation":"先写谁在哪里做什么，再写结果，句子才连得起来。","choices":[{"key":"A","text":"小兔。萝卜。用力。"},{"key":"B","text":"拔出来了小兔菜地终于。"},{"key":"C","text":"它很用力。"},{"key":"D","text":"小兔在菜地里拔萝卜。它拔得很用力，终于拔出来了。"}]}},"cnc_p119":{"desc":"背诵贺知章《咏柳》，知道「二月春风似剪刀」是在写风。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p096","k":1,"why":"背七言《咏柳》之前，要先会背七言《望庐山瀑布》，分清哪句写瀑布、哪句写柳。"},{"id":"cnc_p118","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地八·看图写话」，再学「古诗《咏柳》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「碧玉妆成一树高」的下一句是哪一句？","answer":"A","explanation":"柳条像绿丝绦垂下来。绦是丝带，不能写成「条」。","choices":[{"key":"A","text":"万条垂下绿丝绦"},{"key":"B","text":"不知细叶谁裁出"},{"key":"C","text":"二月春风似剪刀"},{"key":"D","text":"万条垂下绿丝条"}]}},"cnc_p120":{"desc":"背诵高鼎《村居》，不把它和贺知章《咏柳》记成同一首。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p119","k":1,"why":"背《村居》之前，要先会背《咏柳》，才不会把春风似剪刀和放纸鸢记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「草长莺飞二月天」的下一句是哪一句？","answer":"B","explanation":"先写杨柳在春烟里拂着堤岸，后面才写儿童放风筝。","choices":[{"key":"A","text":"儿童散学归来早"},{"key":"B","text":"拂堤杨柳醉春烟"},{"key":"C","text":"忙趁东风放纸鸢"},{"key":"D","text":"二月春风似剪刀"}]}},"cnc_p121":{"desc":"读《找春天》，分清小草、野花、嫩芽、小溪分别是春天的眉毛、眼睛、音符和琴声。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p120","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《村居》」，再学「阅读《找春天》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"小朋友到哪里去找春天？","answer":"C","explanation":"他们脱掉棉袄，冲出家门，奔向田野寻找春天。","choices":[{"key":"A","text":"到雪地里堆雪人"},{"key":"B","text":"待在被窝里不出来"},{"key":"C","text":"脱掉棉袄，奔向田野"},{"key":"D","text":"到夏天的荷塘"}]}},"cnc_p122":{"desc":"读懂长颈鹿大叔寄来的花籽漏在路上，第二年春天开成一条鲜花小路。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p121","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《找春天》」，再学「阅读《开满鲜花的小路》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"包裹是谁寄给鼹鼠先生的？","answer":"D","explanation":"长颈鹿大叔寄来包裹。松鼠太太、刺猬太太和狐狸太太是后来看见花的人。","choices":[{"key":"A","text":"松鼠太太"},{"key":"B","text":"刺猬太太"},{"key":"C","text":"狐狸太太"},{"key":"D","text":"长颈鹿大叔"}]}},"cnc_p123":{"desc":"读懂 1987 年 4 月 5 日，邓小平爷爷在天坛公园认真栽下一棵柏树苗。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p122","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《开满鲜花的小路》」，再学「阅读《邓小平爷爷植树》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文写的植树是哪一天？","answer":"A","explanation":"课文开头就写：1987 年 4 月 5 日，是个令人难忘的日子。","choices":[{"key":"A","text":"1987 年 4 月 5 日"},{"key":"B","text":"1985 年 1 月 1 日"},{"key":"C","text":"1978 年 10 月 1 日"},{"key":"D","text":"2000 年 6 月 1 日"}]}},"cnc_p124":{"desc":"说话要看场合选用语气。日积月累背白居易《赋得古原草送别》前四句：离离原上草，一岁一枯荣。野火烧不尽，春风吹又生。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p120","k":1,"why":"背《赋得古原草送别》之前，要先会背《村居》，才不会把放纸鸢和春风吹又生记成同一首。"},{"id":"cnc_p123","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《邓小平爷爷植树》」，再学「语文园地一·注意说话的语气」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"请别人帮忙时，语气怎样更合适？","answer":"B","explanation":"园地里的口语交际是注意说话的语气。请求别人，要用商量的口气。","choices":[{"key":"A","text":"用命令的口气催别人快点"},{"key":"B","text":"用商量的口气，把话说清楚"},{"key":"C","text":"背过身去不说话"},{"key":"D","text":"故意把声音压得谁也听不见"}]}},"cnc_p125":{"desc":"读懂诗里沿着小溪、顺着小路，找到的是雷锋做过的好事。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p124","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地一·注意说话的语气」，再学「阅读《雷锋叔叔，你在哪里》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"小朋友们在寻找谁？","answer":"C","explanation":"题目就是「雷锋叔叔，你在哪里」。他们沿着小溪和小路去找。","choices":[{"key":"A","text":"曹冲"},{"key":"B","text":"朱德"},{"key":"C","text":"雷锋叔叔"},{"key":"D","text":"周总理"}]}},"cnc_p126":{"desc":"读懂一块平平常常的米糕，经过了许多人的劳动。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p125","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《雷锋叔叔，你在哪里》」，再学「阅读《千人糕》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"爸爸说的「千人糕」实际上是什么？","answer":"D","explanation":"爸爸端上来的就是平常的米糕，却叫它千人糕。","choices":[{"key":"A","text":"一千个人才吃的蛋糕"},{"key":"B","text":"一块石头"},{"key":"C","text":"一碗白糖"},{"key":"D","text":"一块米糕"}]}},"cnc_p127":{"desc":"读懂萨沙把雨衣盖在野蔷薇上，因为他要保护比自己更弱小的。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p126","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《千人糕》」，再学「阅读《我不是最弱小的》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"一家人在郊外时遇到了什么？","answer":"A","explanation":"他们在郊外，雨忽然下来了，妈妈拿出了雨衣。","choices":[{"key":"A","text":"突然下起雨来"},{"key":"B","text":"太阳晒得更厉害"},{"key":"C","text":"河水一下子干了"},{"key":"D","text":"野蔷薇自己把雨衣送来"}]}},"cnc_p128":{"desc":"认识教师、建筑师、饲养员这类职业，读懂「予人玫瑰，手有余香」「与其锦上添花，不如雪中送炭」。","criteria":["能理解词语在句子里的意思","能选出搭配恰当的词语"],"root":"","pre":[{"id":"cnc_p089","k":1,"why":"在园地里搭配词语、读懂名言之前，要先理解词义，能分清意思相反的词。"},{"id":"cnc_p127","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《我不是最弱小的》」，再学「语文园地二·职业和名言」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「予人玫瑰，手有余香」是在说什么？","answer":"B","explanation":"送给别人玫瑰，手上还留着香气。名言说的是帮助别人。","choices":[{"key":"A","text":"玫瑰只能自己留着"},{"key":"B","text":"把好处给别人，自己也会感到快乐"},{"key":"C","text":"帮助别人以后一定吃亏"},{"key":"D","text":"手上有香味就不用洗手"}]}},"cnc_p129":{"desc":"背诵《神州谣》，知道神州就是华夏，台湾岛和大陆是一家。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p128","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·职业和名言」，再学「识字：《神州谣》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「我神州，称华夏」的下一句是哪一句？","answer":"C","explanation":"先说山川美得可以画下来，后面才写黄河、长江。","choices":[{"key":"A","text":"黄河奔，长江涌"},{"key":"B","text":"长城长，珠峰耸"},{"key":"C","text":"山川美，可入画"},{"key":"D","text":"台湾岛，隔海峡"}]}},"cnc_p130":{"desc":"把春节、元宵、清明、端午、七夕、中秋、重阳和习俗对上。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p129","k":0,"why":"按统编教材的常见教学顺序，先学「识字：《神州谣》」，再学「识字：《传统节日》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"端午节有哪些习俗？","answer":"D","explanation":"过端午，赛龙舟，粽子飘香。赏月吃月饼是中秋。","choices":[{"key":"A","text":"赏月、吃月饼"},{"key":"B","text":"登高、赏菊"},{"key":"C","text":"看花灯"},{"key":"D","text":"吃粽子、赛龙舟"}]}},"cnc_p131":{"desc":"知道古代用贝壳当钱币，所以财、购、贫、货这些字带贝字旁。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p130","k":0,"why":"按统编教材的常见教学顺序，先学「识字：《传统节日》」，再学「识字：《「贝」的故事》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"古代人们曾经把什么当成钱币？","answer":"A","explanation":"海边的贝壳好看又难得，古时候曾经拿它当货币。","choices":[{"key":"A","text":"贝壳"},{"key":"B","text":"树叶"},{"key":"C","text":"石头子"},{"key":"D","text":"雪花"}]}},"cnc_p132":{"desc":"借助菜名认识凉拌、煎、烧、烤、煮、爆、炖、蒸、炸、炒，并分清「炸」的两个读音。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p131","k":0,"why":"按统编教材的常见教学顺序，先学「识字：《「贝」的故事》」，再学「识字：《中国美食》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一组菜名都在这篇课文里？","answer":"B","explanation":"课文写了凉拌菠菜、香煎豆腐、红烧茄子，还有烤鸭、水煮鱼等。","choices":[{"key":"A","text":"火锅、酸辣粉、汤圆"},{"key":"B","text":"凉拌菠菜、香煎豆腐、红烧茄子"},{"key":"C","text":"汉堡、薯条、三明治"},{"key":"D","text":"年糕、月饼、粽子"}]}},"cnc_p133":{"desc":"借助火、心、刀这些形旁猜意思，会读甜津津、香喷喷，并背十二生肖。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p132","k":0,"why":"按统编教材的常见教学顺序，先学「识字：《中国美食》」，再学「语文园地三·形旁和十二生肖」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「香喷喷」是怎样的词？它在写什么？","answer":"C","explanation":"甜津津、酸溜溜、辣乎乎、香喷喷都是 ABB，用来写味道或感觉。","choices":[{"key":"A","text":"AABB 式，在写职业"},{"key":"B","text":"一个生肖的名字"},{"key":"C","text":"ABB 式，在写香味"},{"key":"D","text":"一种烹调方法"}]}},"cnc_p134":{"desc":"读《彩色的梦》，知道「我」用彩色铅笔在梦里画下了草地、花朵和小朋友。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p133","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地三·形旁和十二生肖」，再学「阅读《彩色的梦》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「我」的彩色梦靠什么画出来？","answer":"D","explanation":"课文里那一大把彩色的梦，就是躺在铅笔盒里的彩色铅笔。","choices":[{"key":"A","text":"一块黑炭"},{"key":"B","text":"没有颜色的水"},{"key":"C","text":"夜里的月亮"},{"key":"D","text":"一大把彩色铅笔"}]}},"cnc_p135":{"desc":"读懂妹妹走不动时，妈妈给她一根柳条当马，她自己跑回了家。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p134","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《彩色的梦》」，再学「阅读《一匹出色的马》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"散步时，妹妹怎样了？","answer":"A","explanation":"妹妹走累了，不愿意再往前走。","choices":[{"key":"A","text":"走不动，想让人抱"},{"key":"B","text":"一个人先跑回了家"},{"key":"C","text":"在河边洗柳条"},{"key":"D","text":"帮妈妈砍了一棵树"}]}},"cnc_p136":{"desc":"读懂「我」喜欢渡口旁枫树上的喜鹊，觉得自己能听懂喜鹊阿姨和喜鹊弟弟的话。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p135","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《一匹出色的马》」，再学「阅读《枫树上的喜鹊》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"枫树长在哪里？它像什么？","answer":"B","explanation":"渡口旁的枫树绿荫打开着，像一把一直撑开的太阳伞。","choices":[{"key":"A","text":"长在沙漠里，像一把剪刀"},{"key":"B","text":"渡口旁，像一把绿色的太阳伞"},{"key":"C","text":"长在天坛，像柏树苗"},{"key":"D","text":"长在雪地里，像一座城堡"}]}},"cnc_p137":{"desc":"认识拨浪鼓、不倒翁这些玩具，按词读准「倒」；积累「失信不立」「诚信者，天下之结也」。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p022","k":1,"why":"分辨多音字的读音之前，要先会拼读音节。"},{"id":"cnc_p136","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《枫树上的喜鹊》」，再学「语文园地四·玩具和诚信」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「不倒翁」的「倒」读哪一个？","answer":"C","explanation":"不倒翁是倒下去还会起来，这里的倒读 dǎo。","choices":[{"key":"A","text":"dào（倒水的倒）"},{"key":"B","text":"diào（没有这个读音）"},{"key":"C","text":"dǎo（倒下的倒）"},{"key":"D","text":"dōu（都的读音）"}]}},"cnc_p138":{"desc":"读懂羊丢了以后把羊圈修好，还不算晚。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p101","k":1,"why":"再读寓言之前，要先会说出一则寓言的道理。"},{"id":"cnc_p137","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地四·玩具和诚信」，再学「阅读《亡羊补牢》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"养羊人第一次丢羊，是因为什么？","answer":"D","explanation":"羊圈破了，他没有修，狼从窟窿里钻进去，叼走了一只羊。","choices":[{"key":"A","text":"羊自己走丢了，圈是好的"},{"key":"B","text":"他把羊送给了邻居"},{"key":"C","text":"白天羊在圈里热坏了"},{"key":"D","text":"羊圈破了个窟窿，夜里狼钻进去了"}]}},"cnc_p139":{"desc":"读懂宋人把禾苗拔高，禾苗反而枯死了。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p138","k":1,"why":"读《揠苗助长》之前，要先会从寓言里找出做法和结果。"}],"q":{"type":"choice","difficulty":"basic","prompt":"那个人为什么去拔苗？","answer":"A","explanation":"他巴望自己的禾苗长得快些，天天去看，还是觉得慢。","choices":[{"key":"A","text":"他觉得苗长得太慢，想帮它们快些长高"},{"key":"B","text":"苗已经比他高了"},{"key":"C","text":"邻居请他把苗拔掉"},{"key":"D","text":"天要下雨，苗会淹死"}]}},"cnc_p140":{"desc":"读懂「我」从座位侧面把杨桃画成五角星，是因为看到的角度不同。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p138","k":1,"why":"读《画杨桃》之前，要先会从故事里找出做法和结果。"},{"id":"cnc_p139","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《揠苗助长》」，再学「阅读《画杨桃》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「我」把杨桃画成了什么？","answer":"B","explanation":"坐在前排靠边，看到的杨桃一端像五角星。","choices":[{"key":"A","text":"一个圆圆的苹果"},{"key":"B","text":"五角星"},{"key":"C","text":"一只小鸟"},{"key":"D","text":"一把雨伞"}]}},"cnc_p141":{"desc":"读懂老牛说水浅、松鼠说水深，小马后来自己试了试。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p138","k":1,"why":"读《小马过河》之前，要先会从寓言里找出做法和结果。"},{"id":"cnc_p140","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《画杨桃》」，再学「阅读《小马过河》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"小马为什么要过河？","answer":"C","explanation":"磨坊师傅让小马把麦子驮回家，一条河挡住了路。","choices":[{"key":"A","text":"要去找松鼠玩"},{"key":"B","text":"老牛叫它过河"},{"key":"C","text":"要把半口袋麦子驮回家"},{"key":"D","text":"它想测量河有多深"}]}},"cnc_p142":{"desc":"读完寓言和《画杨桃》，能先说出课文里的做法，再说自己怎么看。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p141","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《小马过河》」，再学「语文园地五·说说自己的想法」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"说出自己的想法时，最好先说什么？","answer":"D","explanation":"想法要扣住课文。先说做法和结果，别人听得懂你在说哪一篇。","choices":[{"key":"A","text":"先说一个和课文无关的故事"},{"key":"B","text":"只说「我不知道」"},{"key":"C","text":"把课文题目改掉"},{"key":"D","text":"课文里谁做了什么，再说自己怎么看"}]}},"cnc_p143":{"desc":"背诵杜甫七言《绝句》，不和五言「迟日江山丽」记成同一首。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p119","k":1,"why":"背「两个黄鹂」之前，要先会背《咏柳》，才不会把春风和黄鹂装进同一首。"},{"id":"cnc_p142","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地五·说说自己的想法」，再学「古诗《绝句》：两个黄鹂」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「两个黄鹂鸣翠柳」的下一句是哪一句？","answer":"A","explanation":"先写一行白鹭飞上青天，后面才是窗含西岭、门泊东吴。迟日江山丽是另一首《绝句》。","choices":[{"key":"A","text":"一行白鹭上青天"},{"key":"B","text":"窗含西岭千秋雪"},{"key":"C","text":"门泊东吴万里船"},{"key":"D","text":"迟日江山丽"}]}},"cnc_p144":{"desc":"背诵杨万里这首写西湖六月荷花的诗，不把它记成苏轼的诗。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p143","k":1,"why":"背杨万里的西湖诗之前，要先会背杜甫的七言《绝句》，才不会把黄鹂和荷花记混。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「毕竟西湖六月中」的下一句是哪一句？","answer":"B","explanation":"先说六月的西湖风光和别的时节不同，后面才写莲叶和荷花。比西子是苏轼的句子。","choices":[{"key":"A","text":"接天莲叶无穷碧"},{"key":"B","text":"风光不与四时同"},{"key":"C","text":"映日荷花别样红"},{"key":"D","text":"欲把西湖比西子"}]}},"cnc_p145":{"desc":"按乌云、大风、雷雨、雨停的顺序说出雷雨前后的变化。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p144","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《晓出净慈寺送林子方》」，再学「阅读《雷雨》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"雨下来之前，天色和风有什么变化？","answer":"C","explanation":"满天乌云，黑沉沉的。风把树枝吹得乱摆。","choices":[{"key":"A","text":"太阳更红了"},{"key":"B","text":"天上出现了彩虹"},{"key":"C","text":"乌云压下来，风越来越大"},{"key":"D","text":"树叶一动也不动"}]}},"cnc_p146":{"desc":"读懂太阳、北极星、大树和沟渠积雪怎样帮助辨别方向。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p145","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《雷雨》」，再学「阅读《要是你在野外迷了路》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"中午的时候，太阳在哪一边？","answer":"D","explanation":"中午太阳在南边，地上的树影正指着北方。","choices":[{"key":"A","text":"北边"},{"key":"B","text":"东边的树根下"},{"key":"C","text":"西边的沟渠里"},{"key":"D","text":"南边"}]}},"cnc_p147":{"desc":"读懂在太空睡觉要固定身体，喝水要用吸管，走路的鞋子带钩子。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p146","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《要是你在野外迷了路》」，再学「阅读《太空生活趣事多》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"在太空里睡觉，身体要怎样？","answer":"A","explanation":"人会飘起来，所以睡觉要把自己绑住、固定住。","choices":[{"key":"A","text":"钻进睡袋，把身体固定好"},{"key":"B","text":"躺在地上就不会飘"},{"key":"C","text":"必须站着睡"},{"key":"D","text":"可以不固定，和在家里一样"}]}},"cnc_p148":{"desc":"背二十四节气歌，读准「处暑」的处；写话时对大自然写下「为什么……」。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p147","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《太空生活趣事多》」，再学「语文园地六·节气和问号」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「春雨惊春清谷天」的下一句是哪一句？","answer":"B","explanation":"上一句是春季节气，下一句才接到夏天：立夏、小满、芒种、夏至、小暑、大暑。","choices":[{"key":"A","text":"秋处露秋寒霜降"},{"key":"B","text":"夏满芒夏暑相连"},{"key":"C","text":"冬雪雪冬小大寒"},{"key":"D","text":"春风吹又生"}]}},"cnc_p149":{"desc":"读懂大象耳朵像扇子，竖起来以后反而不舒服。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p148","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地六·节气和问号」，再学「阅读《大象的耳朵》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"大象的耳朵本来是什么样的？","answer":"C","explanation":"大象有一对大耳朵，像扇子似的耷拉着。","choices":[{"key":"A","text":"像兔子一样竖得笔直"},{"key":"B","text":"小得几乎看不见"},{"key":"C","text":"像扇子似的耷拉着"},{"key":"D","text":"一天到晚扇个不停"}]}},"cnc_p150":{"desc":"读懂蜘蛛先后卖口罩、围巾、袜子，顾客分别是河马、长颈鹿和蜈蚣。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p149","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《大象的耳朵》」，再学「阅读《蜘蛛开店》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"蜘蛛为什么想开店？","answer":"D","explanation":"它每天等小飞虫，好寂寞，好无聊，于是决定开一家商店。","choices":[{"key":"A","text":"它已经有很多顾客"},{"key":"B","text":"河马请它开店"},{"key":"C","text":"它想去太空走路"},{"key":"D","text":"蹲在网上等飞虫，觉得寂寞、无聊"}]}},"cnc_p151":{"desc":"读懂青蛙按别人的意见改泥塘，最后觉得太好了，自己留下不卖。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p150","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《蜘蛛开店》」，再学「阅读《青蛙卖泥塘》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"青蛙一开始想怎样处理泥塘？","answer":"A","explanation":"泥塘又荒又差，青蛙喊着要卖泥塘。","choices":[{"key":"A","text":"把它卖掉"},{"key":"B","text":"把它填成马路"},{"key":"C","text":"请蜘蛛来开店"},{"key":"D","text":"自己搬去天坛"}]}},"cnc_p152":{"desc":"读懂小毛虫不着急，认真做自己的事，最后变成蝴蝶。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p151","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《青蛙卖泥塘》」，再学「阅读《小毛虫》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"别的昆虫怎样看小毛虫？","answer":"B","explanation":"别的昆虫在花间飞来飞去，小毛虫却爬得很慢，它们笑它。","choices":[{"key":"A","text":"觉得它已经是蝴蝶"},{"key":"B","text":"觉得它又慢又什么也不会"},{"key":"C","text":"请它去卖泥塘"},{"key":"D","text":"跟它一起结茧"}]}},"cnc_p153":{"desc":"认识扫帚、抹布、拖把、簸箕、水桶，会说扫地、擦玻璃、倒垃圾、摆桌椅。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p152","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《小毛虫》」，再学「语文园地七·大扫除」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"扫地最常用哪一种工具？","answer":"C","explanation":"扫帚用来扫地。抹布是用来擦的。","choices":[{"key":"A","text":"抹布"},{"key":"B","text":"雨衣"},{"key":"C","text":"扫帚"},{"key":"D","text":"柳条"}]}},"cnc_p154":{"desc":"读懂十个太阳一起出来时，羿射下九个，留下一个。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p153","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地七·大扫除」，再学「阅读《羿射九日》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"故事开头，天上同时出现了几个太阳？","answer":"D","explanation":"十个太阳一起烤着大地，庄稼枯了，人们受不了。","choices":[{"key":"A","text":"一个"},{"key":"B","text":"九个"},{"key":"C","text":"两个"},{"key":"D","text":"十个"}]}},"cnc_p155":{"desc":"读懂黄帝从草帽滚动想到造车，从漂在水上的树叶想到造船。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p154","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《羿射九日》」，再学「阅读《黄帝的传说》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文里的黄帝又被称作什么？","answer":"A","explanation":"课文称他轩辕。大禹、羿是另外两篇传说里的人物。","choices":[{"key":"A","text":"轩辕"},{"key":"B","text":"大禹"},{"key":"C","text":"羿"},{"key":"D","text":"雷锋"}]}},"cnc_p156":{"desc":"读懂洪水泛滥时，禹用疏导的办法挖通河道，让洪水流入大海。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p155","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《黄帝的传说》」，再学「阅读《大禹治水》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"洪水泛滥时，人们的生活怎样？","answer":"B","explanation":"大水淹没田地，冲毁房屋，人们痛苦极了。","choices":[{"key":"A","text":"到处都是十个太阳"},{"key":"B","text":"田地被淹，房屋被冲毁"},{"key":"C","text":"泥塘卖得很好"},{"key":"D","text":"只要把窗关上就行"}]}},"cnc_p157":{"desc":"用动作把心情写具体，并按顺序写一件小事。日积月累背范仲淹《江上渔者》。推荐动画片时要把话说慢，让人听清。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p094","k":1,"why":"把句子写具体之前，要先会把句子补充完整。"},{"id":"cnc_p118","k":1,"why":"按顺序写一件小事之前，要先会写几句连贯的话。"},{"id":"cnc_p156","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《大禹治水》」，再学「语文园地八·把句子写具体」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「江上往来人」的下一句是哪一句？","answer":"C","explanation":"人们喜爱的是鲈鱼的鲜美，后面才写一叶小舟出没在风波里。荷花是杨万里的诗。","choices":[{"key":"A","text":"君看一叶舟"},{"key":"B","text":"出没风波里"},{"key":"C","text":"但爱鲈鱼美"},{"key":"D","text":"映日荷花别样红"}]}},"cnc_p158":{"desc":"读懂这是一所边疆小学，不同民族的孩子在同一所学校上学。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p157","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地八·把句子写具体」，再学「阅读《大青树下的小学》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文写的学校在什么样的地方？","answer":"D","explanation":"课文说这就是我们可爱的小学，一所边疆的小学。","choices":[{"key":"A","text":"繁华的大城市中心"},{"key":"B","text":"海岛上的渔村"},{"key":"C","text":"只有一个院子的私塾"},{"key":"D","text":"边疆"}]}},"cnc_p159":{"desc":"读泰戈尔的散文诗：花在地下上学，雨一来就放假，急着回到天上的妈妈身边。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p158","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《大青树下的小学》」，再学「阅读《花的学校》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《花的学校》的作者是谁？","answer":"A","explanation":"这篇是泰戈尔写的。张天翼写《宝葫芦的秘密》，贾尼·罗大里写《小狗学叫》。","choices":[{"key":"A","text":"泰戈尔"},{"key":"B","text":"张天翼"},{"key":"C","text":"叶圣陶"},{"key":"D","text":"贾尼·罗大里"}]}},"cnc_p160":{"desc":"读懂孙中山小时候不懂就向先生提问，先生称赞他。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p159","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《花的学校》」，再学「阅读《不懂就要问》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文里勤学好问的小朋友是谁？","answer":"B","explanation":"课文写的是孙中山小时候在私塾读书的事。","choices":[{"key":"A","text":"司马光"},{"key":"B","text":"孙中山"},{"key":"C","text":"列宁"},{"key":"D","text":"曹冲"}]}},"cnc_p161":{"desc":"已经知道读音时，按音节的第一个字母用音序查字法查字典。口语交际「我的暑假生活」要说清一件暑假里的事；习作「猜猜他是谁」不说出名字，用特点让别人猜。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p016","k":1,"why":"按音序查字之前，要先认识声母和字母顺序。"},{"id":"cnc_p160","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《不懂就要问》」，再学「语文园地一·音序查字典」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"已经知道「花」读 huā，适合先用哪种查法？","answer":"C","explanation":"知道读音，就按音序去查。不知道读音，才先用部首。","choices":[{"key":"A","text":"部首查字法"},{"key":"B","text":"随便从最后一页翻起"},{"key":"C","text":"音序查字法"},{"key":"D","text":"只看插图不查字"}]}},"cnc_p162":{"desc":"不认识的字，先找部首，再数除去部首还有几画。和音序查字法一起用在语文园地一。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p090","k":1,"why":"用部首查字典之前，要先认识常见偏旁。"},{"id":"cnc_p161","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地一·音序查字典」，再学「语文园地一·部首查字典」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「河」用部首查字法，部首是哪一个？","answer":"D","explanation":"河的左边是三点水。可是另一部分，不是部首。","choices":[{"key":"A","text":"可"},{"key":"B","text":"口"},{"key":"C","text":"木"},{"key":"D","text":"三点水"}]}},"cnc_p163":{"desc":"背诵刘禹锡《望洞庭》，知道白银盘比喻湖面，青螺比喻君山。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p144","k":1,"why":"背刘禹锡《望洞庭》之前，要先会背杨万里的西湖诗，才不会把白银盘里的青螺和接天莲叶记成同一处湖。"},{"id":"cnc_p162","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地一·部首查字典」，再学「古诗《望洞庭》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「湖光秋月两相和」的下一句是哪一句？","answer":"A","explanation":"湖光和秋月融在一起，后面才写无风的湖面像没有磨过的铜镜。","choices":[{"key":"A","text":"潭面无风镜未磨"},{"key":"B","text":"遥望洞庭山水翠"},{"key":"C","text":"白银盘里一青螺"},{"key":"D","text":"潭面无风镜已磨"}]}},"cnc_p164":{"desc":"背诵杜牧《山行》，知道「坐」是因为，「红于」是比……更红。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p143","k":1,"why":"背杜牧《山行》之前，要先会背杜甫的七言《绝句》，才不会把两位诗人的句子装错。"},{"id":"cnc_p163","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《望洞庭》」，再学「古诗《山行》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「远上寒山石径斜」的下一句是哪一句？","answer":"B","explanation":"统编教材这句是「白云生处有人家」。停车、霜叶是后两句。","choices":[{"key":"A","text":"停车坐爱枫林晚"},{"key":"B","text":"白云生处有人家"},{"key":"C","text":"霜叶红于二月花"},{"key":"D","text":"白云深处有人家"}]}},"cnc_p165":{"desc":"背诵叶绍翁《夜书所见》，知道促织是蟋蟀，客情是身在异乡的心情。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p164","k":1,"why":"背叶绍翁《夜书所见》之前，要先会背杜牧《山行》，两首都写秋，才不会把霜叶和篱落一灯明记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「萧萧梧叶送寒声」的下一句是哪一句？","answer":"C","explanation":"梧叶带来寒意，秋风牵动了旅人想家的心情。挑促织、一灯明是后两句。","choices":[{"key":"A","text":"知有儿童挑促织"},{"key":"B","text":"夜深篱落一灯明"},{"key":"C","text":"江上秋风动客情"},{"key":"D","text":"江上秋风动客愁"}]}},"cnc_p166":{"desc":"读张秋生的课文：一夜风雨之后，梧桐叶像金色的巴掌铺在水泥道上。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p165","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《夜书所见》」，再学「阅读《铺满金色巴掌的水泥道》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"水泥道上铺满的是什么？","answer":"D","explanation":"法国梧桐的叶子落下来，平展地贴在道上，所以说像巴掌。小扇子是《秋天的雨》里的银杏叶。","choices":[{"key":"A","text":"金色的雪"},{"key":"B","text":"银杏叶做的小扇子"},{"key":"C","text":"海滩上的贝壳"},{"key":"D","text":"梧桐树的落叶，像一只只金色的巴掌"}]}},"cnc_p167":{"desc":"抓住秋天的雨这把钥匙打开的颜色、气味和凉意。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p097","k":1,"why":"读《秋天的雨》之前，要先会抓住写景课文里的景物特点。"},{"id":"cnc_p166","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《铺满金色巴掌的水泥道》」，再学「阅读《秋天的雨》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文把秋天的雨比作什么？","answer":"A","explanation":"秋天的雨，是一把钥匙，把秋天的大门打开了。","choices":[{"key":"A","text":"一把钥匙"},{"key":"B","text":"一个太阳"},{"key":"C","text":"一只灰雀"},{"key":"D","text":"一条小船"}]}},"cnc_p168":{"desc":"分清刷刷是黄叶道别，瞿瞿是蟋蟀和阳台告别，秋的声音还在谷粒和汗水里。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p167","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《秋天的雨》」，再学「阅读《听听，秋的声音》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「刷刷」在诗里是什么声音？","answer":"B","explanation":"黄叶离开树枝，说出道别的话。蟋蟀的声音是后面的「瞿瞿」。","choices":[{"key":"A","text":"蟋蟀振动翅膀"},{"key":"B","text":"大树抖抖手臂，黄叶在道别"},{"key":"C","text":"海浪拍打沙滩"},{"key":"D","text":"石头砸破水缸"}]}},"cnc_p169":{"desc":"日记先写日期、星期和天气，再写这一天真正看到的、听到的和想到的。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p157","k":1,"why":"写日记之前，要先会按顺序把一件事写下来，并把样子写具体。"},{"id":"cnc_p168","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《听听，秋的声音》」，再学「习作：写日记」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"一篇日记，第一行通常先写什么？","answer":"C","explanation":"先让人知道是哪一天、星期几、天气怎样，再写这一天的事。","choices":[{"key":"A","text":"只写一个感叹号"},{"key":"B","text":"先写结尾"},{"key":"C","text":"日期、星期和天气"},{"key":"D","text":"先写别人没看见的想象"}]}},"cnc_p170":{"desc":"能辨认绿油油、红彤彤和整整齐齐，并知道重叠以后的意思。","criteria":["能理解词语在句子里的意思","能选出搭配恰当的词语"],"root":"","pre":[{"id":"cnc_p070","k":1,"why":"积累 ABB、AABB 之前，要先会读高高兴兴这类重叠词。"},{"id":"cnc_p169","k":0,"why":"按统编教材的常见教学顺序，先学「习作：写日记」，再学「语文园地二·ABB 和 AABB 式词语」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一个是 ABB 式词语？","answer":"D","explanation":"绿油油是一个字后面叠两个相同的字。整整齐齐是 AABB。","choices":[{"key":"A","text":"整整齐齐"},{"key":"B","text":"高低"},{"key":"C","text":"绿油"},{"key":"D","text":"绿油油"}]}},"cnc_p171":{"desc":"一边读一边预测：老屋一次次答应小猫、老母鸡和小蜘蛛的请求。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p160","k":1,"why":"边读边预测之前，要先会读懂一篇故事在讲谁做了什么。"},{"id":"cnc_p170","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·ABB 和 AABB 式词语」，再学「阅读《总也倒不了的老屋》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"故事开始时，老屋打算怎样？","answer":"A","explanation":"老屋说：我到了倒下的时候了。它的窗户、门板都旧了。","choices":[{"key":"A","text":"倒下，因为它已经很老了"},{"key":"B","text":"马上盖成新楼"},{"key":"C","text":"自己跑到河边"},{"key":"D","text":"把小动物都赶走"}]}},"cnc_p172":{"desc":"读米切尔·恩德的童话：乌龟陶陶要去参加狮王的婚礼，别人怎么劝，她的决定也不改变。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p171","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《总也倒不了的老屋》」，再学「阅读《犟龟》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"陶陶出发，是要去参加谁的婚礼？","answer":"B","explanation":"她听鸽子说，狮王二十八世邀请动物去参加庆典，就拿定主意上路了。","choices":[{"key":"A","text":"蜘蛛的婚礼"},{"key":"B","text":"狮王二十八世的婚礼"},{"key":"C","text":"蜗牛的婚礼"},{"key":"D","text":"老虎的婚礼"}]}},"cnc_p173":{"desc":"读贾尼·罗大里的童话：不会叫的小狗先学公鸡叫，再学杜鹃叫，课文留下几种结局让人预测。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p172","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《犟龟》」，再学「阅读《小狗学叫》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这只小狗为什么要学叫？","answer":"C","explanation":"它不会像狗、猫、牛、马那样叫。别人批评它，它却不知道正确的叫声是什么样。","choices":[{"key":"A","text":"它觉得汪汪叫太难听，所以改掉"},{"key":"B","text":"狐狸命令它不准学狗叫"},{"key":"C","text":"它来到没有狗的地方，从没听过狗怎么叫，还被人笑话"},{"key":"D","text":"它本来就会狗叫，只是想玩玩"}]}},"cnc_p174":{"desc":"续写要接着前面的情节，人物的脾气不能突然换掉。口语交际「名字里的故事」要说出名字的来历或含义。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p173","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《小狗学叫》」，再学「语文园地三·续写故事」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"续写《总也倒不了的老屋》，哪一种接得上？","answer":"D","explanation":"前面来的都是请老屋再等等的小动物。续写要接着这个情节，不能换成另一篇。","choices":[{"key":"A","text":"老屋忽然飞到西沙群岛捕鱼"},{"key":"B","text":"故事改成背一首古诗"},{"key":"C","text":"从第一句起老屋就没有出现"},{"key":"D","text":"又来了一个需要帮忙的小动物，请老屋再留一留"}]}},"cnc_p175":{"desc":"读张天翼的童话节选：王葆听奶奶讲过宝葫芦，想要一个想什么就有什么的葫芦。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p174","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地三·续写故事」，再学「阅读《宝葫芦的秘密》（节选）」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这篇节选的作者是谁？主人公叫什么？","answer":"A","explanation":"《宝葫芦的秘密》是张天翼的童话。节选里想得到宝葫芦的孩子叫王葆。","choices":[{"key":"A","text":"张天翼。主人公是王葆"},{"key":"B","text":"泰戈尔。主人公是陶陶"},{"key":"C","text":"贾尼·罗大里。主人公是一条小狗"},{"key":"D","text":"叶圣陶。主人公是稻草人"}]}},"cnc_p176":{"desc":"读懂红头被牛吞进肚子，青头在外面鼓励它，最后红头被喷了出来。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p175","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《宝葫芦的秘密》（节选）」，再学「阅读《在牛肚子里旅行》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"红头和青头是什么动物？","answer":"B","explanation":"青头和红头是一对好朋友，都是蟋蟀。","choices":[{"key":"A","text":"两只小鸟"},{"key":"B","text":"两只蟋蟀"},{"key":"C","text":"两头老牛"},{"key":"D","text":"两只小鱼"}]}},"cnc_p177":{"desc":"读懂蚂蚁队长不许偷嘴，自己也不吃，后来把掉下的一点奶酪给了最小的蚂蚁。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p176","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《在牛肚子里旅行》」，再学「阅读《一块奶酪》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"蚂蚁队长发现奶酪以后，先吩咐大家做什么？","answer":"C","explanation":"奶酪是要搬回去的。队长带着大家搬运，不是先开饭。","choices":[{"key":"A","text":"当场分着吃完"},{"key":"B","text":"拿去送给狮王"},{"key":"C","text":"把这块奶酪搬进洞里"},{"key":"D","text":"扔进河里"}]}},"cnc_p178":{"desc":"自己编一个童话：有会想象出来的角色，有麻烦，有后来怎样。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p177","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《一块奶酪》」，再学「语文园地四·我来编童话」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一个开头像在编童话？","answer":"D","explanation":"童话里常有不会真的说话的东西开口说话。只写日期，或者只有两个词，故事还没开始。","choices":[{"key":"A","text":"今天星期一，天气晴。"},{"key":"B","text":"奶酪。蚂蚁。"},{"key":"C","text":"我要编故事，但是没有角色"},{"key":"D","text":"小蚂蚁拿到一块会说话的奶酪，奶酪说它想回家"}]}},"cnc_p179":{"desc":"这次读书吧读童话。安徒生童话、叶圣陶的《稻草人》，都是那个想象出来的王国。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p178","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地四·我来编童话」，再学「快乐读书吧：在那奇妙的王国里」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「在那奇妙的王国里」主要读哪一类书？","answer":"A","explanation":"童话里有想象出来的人和事。《稻草人》是叶圣陶的童话。空白本和口诀表不是。","choices":[{"key":"A","text":"童话，比如安徒生童话和《稻草人》"},{"key":"B","text":"只抄当天的课程表"},{"key":"C","text":"一本空白笔记本"},{"key":"D","text":"只印着乘法口诀的表"}]}},"cnc_p180":{"desc":"学习作者怎样观察翠鸟的颜色和捕鱼动作。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p179","k":0,"why":"按统编教材的常见教学顺序，先学「快乐读书吧：在那奇妙的王国里」，再学「阅读《搭船的鸟》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"搭船的鸟是什么鸟？","answer":"B","explanation":"母亲告诉「我」，那只彩色的鸟是翠鸟。","choices":[{"key":"A","text":"灰雀"},{"key":"B","text":"翠鸟"},{"key":"C","text":"燕子"},{"key":"D","text":"黄鹂"}]}},"cnc_p181":{"desc":"读普里什文的课文：蒲公英张开时草地是金色的，合拢时又变成绿色。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p180","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《搭船的鸟》」，再学「阅读《金色的草地》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《金色的草地》的作者是谁？","answer":"C","explanation":"这篇写蒲公英草地的课文是普里什文的。泰戈尔写《花的学校》，朱维之写《读不完的大书》。","choices":[{"key":"A","text":"泰戈尔"},{"key":"B","text":"张天翼"},{"key":"C","text":"普里什文"},{"key":"D","text":"朱维之"}]}},"cnc_p182":{"desc":"写一种看到的事物，把颜色、样子和不同时候的变化写出来，不要只写「很美」。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p180","k":1,"why":"写「我们眼中的缤纷世界」之前，要先会像《搭船的鸟》那样按顺序说出看到的样子。"},{"id":"cnc_p181","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《金色的草地》」，再学「习作：我们眼中的缤纷世界」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"写眼前的一种事物，哪一种更清楚？","answer":"D","explanation":"要写出自己看到的颜色和变化。只说很美，别人不知道美在哪里。","choices":[{"key":"A","text":"世界很美。"},{"key":"B","text":"我没看，但一定很好看。"},{"key":"C","text":"草地。"},{"key":"D","text":"草地中午是金色的，蒲公英张开了；傍晚花合拢，草地又变成绿色。"}]}},"cnc_p183":{"desc":"写看到的事物时，按后面是名词、动词还是补语，选用的、地、得。","criteria":["能把句子写通顺","能按要求选用或修改句子"],"root":"","pre":[{"id":"cnc_p157","k":1,"why":"区分的、地、得之前，要先会把一句话写完整、写具体。"},{"id":"cnc_p182","k":0,"why":"按统编教材的常见教学顺序，先学「习作：我们眼中的缤纷世界」，再学「习作：我们眼中的缤纷世界·的、地、得」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「美丽____花」横线处该填哪一个？","answer":"A","explanation":"的后面常常是名词。花是名词，用「美丽的花」。","choices":[{"key":"A","text":"的"},{"key":"B","text":"地"},{"key":"C","text":"得"},{"key":"D","text":"底"}]}},"cnc_p184":{"desc":"按海水、海底、海滩、海岛的顺序了解西沙群岛的物产。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p183","k":0,"why":"按统编教材的常见教学顺序，先学「习作：我们眼中的缤纷世界·的、地、得」，再学「阅读《富饶的西沙群岛》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"西沙群岛的海水为什么五光十色？","answer":"B","explanation":"海水有深蓝、淡青、绿、淡绿、杏黄，是因为海底高低不平。","choices":[{"key":"A","text":"海面上撒了颜料"},{"key":"B","text":"海底有高耸的山崖，也有低陷的峡谷，深浅不同"},{"key":"C","text":"海水只有一种深黑色"},{"key":"D","text":"因为那里没有阳光"}]}},"cnc_p185":{"desc":"先读海滨的沙滩和船，再读小城的庭院、公园和扫得很干净的街道。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p184","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《富饶的西沙群岛》」，再学「阅读《海滨小城》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文先写哪里，后写哪里？","answer":"C","explanation":"海的颜色、沙滩、渔船在前。庭院、公园、街道是小城这一部分。","choices":[{"key":"A","text":"只写小城，没有海"},{"key":"B","text":"先写小兴安岭的雪，再写海"},{"key":"C","text":"先写海滨，再写小城"},{"key":"D","text":"从头到尾只写一条船"}]}},"cnc_p186":{"desc":"按春夏秋冬读小兴安岭：夏天枝叶封住森林，秋天献出山葡萄、榛子和人参。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p185","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《海滨小城》」，再学「阅读《美丽的小兴安岭》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文按什么顺序写小兴安岭？","answer":"D","explanation":"四个季节各有样子。不是只挑一个季节，也不是按海滨、小城来分。","choices":[{"key":"A","text":"只写夏天"},{"key":"B","text":"从海里写到沙滩"},{"key":"C","text":"从早晨写到中午就结束"},{"key":"D","text":"春、夏、秋、冬"}]}},"cnc_p187":{"desc":"从万国市场、美食天堂和旅游胜地读懂香港为什么被比作明珠。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p186","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《美丽的小兴安岭》」，再学「阅读《香港，璀璨的明珠》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文把香港比作什么？","answer":"A","explanation":"明珠写的是它又亮又重要。青螺是《望洞庭》里的君山。","choices":[{"key":"A","text":"祖国南海之滨一颗璀璨的明珠"},{"key":"B","text":"白银盘里的一枚青螺"},{"key":"C","text":"一把打开秋天的钥匙"},{"key":"D","text":"一块搬不完的奶酪"}]}},"cnc_p188":{"desc":"围绕一个地方写它美在哪里，可以像课文那样分几个方面，每一方面都要具体。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p187","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《香港，璀璨的明珠》」，再学「语文园地六·这儿真美」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"写「这儿真美」，哪一段是围绕一个地方的？","answer":"B","explanation":"三句都在写这小城的街道。只重复「美」，或者一句一个地方，读者不知道你要写哪里。","choices":[{"key":"A","text":"这儿真美，非常美，特别美。"},{"key":"B","text":"海滨小城的街道用细沙铺成，人们扫得很干净，连一片落叶都看不见。"},{"key":"C","text":"街道。足球。面条。"},{"key":"D","text":"街道很美。西沙的鱼也很美。洞庭湖的月亮也很美。"}]}},"cnc_p189":{"desc":"背诵王维《鹿柴》，知道空山并非没有声音，返景是夕阳返照的光。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p164","k":1,"why":"背王维《鹿柴》之前，要先会背杜牧《山行》，两首都写山，才不会把空山不见人和霜叶红于二月花记成同一首。"},{"id":"cnc_p188","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地六·这儿真美」，再学「古诗《鹿柴》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「空山不见人」的下一句是哪一句？","answer":"C","explanation":"看不见人，却听得见说话的声音。返景、青苔是后两句。是「闻」，不是「见」。","choices":[{"key":"A","text":"返景入深林"},{"key":"B","text":"复照青苔上"},{"key":"C","text":"但闻人语响"},{"key":"D","text":"但见人语响"}]}},"cnc_p190":{"desc":"背诵李白《望天门山》，知道楚江就是长江，碧水在这里回旋。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p164","k":1,"why":"背写山水的《望天门山》之前，要先会背《山行》，分清山行和天门山不是同一首。"},{"id":"cnc_p189","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《鹿柴》」，再学「古诗《望天门山》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「天门中断楚江开」的下一句是哪一句？","answer":"D","explanation":"江水向东流到这里打了个回旋。教材这句是「至此回」。","choices":[{"key":"A","text":"两岸青山相对出"},{"key":"B","text":"孤帆一片日边来"},{"key":"C","text":"碧水东流到此回"},{"key":"D","text":"碧水东流至此回"}]}},"cnc_p191":{"desc":"背诵苏轼这首写西湖的诗，不把它和杨万里的西湖荷花诗记混。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p144","k":1,"why":"背苏轼的西湖诗之前，要先会背杨万里的西湖诗，才不会把「比西子」和「接天莲叶」记混。"},{"id":"cnc_p190","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《望天门山》」，再学「古诗《饮湖上初晴后雨》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「水光潋滟晴方好」的下一句是哪一句？","answer":"A","explanation":"晴天的水光很好，雨天的山色也很奇妙。接天莲叶是杨万里的句子。","choices":[{"key":"A","text":"山色空蒙雨亦奇"},{"key":"B","text":"欲把西湖比西子"},{"key":"C","text":"淡妆浓抹总相宜"},{"key":"D","text":"接天莲叶无穷碧"}]}},"cnc_p192":{"desc":"读懂风、水和动物都是大自然里的音乐家。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p191","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《饮湖上初晴后雨》」，再学「阅读《大自然的声音》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文说，风是大自然的什么？","answer":"B","explanation":"风会在森林里演奏，课文称他是大自然的音乐家。","choices":[{"key":"A","text":"画家"},{"key":"B","text":"音乐家"},{"key":"C","text":"石匠"},{"key":"D","text":"裁缝"}]}},"cnc_p193":{"desc":"读朱维之的课文：大自然是一本看不完的大画册，里面有麻雀、老鹰、蚂蚁，也有竹子和棕榈。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p192","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《大自然的声音》」，再学「阅读《读不完的大书》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「读不完的大书」指的是什么？","answer":"C","explanation":"课文说大自然是看不完的大画册，是永远读不完的大书。","choices":[{"key":"A","text":"一本厚厚的生字表"},{"key":"B","text":"只写香港夜景的课文"},{"key":"C","text":"大自然"},{"key":"D","text":"狮王的婚礼请柬"}]}},"cnc_p194":{"desc":"先说出看见的问题，再写出办法和理由。口语交际「身边的小事」要把经过说清楚。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p193","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《读不完的大书》」，再学「语文园地七·我有一个想法」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"写「我有一个想法」，哪一种清楚？","answer":"D","explanation":"问题、办法、理由都在。只说有想法，别人不知道你要改什么。","choices":[{"key":"A","text":"我有一个想法。"},{"key":"B","text":"想法很好。"},{"key":"C","text":"图书。足球。面条。"},{"key":"D","text":"图书角太挤了。我建议再加一层架子，把故事书和科普书分开，找书就快了。"}]}},"cnc_p195":{"desc":"借助注释读懂司马光砸瓮救友：瓮是水缸，光持石击瓮。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p160","k":1,"why":"读文言文之前，要先会读懂一篇写人的故事在讲谁做了什么。"},{"id":"cnc_p194","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地七·我有一个想法」，再学「文言文《司马光》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"一个小孩掉进了什么里面？","answer":"A","explanation":"一儿登瓮，足跌没水中。瓮是口小肚大的水缸。","choices":[{"key":"A","text":"瓮"},{"key":"B","text":"井"},{"key":"C","text":"河"},{"key":"D","text":"牛肚子"}]}},"cnc_p196":{"desc":"读懂童第周的两件事：中学时为自己争气，留学时做出剥离青蛙卵外膜的实验，为中国人争气。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p195","k":0,"why":"按统编教材的常见教学顺序，先学「文言文《司马光》」，再学「阅读《一定要争气》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文写的是谁的故事？","answer":"B","explanation":"两件争气的事都发生在童第周身上。白求恩在手术台旁，赵一曼和一只粗瓷大碗有关。","choices":[{"key":"A","text":"白求恩"},{"key":"B","text":"生物学家童第周"},{"key":"C","text":"赵一曼"},{"key":"D","text":"司马光"}]}},"cnc_p197":{"desc":"读懂齐会战斗中，白求恩把手术台当成医生的阵地，连续工作了六十九个小时。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p196","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《一定要争气》」，再学「阅读《手术台就是阵地》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文里坚持做手术的人是谁？","answer":"C","explanation":"白求恩是加拿大的医生，在齐会战斗里为伤员做手术。","choices":[{"key":"A","text":"童第周"},{"key":"B","text":"赵一曼"},{"key":"C","text":"白求恩大夫"},{"key":"D","text":"司马光"}]}},"cnc_p198":{"desc":"读懂赵一曼和战士用同一只粗瓷大碗吃饭，还把饭让给生病的小通讯员。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p197","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《手术台就是阵地》」，再学「阅读《一个粗瓷大碗》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文围绕什么物件，写的是谁？","answer":"D","explanation":"碗是线索。赵一曼用它吃饭，也用它关心战士。","choices":[{"key":"A","text":"一只宝葫芦，写王葆"},{"key":"B","text":"一块奶酪，写蚂蚁队长"},{"key":"C","text":"一口瓮，写司马光"},{"key":"D","text":"一只粗瓷大碗，写抗日女英雄赵一曼"}]}},"cnc_p199":{"desc":"写自己经历的一件事，把经过写清楚，并写出为什么难忘。口语交际「请教」要说清哪里不会，再谢谢对方。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p198","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《一个粗瓷大碗》」，再学「语文园地八·那次经历真难忘」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一段更像「那次经历真难忘」？","answer":"A","explanation":"经过和心里记住的那一下都在。只重复难忘，别人不知道发生了什么。","choices":[{"key":"A","text":"接力时棒子在我手里滑了一下，同桌喊「稳住」。冲过终点的那一下，我现在还记得。"},{"key":"B","text":"那次真难忘。"},{"key":"C","text":"难忘。非常难忘。特别难忘。"},{"key":"D","text":"接力。面条。古诗。"}]}},"cnc_p200":{"desc":"背诵杜甫五言《绝句》，不和七言「两个黄鹂」记成同一首。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p143","k":1,"why":"背五言《绝句》之前，要先会背七言「两个黄鹂」，两首同名诗才不会串句。"},{"id":"cnc_p199","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地八·那次经历真难忘」，再学「古诗《绝句》：迟日江山丽」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「迟日江山丽」的下一句是哪一句？","answer":"B","explanation":"迟日江山丽，春风花草香。泥融、沙暖是后两句。两个黄鹂是另一首《绝句》。","choices":[{"key":"A","text":"泥融飞燕子"},{"key":"B","text":"春风花草香"},{"key":"C","text":"沙暖睡鸳鸯"},{"key":"D","text":"两个黄鹂鸣翠柳"}]}},"cnc_p201":{"desc":"背诵苏轼题惠崇画的诗，知道作者是苏轼，不是画家惠崇。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p191","k":1,"why":"背苏轼题画的《惠崇春江晚景》之前，要先会背他的西湖诗，才不会把「鸭先知」和「比西子」记成同一首。"},{"id":"cnc_p200","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《绝句》：迟日江山丽」，再学「古诗《惠崇春江晚景》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「竹外桃花三两枝」的下一句是哪一句？","answer":"C","explanation":"先写鸭子知道江水暖了。蒌蒿、河豚是后两句。是鸭，不是鹅。","choices":[{"key":"A","text":"蒌蒿满地芦芽短"},{"key":"B","text":"正是河豚欲上时"},{"key":"C","text":"春江水暖鸭先知"},{"key":"D","text":"春江水暖鹅先知"}]}},"cnc_p202":{"desc":"背诵曾几《三衢道中》，不把黄鹂四五声和「两个黄鹂鸣翠柳」记成同一首。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p143","k":1,"why":"背《三衢道中》之前，要先会背「两个黄鹂」，才不会把黄鹂四五声和鸣翠柳记成同一首。"},{"id":"cnc_p201","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《惠崇春江晚景》」，再学「古诗《三衢道中》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「梅子黄时日日晴」的下一句是哪一句？","answer":"D","explanation":"梅子黄的时节天天放晴，小溪走到头，人改走山路。绿阴、黄鹂是后两句。","choices":[{"key":"A","text":"绿阴不减来时路"},{"key":"B","text":"添得黄鹂四五声"},{"key":"C","text":"春风花草香"},{"key":"D","text":"小溪泛尽却山行"}]}},"cnc_p203":{"desc":"抓住燕子的羽毛、翅膀、尾巴，以及电线像五线谱的比方。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p202","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《三衢道中》」，再学「阅读《燕子》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"燕子的外形，课文抓住了哪三处？","answer":"A","explanation":"一身乌黑光亮的羽毛，一对俊俏轻快的翅膀，加上剪刀似的尾巴。","choices":[{"key":"A","text":"羽毛、翅膀和尾巴"},{"key":"B","text":"嘴巴、爪子和眼睛"},{"key":"C","text":"只写了颜色没有写外形"},{"key":"D","text":"荷叶、荷花和莲蓬"}]}},"cnc_p204":{"desc":"抓住荷叶、荷花的样子，以及「我」仿佛自己也变成荷花。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p167","k":1,"why":"读《荷花》之前，要先会抓住写景段落里的景物特点。"},{"id":"cnc_p203","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《燕子》」，再学「阅读《荷花》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"荷叶在课文里是什么样子？","answer":"B","explanation":"荷叶挨挨挤挤，像碧绿的大圆盘。小扇子是《秋天的雨》里的银杏叶。","choices":[{"key":"A","text":"稀疏的，像几根针"},{"key":"B","text":"挨挨挤挤的，像一个个碧绿的大圆盘"},{"key":"C","text":"金黄的，像小扇子"},{"key":"D","text":"红色的，像邮票"}]}},"cnc_p205":{"desc":"读汪曾祺的四则短文，分清复眼、花大姐、独角仙和蚂蚱，不和法布尔的《石蜂》记成同一篇。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p204","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《荷花》」，再学「阅读《昆虫备忘录》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《昆虫备忘录》的作者是谁？","answer":"C","explanation":"这篇是汪曾祺写的备忘录。法布尔写的是后面的《石蜂》。冰心写《肥皂泡》，萧红写《火烧云》。","choices":[{"key":"A","text":"法布尔"},{"key":"B","text":"冰心"},{"key":"C","text":"汪曾祺"},{"key":"D","text":"萧红"}]}},"cnc_p206":{"desc":"能分清「像大圆盘」是比喻，「蜻蜓告诉我」是拟人。口语交际是商量春游去哪儿玩，习作「我的植物朋友」要把看到的样子写出来，用上比喻或拟人。","criteria":["能把句子写通顺","能按要求选用或修改句子"],"root":"","pre":[{"id":"cnc_p183","k":1,"why":"学习比喻和拟人之前，要先会把句子写通顺。"},{"id":"cnc_p204","k":1,"why":"分辨比喻和拟人，要先读过《荷花》里的句子。"},{"id":"cnc_p205","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《昆虫备忘录》」，再学「语文园地一·比喻和拟人」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「荷叶像一个个碧绿的大圆盘」用的是哪一种写法？","answer":"D","explanation":"把荷叶比作大圆盘，是比喻。圆盘不会说话，这里没有把荷叶写成一个人。","choices":[{"key":"A","text":"拟人"},{"key":"B","text":"反问"},{"key":"C","text":"排比"},{"key":"D","text":"比喻"}]}},"cnc_p207":{"desc":"借助注释读懂宋人守着树桩等兔子，从此被宋人耻笑。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p195","k":1,"why":"读《守株待兔》之前，要先会借助注释读懂短文言文。"},{"id":"cnc_p206","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地一·比喻和拟人」，再学「阅读《守株待兔》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"兔子是怎样死的？","answer":"A","explanation":"兔走触株，折颈而死。株是树桩。","choices":[{"key":"A","text":"跑过来撞在树桩上，折断了脖子"},{"key":"B","text":"农夫用箭射死的"},{"key":"C","text":"被狼叼走的"},{"key":"D","text":"自己跳进瓮里"}]}},"cnc_p208":{"desc":"读懂严文井的寓言：掉进陷阱的狼装成狗，摇尾巴骗老山羊，最后露出凶相。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p207","k":1,"why":"读《会摇尾巴的狼》之前，要先会说出《守株待兔》说明的道理。"}],"q":{"type":"choice","difficulty":"basic","prompt":"掉进陷阱、向人求救的是谁？","answer":"B","explanation":"狼自己爬不出来，才向路过的老山羊求助。小鸡是它编出来的借口。","choices":[{"key":"A","text":"一只真的狗"},{"key":"B","text":"一只狼"},{"key":"C","text":"老山羊"},{"key":"D","text":"一只小鸡"}]}},"cnc_p209":{"desc":"读懂鹿先夸角、嫌腿，被狮子追时却是细腿救了它，美丽的角差点害了它。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p207","k":1,"why":"读《鹿角和鹿腿》之前，要先会从寓言里找出做法和结果。"},{"id":"cnc_p208","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《会摇尾巴的狼》」，再学「阅读《鹿角和鹿腿》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"鹿在池塘边先喜欢自己的什么，又讨厌什么？","answer":"C","explanation":"它把角称为精美别致，却嫌腿又细又难看。","choices":[{"key":"A","text":"喜欢细腿，讨厌角"},{"key":"B","text":"喜欢狮子的鬃毛"},{"key":"C","text":"喜欢美丽的角，讨厌细长的腿"},{"key":"D","text":"觉得角和腿都没有用"}]}},"cnc_p210":{"desc":"读克雷洛夫的寓言：池子图安逸，后来干涸；河流不停奔流，才一直有用。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p207","k":1,"why":"读《池子与河流》之前，要先会说出一则寓言的道理。"},{"id":"cnc_p209","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《鹿角和鹿腿》」，再学「阅读《池子与河流》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"池子怎样看待河流？","answer":"D","explanation":"池子觉得自己躺在柔软的泥土里最舒服，反问河流什么时候才能休息。","choices":[{"key":"A","text":"夸它最会休息"},{"key":"B","text":"请它一起守着树桩"},{"key":"C","text":"觉得它已经干涸了"},{"key":"D","text":"嫌它整天奔流，不肯像自己一样安闲地躺着"}]}},"cnc_p211":{"desc":"能说出守株待兔、亡羊补牢、揠苗助长的意思，不把道理用反。口语交际是劝告，习作是看图画，写一写。","criteria":["能理解词语在句子里的意思","能选出搭配恰当的词语"],"root":"","pre":[{"id":"cnc_p138","k":1,"why":"理解「亡羊补牢」之前，要先读过这则寓言。"},{"id":"cnc_p207","k":1,"why":"把守株待兔当成成语来用之前，要先读懂这则文言故事。"},{"id":"cnc_p210","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《池子与河流》」，再学「语文园地二·守株待兔与亡羊补牢」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「守株待兔」用来批评什么样的人？","answer":"A","explanation":"守株待兔是白捡了一次，就不再劳动，坐等下一次。","choices":[{"key":"A","text":"存着侥幸，死守一次偶然经验"},{"key":"B","text":"丢了羊立刻把圈修好"},{"key":"C","text":"肯自己试一试深浅"},{"key":"D","text":"帮助禾苗按时浇水"}]}},"cnc_p212":{"desc":"这次读书吧读寓言：故事不长，读完要说出它说明的道理。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p211","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·守株待兔与亡羊补牢」，再学「快乐读书吧：小故事大道理」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「小故事大道理」主要读哪一类书？","answer":"B","explanation":"守株待兔、伊索寓言、克雷洛夫寓言都是短故事，里面有一个道理。空白本和口诀表不是。","choices":[{"key":"A","text":"只抄课程表"},{"key":"B","text":"寓言"},{"key":"C","text":"没有字的空白本"},{"key":"D","text":"只印乘法口诀的表"}]}},"cnc_p213":{"desc":"读懂海底不是一片静默：有声音，动物的活动方式也各不相同。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p184","k":1,"why":"读《海底世界》之前，要先会按方面读懂《富饶的西沙群岛》。"},{"id":"cnc_p212","k":0,"why":"按统编教材的常见教学顺序，先学「快乐读书吧：小故事大道理」，再学「阅读《海底世界》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"海底有没有声音？","answer":"C","explanation":"有的像蜜蜂嗡嗡，有的像小鸟啾啾，有的像小狗汪汪，有的还像在打鼾。","choices":[{"key":"A","text":"完全没有声音"},{"key":"B","text":"只有行船的声音"},{"key":"C","text":"有。动物会发出各种声音"},{"key":"D","text":"只有人在海底说话"}]}},"cnc_p214":{"desc":"读懂法布尔为验证石蜂认路不靠记忆力所做的实验：带到远处、做上记号、再看谁飞回。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p213","k":1,"why":"读《石蜂》这种实验说明文之前，要先会按顺序读懂一篇说明文。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这篇课文的作者是谁？","answer":"D","explanation":"法布尔把这次实验写进了观察记录。汪曾祺写的是《昆虫备忘录》，不是这篇实验。","choices":[{"key":"A","text":"汪曾祺"},{"key":"B","text":"冰心"},{"key":"C","text":"萧红"},{"key":"D","text":"法布尔"}]}},"cnc_p215":{"desc":"读懂「我」和阿成哥把小溪里的虾养在葡萄架下的缸里，并看出不同虾的样子。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p213","k":1,"why":"读《小虾》之前，要先会从一篇写动物的短文里抓住它的样子和活动。"},{"id":"cnc_p214","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《石蜂》」，再学「阅读《小虾》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"养虾的缸在什么地方？","answer":"A","explanation":"阳光从葡萄架的空隙漏下来，水面像许多圆镜。这口闲着的缸正好养虾。","choices":[{"key":"A","text":"院子里的葡萄架下，夏天积了大半缸雨水"},{"key":"B","text":"在海底的峡谷里"},{"key":"C","text":"在蜂窝旁边"},{"key":"D","text":"在赵州桥下"}]}},"cnc_p216":{"desc":"把一项小实验按顺序写清楚：准备了什么，怎样做，看到什么变化，结果是什么。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p214","k":1,"why":"按步骤写一项小实验之前，要先会按顺序说出《石蜂》的实验过程。"},{"id":"cnc_p215","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《小虾》」，再学「语文园地三·我做了一项小实验」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"写「我做了一项小实验」，哪一种顺序清楚？","answer":"B","explanation":"和《石蜂》一样，实验要让人看出先做什么、后做什么。忽然写吃饭，就把过程写乱了。","choices":[{"key":"A","text":"先写结果，中间插进昨天吃了什么，最后才说用了什么"},{"key":"B","text":"先写准备了什么，再写步骤，接着写看到的变化，最后写结果"},{"key":"C","text":"只写「很好玩」三个字"},{"key":"D","text":"把步骤全部倒过来说"}]}},"cnc_p217":{"desc":"背诵王安石《元日》，知道屠苏是酒，新桃旧符是春联的前身。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p216","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地三·我做了一项小实验」，再学「古诗《元日》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「爆竹声中一岁除」的下一句是哪一句？","answer":"C","explanation":"爆竹送走旧年，人们喝着屠苏酒。千门万户是后两句。","choices":[{"key":"A","text":"千门万户曈曈日"},{"key":"B","text":"总把新桃换旧符"},{"key":"C","text":"春风送暖入屠苏"},{"key":"D","text":"春风送暖入屠城"}]}},"cnc_p218":{"desc":"背诵杜牧《清明》，不把作者记成杜甫，不把杏花村记成酒家自己。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p164","k":1,"why":"背杜牧《清明》之前，要先知道《山行》也是杜牧的，才不会把《清明》记成杜甫的诗。"},{"id":"cnc_p217","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《元日》」，再学「古诗《清明》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「清明时节雨纷纷」的下一句是哪一句？","answer":"D","explanation":"清明细雨，路上的行人伤心极了。借问酒家是后两句。","choices":[{"key":"A","text":"借问酒家何处有"},{"key":"B","text":"牧童遥指杏花村"},{"key":"C","text":"路上行人欲断肠"},{"key":"D","text":"路上行人欲断魂"}]}},"cnc_p219":{"desc":"背诵王维写重阳的诗，知道「山东」指华山以东，不是今天的山东省。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p217","k":1,"why":"背王维的重阳诗之前，要先会背王安石的《元日》，才不会把爆竹屠苏和遍插茱萸记成同一首。"},{"id":"cnc_p218","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《清明》」，再学「古诗《九月九日忆山东兄弟》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「独在异乡为异客」的下一句是哪一句？","answer":"A","explanation":"独自在外地作客，每到节日就更加想念亲人。登高、茱萸是后两句。屠苏是《元日》里的酒。","choices":[{"key":"A","text":"每逢佳节倍思亲"},{"key":"B","text":"遥知兄弟登高处"},{"key":"C","text":"遍插茱萸少一人"},{"key":"D","text":"春风送暖入屠苏"}]}},"cnc_p220":{"desc":"知道纸广泛使用以前字写在甲骨、竹木和帛上，东汉蔡伦改进造纸术后，纸才便宜、方便。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p219","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《九月九日忆山东兄弟》」，再学「阅读《纸的发明》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"纸还没有广泛使用时，人们把字写在哪里？","answer":"B","explanation":"更早还有刻在甲骨上、铸在青铜器上的字。竹简沉重，帛又太贵。","choices":[{"key":"A","text":"只能写在今天的电脑上"},{"key":"B","text":"龟甲兽骨、竹片木片，还有价钱很贵的帛"},{"key":"C","text":"只刻在赵州桥的栏板上"},{"key":"D","text":"写在还没发明的白纸上"}]}},"cnc_p221":{"desc":"知道赵州桥是隋朝李春设计的石拱桥，大拱上有小拱，下面没有桥墩。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p220","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《纸的发明》」，再学「阅读《赵州桥》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"赵州桥是谁设计并参加建造的？","answer":"C","explanation":"赵州桥又叫安济桥，是隋朝石匠李春设计的。","choices":[{"key":"A","text":"宋朝的司马光"},{"key":"B","text":"唐朝的李白"},{"key":"C","text":"隋朝的石匠李春"},{"key":"D","text":"汉朝的曹操"}]}},"cnc_p222":{"desc":"知道这幅画是北宋张择端的《清明上河图》，画的是汴京汴河两岸的热闹生活。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p221","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《赵州桥》」，再学「阅读《一幅名扬中外的画》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文介绍的这幅画叫什么？","answer":"D","explanation":"它名扬中外，画的是北宋都城清明时节的繁华。惠崇的画是另一课里苏轼题诗的那幅。","choices":[{"key":"A","text":"《惠崇春江晚景》"},{"key":"B","text":"赵州桥的设计图"},{"key":"C","text":"一张只有一座桥的地图"},{"key":"D","text":"《清明上河图》"}]}},"cnc_p223":{"desc":"把本单元的诗和传统节日对上：元日是春节，清明是清明节，九月九日是重阳。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p222","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《一幅名扬中外的画》」，再学「语文园地四·中华传统节日」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《元日》写的是哪个节日？","answer":"A","explanation":"爆竹、屠苏酒、换新桃符，都是旧年过去、新年到来时的事。","choices":[{"key":"A","text":"春节，农历正月初一"},{"key":"B","text":"清明节"},{"key":"C","text":"重阳节"},{"key":"D","text":"中秋节"}]}},"cnc_p224":{"desc":"读懂胡萝卜先生的胡子沾上果酱后越来越长，一路被别人派上用场。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p223","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地四·中华传统节日」，再学「阅读《胡萝卜先生的长胡子》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"胡萝卜先生的胡子为什么会变长？","answer":"B","explanation":"果酱沾在胡子上，胡子就停不住地长。这是想象出来的，不是种庄稼。","choices":[{"key":"A","text":"他天天浇水，把胡子当成树苗"},{"key":"B","text":"胡子沾上了果酱，第二天就越来越长"},{"key":"C","text":"狮子追他，吓得胡子变长"},{"key":"D","text":"蔡伦用树皮给他做了一根胡子"}]}},"cnc_p225":{"desc":"读懂英英变成大树以后，妈妈却在树枝上开始野餐。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p224","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《胡萝卜先生的长胡子》」，再学「阅读《我变成了一棵树》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"英英为什么希望变成一棵树？","answer":"C","explanation":"她玩得正高兴，不想被妈妈叫回去，于是希望自己变成一棵树。","choices":[{"key":"A","text":"她想给妈妈遮雨"},{"key":"B","text":"她讨厌自己的名字"},{"key":"C","text":"这样妈妈就找不到她，她可以继续在外面玩"},{"key":"D","text":"树上有作业要写"}]}},"cnc_p226":{"desc":"大胆想象一件奇事，同时围绕这一个意思把话写清楚，不忽然换成不相干的内容。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p169","k":1,"why":"围绕一个意思写一段话之前，要先会在日记里把看到的内容写清楚。"},{"id":"cnc_p225","k":1,"why":"围绕一个意思写之前，要先看出《我变成了一棵树》整篇都在写同一件事。"}],"q":{"type":"choice","difficulty":"basic","prompt":"写「一支铅笔的梦想」，哪一段是围绕一个意思的？","answer":"D","explanation":"这几句都在写铅笔的这一个梦。忽然写晚饭或数学，就离开了这个意思。","choices":[{"key":"A","text":"铅笔梦见自己变成小船。昨天晚饭我吃了面条。"},{"key":"B","text":"梦想。数学。足球。"},{"key":"C","text":"铅笔。面条。下课。"},{"key":"D","text":"铅笔梦见自己变成小船，在作业本的格子河里给字送信。"}]}},"cnc_p227":{"desc":"读张继楼的三首小诗：溪边钓鱼、江上戏水、林中采蘑菇。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p226","k":0,"why":"按统编教材的常见教学顺序，先学「习作：奇妙的想象」，再学「阅读《童年的水墨画》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《童年的水墨画》的作者是谁？课文是哪三首小诗？","answer":"A","explanation":"三首分别写溪边钓鱼、江上游泳、雨后的松林。冰心写的是《肥皂泡》。","choices":[{"key":"A","text":"张继楼。溪边、江上、林中"},{"key":"B","text":"冰心。街头、溪边、江上"},{"key":"C","text":"萧红。只有溪边一首"},{"key":"D","text":"法布尔。石蜂、小虾、蚂蚱"}]}},"cnc_p228":{"desc":"读冰心《肥皂泡》，感受肥皂泡的轻、圆和美丽。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p227","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《童年的水墨画》」，再学「阅读《肥皂泡》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《肥皂泡》的作者是谁？","answer":"B","explanation":"《肥皂泡》是冰心的散文。萧红写的是《火烧云》。","choices":[{"key":"A","text":"萧红"},{"key":"B","text":"冰心"},{"key":"C","text":"法布尔"},{"key":"D","text":"叶圣陶"}]}},"cnc_p229":{"desc":"读懂列宁看见深红胸脯的灰雀不见了，男孩后来把鸟放回枝头。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p228","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《肥皂泡》」，再学「阅读《灰雀》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"公园白桦树上原来有几只灰雀？胸脯是什么颜色？","answer":"C","explanation":"列宁每天都来看这三只灰雀。不见的是胸脯深红色的那一只。","choices":[{"key":"A","text":"一只，全身雪白"},{"key":"B","text":"两只，都是深红"},{"key":"C","text":"三只。两只粉红，一只深红"},{"key":"D","text":"五只，全是灰色没有别的颜色"}]}},"cnc_p230":{"desc":"读懂宋庆龄想起要教小珍叠花篮，宁可不去看鸽子，也要守住约定。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p229","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《灰雀》」，再学「阅读《我不能失信》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文里的「我」是谁？她不能失信于谁？","answer":"D","explanation":"一个早晨，宋耀如一家准备出门。二女儿宋庆龄想起昨天对小珍的约定。","choices":[{"key":"A","text":"列宁。不能失信于灰雀"},{"key":"B","text":"英英。不能失信于妈妈"},{"key":"C","text":"蔡伦。不能失信于李春"},{"key":"D","text":"宋庆龄。不能失信于小珍"}]}},"cnc_p231":{"desc":"写身边的人要写出特点，用一件具体的事来表现，不要只堆形容词。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p230","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《我不能失信》」，再学「语文园地六·身边那些有特点的人」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"写一个有特点的人，哪一段更清楚？","answer":"A","explanation":"急，要写成看得见的动作。只重复「很好」，别人不知道好在哪里。","choices":[{"key":"A","text":"弟弟做事很急。鞋带还拖着，他已经冲到了操场上。"},{"key":"B","text":"弟弟很好，非常好，特别好。"},{"key":"C","text":"弟弟。操场。昨天的面条。"},{"key":"D","text":"我的同桌是一个人。"}]}},"cnc_p232":{"desc":"读萧红《火烧云》，抓住颜色和形状变得快。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p231","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地六·身边那些有特点的人」，再学「阅读《火烧云》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《火烧云》的作者是谁？","answer":"B","explanation":"《火烧云》是萧红的课文。《肥皂泡》才是冰心的。","choices":[{"key":"A","text":"冰心"},{"key":"B","text":"萧红"},{"key":"C","text":"叶圣陶"},{"key":"D","text":"法布尔"}]}},"cnc_p233":{"desc":"按起风前、起风后的顺序，看出天气、动物和人们怎样变得不平常。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p232","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《火烧云》」，再学「阅读《暴风雨来临之前》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"暴风雨还没来的时候，天气首先有什么变化？","answer":"C","explanation":"树木和草都变得昏暗。这是起风以前的压抑，不是火烧云那种红光。","choices":[{"key":"A","text":"太阳更亮，天空更蓝"},{"key":"B","text":"立刻下起了整天的雪"},{"key":"C","text":"空气越来越沉闷，太阳被云遮住，奇形怪状的乌云蔓延过来"},{"key":"D","text":"天空一直没有云"}]}},"cnc_p234":{"desc":"读彼得·西摩的课文，分清天空和大地两方面的奇妙。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p213","k":1,"why":"从天空和大地两方面读《我们奇妙的世界》之前，要先会按方面读懂《海底世界》。"},{"id":"cnc_p233","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《暴风雨来临之前》」，再学「阅读《我们奇妙的世界》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这篇课文的作者是谁？","answer":"D","explanation":"《我们奇妙的世界》是彼得·西摩的作品。萧红写《火烧云》，不要记成同一个人。","choices":[{"key":"A","text":"萧红"},{"key":"B","text":"冰心"},{"key":"C","text":"法布尔"},{"key":"D","text":"英国作家彼得·西摩"}]}},"cnc_p235":{"desc":"分几方面介绍大熊猫：样子、食物、住在哪里，以及为什么称它国宝。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p234","k":1,"why":"分几方面介绍大熊猫之前，要先会看出《我们奇妙的世界》是从天空和大地两方面写的。"}],"q":{"type":"choice","difficulty":"basic","prompt":"介绍大熊猫，哪一段是分方面写的？","answer":"A","explanation":"样子、食物、地方，三方面都在说大熊猫。只重复可爱，别人还是不了解它。海参不是它的食物。","choices":[{"key":"A","text":"它身子白色，眼圈、耳朵和四肢是黑色的。它最爱吃竹子，生活在中国的山区。"},{"key":"B","text":"大熊猫很可爱，非常可爱，特别可爱。"},{"key":"C","text":"大熊猫。昨天的足球。面条。"},{"key":"D","text":"它住在海底，主食是海参。"}]}},"cnc_p236":{"desc":"读懂一个急着要衣服、一个做事很慢，故事因此又等又好笑。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p235","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地七·国宝大熊猫」，再学「阅读《慢性子裁缝和急性子顾客》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"顾客是什么性子，裁缝是什么性子？","answer":"B","explanation":"题目已经把两个人的性格对上了：裁缝慢，顾客急。","choices":[{"key":"A","text":"两个都是急性子"},{"key":"B","text":"顾客急性子，裁缝慢性子"},{"key":"C","text":"顾客慢性子，裁缝急性子"},{"key":"D","text":"两个都没有性子"}]}},"cnc_p237":{"desc":"读懂老虎和贼都把「漏」当成怪物，其实老婆婆说的是房子漏雨。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p236","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《慢性子裁缝和急性子顾客》」，再学「阅读《漏》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"老婆婆说的「漏」本来是什么？","answer":"C","explanation":"老公公和老婆婆说，管他狼哩，管他虎哩，就怕漏。他们怕的是屋子漏雨。","choices":[{"key":"A","text":"一只名叫漏的怪兽"},{"key":"B","text":"老虎的名字"},{"key":"C","text":"房子会漏雨"},{"key":"D","text":"贼的外号"}]}},"cnc_p238":{"desc":"读懂枣核只有枣核那么大，却能帮家里干活，还能把被抢走的牲口要回来。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p237","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《漏》」，再学「阅读《枣核》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"孩子为什么叫枣核？","answer":"D","explanation":"夫妻俩成天盼着孩子。孩子生下来只有枣核那么大，就叫枣核。","choices":[{"key":"A","text":"因为他最爱吃枣"},{"key":"B","text":"因为他长得像一座桥"},{"key":"C","text":"因为县官给他起的名字"},{"key":"D","text":"父母说哪怕有个枣核那么大的孩子也好，后来真生了一个这么大的孩子"}]}},"cnc_p239":{"desc":"讲故事要说清谁遇到了什么、好笑在哪里。习作「这样想象真有趣」要大胆想，也要让人听得懂。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p238","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《枣核》」，再学「语文园地八·趣味故事会」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"在趣味故事会上讲《漏》，哪一种讲法清楚？","answer":"A","explanation":"听众要知道人物、误会和结果。只丢出一个名字，故事还没开始。","choices":[{"key":"A","text":"先说老婆婆怕的是漏雨，再说老虎和贼都把对方当成了怪物"},{"key":"B","text":"只说有个老婆婆"},{"key":"C","text":"从老虎被吓跑讲起，却不说漏是什么"},{"key":"D","text":"把枣核和裁缝也说成是同一只老虎"}]}},"cnc_p240":{"desc":"按潮来前、潮来时、潮头过后的顺序说出钱塘江大潮的变化。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p204","k":1,"why":"按顺序概括写景课文之前，要先会找出景物特点。"},{"id":"cnc_p239","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地八·趣味故事会」，再学「阅读《观潮》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"潮还没有来的时候，江面是怎样的？","answer":"B","explanation":"课文先写江面平静，人们等着潮来。白线和战马都是潮来时的样子。","choices":[{"key":"A","text":"已经排起一条白线"},{"key":"B","text":"风平浪静"},{"key":"C","text":"千万匹战马一齐奔来"},{"key":"D","text":"余波还在漫天卷地"}]}},"cnc_p241":{"desc":"读懂巴金的散文：从前在家乡、三年前在南京、如今在海上，三次看繁星的情景和感受不同。不要和冰心的短诗《繁星》记成同一篇。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p240","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《观潮》」，再学「阅读《繁星》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这篇散文《繁星》的作者是谁？","answer":"C","explanation":"三次看星这篇是巴金写的。冰心的《繁星》是短诗，在四年级下册。刘大白、徐志摩写的是现代诗二首。","choices":[{"key":"A","text":"冰心"},{"key":"B","text":"刘大白"},{"key":"C","text":"巴金"},{"key":"D","text":"徐志摩"}]}},"cnc_p242":{"desc":"读刘大白《秋晚的江上》和徐志摩《花牛歌》：归巢的鸟把斜阳掉在江上，花牛在草地里坐、眠、走、做梦。两首合为一个 topic。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p241","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《繁星》」，再学「现代诗二首」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《秋晚的江上》和《花牛歌》的作者分别是谁？","answer":"D","explanation":"秋晚那首是刘大白的，花牛那首是徐志摩的。巴金写散文《繁星》。","choices":[{"key":"A","text":"巴金和冰心"},{"key":"B","text":"叶圣陶和法布尔"},{"key":"C","text":"王翰和王昌龄"},{"key":"D","text":"刘大白和徐志摩"}]}},"cnc_p243":{"desc":"能按词语选定多音字的读音，不拿一个音套所有词。口语交际「我们与环境」要说出身边的环境问题，也可以说说能做的小事。习作「推荐一个好地方」要把那个地方的特点和值得去的理由写清楚。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p137","k":1,"why":"再认多音字之前，要先会按词选定读音。"},{"id":"cnc_p242","k":0,"why":"按统编教材的常见教学顺序，先学「现代诗二首」，再学「语文园地一·多音字：朝、涨、似、还」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「朝霞」的「朝」读哪一个？","answer":"A","explanation":"朝霞、朝阳的朝读 zhāo，是早晨。朝代、朝廷才读 cháo。","choices":[{"key":"A","text":"zhāo"},{"key":"B","text":"cháo"},{"key":"C","text":"zhào"},{"key":"D","text":"cáo"}]}},"cnc_p244":{"desc":"读懂安徒生的童话：五粒豌豆各奔东西，落在窗下青苔缝里的那一粒发了芽，给生病的小女孩带来希望。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p243","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地一·多音字：朝、涨、似、还」，再学「阅读《一个豆荚里的五粒豆》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这篇童话的作者是谁？","answer":"B","explanation":"五粒豆的故事是安徒生写的。叶至善写《一只窝囊的大老虎》，高洪波写《陀螺》。","choices":[{"key":"A","text":"叶至善"},{"key":"B","text":"安徒生"},{"key":"C","text":"高洪波"},{"key":"D","text":"巴金"}]}},"cnc_p245":{"desc":"读懂科学家怎样做实验：蝙蝠夜里飞行靠的是嘴里发出超声波、耳朵接收回声，不是靠眼睛。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p244","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《一个豆荚里的五粒豆》」，再学「阅读《夜间飞行的秘密》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"科学家要弄清的是什么？","answer":"C","explanation":"课文围绕夜间飞行来写。填海、花牛、帽子是另外几篇。","choices":[{"key":"A","text":"蝙蝠怎样把东海填平"},{"key":"B","text":"花牛怎样在草地里做梦"},{"key":"C","text":"蝙蝠夜里是怎样避开障碍物飞行的"},{"key":"D","text":"方帽子为什么比圆帽子好看"}]}},"cnc_p246":{"desc":"读懂这篇童话：店里只卖方帽子，后来圆帽子流行，老板不肯改，最后只剩他自己戴方的。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p245","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《夜间飞行的秘密》」，再学「阅读《方帽子店》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这家店开头只卖什么样的帽子？","answer":"D","explanation":"很久以前大家都戴方帽子，店里也只做这一种。","choices":[{"key":"A","text":"圆帽子"},{"key":"B","text":"兵马俑的头盔"},{"key":"C","text":"老虎演出用的头罩"},{"key":"D","text":"方帽子"}]}},"cnc_p247":{"desc":"读懂孙膑让田忌以下等马对上等马、中等对下等、上等对中等，二胜一负赢了齐威王。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p246","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《方帽子店》」，再学「阅读《田忌赛马》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"给田忌出主意的人是谁？","answer":"A","explanation":"孙膑观察了双方的马，才想出换对阵的办法。齐威王是对手。","choices":[{"key":"A","text":"孙膑"},{"key":"B","text":"齐威王"},{"key":"C","text":"王戎"},{"key":"D","text":"周恩来"}]}},"cnc_p248":{"desc":"能按中间部分选出辨、辩、辫、瓣，不看半边就乱写。习作「我的家人」要把家里一个人的样子和一件事写具体。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p247","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《田忌赛马》」，再学「语文园地二·形近字：辨、辩、辫、瓣」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「分清对和错」该用哪一个字？","answer":"B","explanation":"辨别的中间是点撇。辩论中间是言，辫子中间是纟，花瓣中间是瓜。","choices":[{"key":"A","text":"辩"},{"key":"B","text":"辨"},{"key":"C","text":"辫"},{"key":"D","text":"瓣"}]}},"cnc_p249":{"desc":"能按意思选用在、再、做、作，不因为读音相同就随便写。和形近字一起放在语文园地二。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p248","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·形近字：辨、辩、辫、瓣」，再学「语文园地二·同音字：在和再、做和作」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「我____教室里读书。」横线处该填哪一个？","answer":"C","explanation":"在表示地点。再表示又一次。","choices":[{"key":"A","text":"再"},{"key":"B","text":"做"},{"key":"C","text":"在"},{"key":"D","text":"作"}]}},"cnc_p250":{"desc":"背诵白居易《暮江吟》，分清残阳、瑟瑟和真珠各写什么。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p249","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·同音字：在和再、做和作」，再学「古诗《暮江吟》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「一道残阳铺水中」的下一句是哪一句？","answer":"D","explanation":"江面一半是深青，一半被残阳照红。后两句才写九月初三的夜。","choices":[{"key":"A","text":"半江瑟瑟半江蓝"},{"key":"B","text":"露似真珠月似弓"},{"key":"C","text":"可怜九月初三夜"},{"key":"D","text":"半江瑟瑟半江红"}]}},"cnc_p251":{"desc":"背诵苏轼《题西林壁》，记住「只缘」和「各不同」，不把字改掉。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p190","k":1,"why":"理解《题西林壁》之前，要先会背写山水的绝句。"},{"id":"cnc_p250","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《暮江吟》」，再学「古诗《题西林壁》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「横看成岭侧成峰」的下一句是哪一句？","answer":"A","explanation":"从不同的距离、不同的高度看，山的样子各不相同。","choices":[{"key":"A","text":"远近高低各不同"},{"key":"B","text":"远近高低都不同"},{"key":"C","text":"远近高低各相同"},{"key":"D","text":"不识庐山真面目"}]}},"cnc_p252":{"desc":"背诵卢梅坡《雪梅》，知道梅和雪各有所长：雪更白，梅有香。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p251","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《题西林壁》」，再学「古诗《雪梅》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「梅雪争春未肯降」的下一句是哪一句？","answer":"B","explanation":"梅和雪都说自己更能代表春，诗人搁下笔，不好立刻评判。","choices":[{"key":"A","text":"梅须逊雪三分白"},{"key":"B","text":"骚人阁笔费评章"},{"key":"C","text":"雪却输梅一段香"},{"key":"D","text":"远近高低各不同"}]}},"cnc_p253":{"desc":"读懂叶圣陶怎样观察爬山虎的脚：长在茎上，触墙才巴住。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p252","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《雪梅》」，再学「阅读《爬山虎的脚》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"爬山虎的脚长在哪里？","answer":"C","explanation":"叶圣陶写细丝一样的脚长在茎上，不是长在花上。","choices":[{"key":"A","text":"叶子尖上"},{"key":"B","text":"花心里"},{"key":"C","text":"茎上"},{"key":"D","text":"根的最底下，茎上没有"}]}},"cnc_p254":{"desc":"读懂法布尔怎样观察蟋蟀的住宅：自己挖掘，倾斜的隧道，门口有平台，内部光滑。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p253","k":1,"why":"读《蟋蟀的住宅》之前，要先会读《爬山虎的脚》，两篇都要把观察到的部位写清楚。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《蟋蟀的住宅》的作者是谁？","answer":"D","explanation":"这篇是法布尔写昆虫的。叶圣陶写爬山虎，屠格涅夫写麻雀。","choices":[{"key":"A","text":"叶圣陶"},{"key":"B","text":"安徒生"},{"key":"C","text":"屠格涅夫"},{"key":"D","text":"法布尔"}]}},"cnc_p255":{"desc":"能分辨意思接近但不能随便替换的词，如发现和发明、改正和改进。口语交际「爱护眼睛，保护视力」要说出护眼的做法。习作「写观察日记」要把连续几天看到的变化写下来。","criteria":["能理解词语在句子里的意思","能选出搭配恰当的词语"],"root":"","pre":[{"id":"cnc_p089","k":1,"why":"辨析近义词之前，要先会分辨意思相反的词。"},{"id":"cnc_p254","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《蟋蟀的住宅》」，再学「语文园地三·近义词辨析」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"已经有的问题被看出来了，该用哪一个？","answer":"A","explanation":"发现是看到本来就存在的事物。发明是创造出原来没有的东西。","choices":[{"key":"A","text":"发现"},{"key":"B","text":"发明"},{"key":"C","text":"发生"},{"key":"D","text":"发挥"}]}},"cnc_p256":{"desc":"读懂盘古把混沌的天地劈开，身体后来化成世间万物。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p255","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地三·近义词辨析」，再学「阅读《盘古开天地》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"盘古醒来以前，天地是怎样的？","answer":"B","explanation":"那时候天和地还没有分开，混在一起。","choices":[{"key":"A","text":"已经分成了山和海"},{"key":"B","text":"混沌得像一个大鸡蛋"},{"key":"C","text":"像一座方帽子店"},{"key":"D","text":"像一条钱塘江的白线"}]}},"cnc_p257":{"desc":"读懂精卫是炎帝的女儿淹死后化成的鸟，衔西山木石去填东海。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p207","k":1,"why":"读神话之前，要先会说出故事说明的道理。"},{"id":"cnc_p256","k":1,"why":"读《精卫填海》之前，要先读《盘古开天地》，才不会把开天和填海记成同一则神话。"}],"q":{"type":"choice","difficulty":"basic","prompt":"精卫是怎样变成鸟的？","answer":"C","explanation":"炎帝的小女儿女娃在东海溺死后，化成了精卫。","choices":[{"key":"A","text":"她本来就是一只鸟"},{"key":"B","text":"她是龙王变成的"},{"key":"C","text":"在东海淹死以后化成的"},{"key":"D","text":"她从西山的石头里蹦出来"}]}},"cnc_p258":{"desc":"读懂普罗米修斯从太阳车上取火给人类，被锁在高加索山上，神鹰啄肝，后来被救。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p256","k":1,"why":"读《普罗米修斯》之前，要先读《盘古开天地》，才不会把盗火和开天记成同一个故事。"},{"id":"cnc_p257","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《精卫填海》」，再学「阅读《普罗米修斯》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"普罗米修斯为人类做了什么？","answer":"D","explanation":"人类原先没有火。他冒险把火带到了人间。开天、补天、填海是另外几则。","choices":[{"key":"A","text":"把东海填平"},{"key":"B","text":"把塌了的天补好"},{"key":"C","text":"把混沌的天地劈开"},{"key":"D","text":"从太阳车上取来火种"}]}},"cnc_p259":{"desc":"读懂女娲炼五色石补天，并分清这和精卫填海不是同一件事。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p257","k":1,"why":"读《女娲补天》之前，要先会读一则神话，才不会把补天和填海记成同一件事。"},{"id":"cnc_p258","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《普罗米修斯》」，再学「阅读《女娲补天》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"天塌以后，女娲用什么补天？","answer":"A","explanation":"她拣来五色石，炼成石浆，把天上的窟窿补上。精卫衔的才是木石。","choices":[{"key":"A","text":"炼好的五色石"},{"key":"B","text":"西山的小树枝"},{"key":"C","text":"道旁的李子"},{"key":"D","text":"萤火虫"}]}},"cnc_p260":{"desc":"想象自己和一位人物过一天，写出一起做了什么、看见了什么。横线上可以是神话里的人，也可以是身边的人，但一天里的事情要能连起来。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p259","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《女娲补天》」，再学「语文园地四·习作：我和____过一天」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一种更像「我和____过一天」？","answer":"B","explanation":"要写出是谁，还要写出这一天做了哪些事。只写名字或只写题目，一天还没开始。","choices":[{"key":"A","text":"女娲。"},{"key":"B","text":"我和女娲过一天：跟着去拣五色石，看她把天补上"},{"key":"C","text":"过一天。"},{"key":"D","text":"我和谁都没写，只抄了课题"}]}},"cnc_p261":{"desc":"这次读书吧读神话和传说，去看盘古、女娲、精卫这样「很久很久以前」的故事，不要把神话当成科学实验的记录。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p260","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地四·习作：我和____过一天」，再学「快乐读书吧：很久很久以前」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「很久很久以前」主要读哪一类书？","answer":"C","explanation":"很久很久以前，是神话开头常用的说法。空白本和口诀表不是这次要读的。","choices":[{"key":"A","text":"只抄当天的课程表"},{"key":"B","text":"一本空白笔记本"},{"key":"C","text":"神话和传说，比如开天、补天、填海这样的故事"},{"key":"D","text":"只印着乘法口诀的表"}]}},"cnc_p262":{"desc":"读懂老麻雀飞下来掩护掉在地上的小麻雀，猎狗因此退开。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p261","k":0,"why":"按统编教材的常见教学顺序，先学「快乐读书吧：很久很久以前」，再学「阅读《麻雀》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"小麻雀当时在哪里？","answer":"D","explanation":"小麻雀才长出羽毛，从树上掉在猎狗面前。","choices":[{"key":"A","text":"还在巢里没有出来"},{"key":"B","text":"站在猎狗背上"},{"key":"C","text":"飞到了海里"},{"key":"D","text":"从巢里掉到地上"}]}},"cnc_p263":{"desc":"读懂「我」和爸爸爬黄山天都峰，遇到一位年纪像爷爷的老爷爷，两个人互相鼓劲，都爬了上去。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p262","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《麻雀》」，再学「阅读《爬天都峰》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「我」和谁一起去爬天都峰？","answer":"A","explanation":"假日里，爸爸带「我」去爬黄山的天都峰。金奎叔在《牛和鹅》里。","choices":[{"key":"A","text":"爸爸"},{"key":"B","text":"金奎叔"},{"key":"C","text":"孙膑"},{"key":"D","text":"老麻雀"}]}},"cnc_p264":{"desc":"写生活里看到的景物或发生的事情，加上颜色、声音、动作或比喻，让句子具体。例文《我家的杏熟了》写杏子的样子和变化，《小木船》写两个朋友为一只小木船闹别扭又和好。两篇都是例子，不单独立成课文。本单元没有语文园地。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p226","k":1,"why":"写「生活万花筒」、把景物或事情写具体之前，要先会围绕一个意思把话写清楚。"},{"id":"cnc_p206","k":1,"why":"把景物或事情写具体，要用上已经学过的比喻。"},{"id":"cnc_p263","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《爬天都峰》」，再学「习作：生活万花筒 ·把景物/事情写具体」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一句把家里的景物写具体了？","answer":"B","explanation":"例文《我家的杏熟了》会写出颜色和动态。只写「熟了」，别人看不见。","choices":[{"key":"A","text":"杏熟了。"},{"key":"B","text":"杏子熟了，风一吹，黄澄澄的果子在枝头轻轻晃"},{"key":"C","text":"我家有杏。"},{"key":"D","text":"生活万花筒。"}]}},"cnc_p265":{"desc":"读懂这篇说明文：远看长城像长龙，东起山海关、西到嘉峪关；近看条石筑成，有垛子、瞭望口和射口。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p264","k":0,"why":"按统编教材的常见教学顺序，先学「习作：生活万花筒 ·把景物/事情写具体」，再学「阅读《长城》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"远看长城像什么？","answer":"C","explanation":"很长，又随着山势弯曲，所以说像长龙。豌豆、花牛、麻雀是另外几篇。","choices":[{"key":"A","text":"一粒发芽的豌豆"},{"key":"B","text":"一头在草地里做梦的花牛"},{"key":"C","text":"一条长龙，在崇山峻岭之间蜿蜒盘旋"},{"key":"D","text":"一只从树上扑下来的麻雀"}]}},"cnc_p266":{"desc":"按长廊、万寿山、昆明湖的顺序读这篇课文，知道这是四年级上册的正式课文，不要和四年级下册习作例文里的《颐和园》混成同一个知识点。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p265","k":1,"why":"读《颐和园》之前，要先会读《长城》这样介绍一处建筑的课文。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这篇课文《颐和园》主要按什么顺序写？","answer":"D","explanation":"移步换景：长廊、佛香阁、昆明湖和十七孔桥。兵马俑、观潮、麻雀是另外几篇。","choices":[{"key":"A","text":"先看兵马俑，再看山海关"},{"key":"B","text":"先写潮来前，再写潮来时"},{"key":"C","text":"先写老麻雀扑下来，再写猎狗后退"},{"key":"D","text":"先走长廊，再上万寿山，再看昆明湖"}]}},"cnc_p267":{"desc":"读懂这篇说明文：秦始皇陵出土的兵马俑规模宏大，有将军俑、武士俑等，神态各异。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p265","k":1,"why":"读《秦兵马俑》之前，要先会读《长城》，两处都是中国的世界文化遗产。"},{"id":"cnc_p266","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《颐和园》」，再学「阅读《秦兵马俑》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"兵马俑是在哪里出土的？","answer":"A","explanation":"它是秦始皇陵的陪葬坑。潮、天都峰、会见菲科是另外几篇。","choices":[{"key":"A","text":"陕西，秦始皇陵附近"},{"key":"B","text":"杭州的钱塘江边"},{"key":"C","text":"黄山的天都峰上"},{"key":"D","text":"意大利的众议院"}]}},"cnc_p268":{"desc":"口语交际「我是小小讲解员」要把一处地方的特点讲清楚，让别人听得见重点。习作「中国的世界文化遗产」可以写长城、颐和园或兵马俑，按看到的顺序介绍，不要只剩一个名字。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p267","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《秦兵马俑》」，再学「语文园地六·我是小小讲解员」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"当小小讲解员，哪一种把一处地方讲清楚了？","answer":"B","explanation":"样子、材料、东西两端，听的人才跟得上。只说「好看」，还没有讲。","choices":[{"key":"A","text":"这是一个地方。"},{"key":"B","text":"长城远看像长龙，近看是条石砌的城墙，东到山海关，西到嘉峪关"},{"key":"C","text":"很好看。"},{"key":"D","text":"文化遗产四个字。"}]}},"cnc_p269":{"desc":"读懂「我」原先怕鹅，金奎叔抓住鹅以后，「我」才敢自己看事情。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p268","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地六·我是小小讲解员」，再学「阅读《牛和鹅》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"大家原先怎样说鹅？","answer":"C","explanation":"他们说牛看人觉得人比牛大，鹅看人觉得人比鹅小。","choices":[{"key":"A","text":"鹅看见人就逃走"},{"key":"B","text":"鹅和牛一样老实"},{"key":"C","text":"鹅把人看得比自己小，所以敢欺负人"},{"key":"D","text":"鹅不会叫"}]}},"cnc_p270":{"desc":"读懂叶至善写自己演老虎：同学说不会豁虎跳就不算老虎，老师说不用，演出时台下哄堂大笑，他至今还不明白为什么。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p269","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《牛和鹅》」，再学「阅读《一只窝囊的大老虎》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《一只窝囊的大老虎》的作者是谁？写的是什么事？","answer":"D","explanation":"这篇是叶至善的回忆。陀螺、牛和鹅、麻雀是另外几篇。","choices":[{"key":"A","text":"高洪波。写抽陀螺"},{"key":"B","text":"任溶溶。写金奎叔抓鹅"},{"key":"C","text":"屠格涅夫。写老麻雀护幼"},{"key":"D","text":"叶至善。写自己在班级演出里扮老虎"}]}},"cnc_p271":{"desc":"读懂高洪波写童年抽陀螺：故乡叫冰尜儿，叔叔送的一只其貌不扬的小陀螺，却战胜了大陀螺。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p270","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《一只窝囊的大老虎》」，再学「阅读《陀螺》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《陀螺》的作者是谁？故乡把陀螺叫什么？","answer":"A","explanation":"冰尜儿就是冰上抽的陀螺。豁虎跳是演老虎时的动作。","choices":[{"key":"A","text":"高洪波。叫冰尜儿"},{"key":"B","text":"叶至善。叫豁虎跳"},{"key":"C","text":"法布尔。叫住宅"},{"key":"D","text":"巴金。叫繁星"}]}},"cnc_p272":{"desc":"读懂王戎为什么不摘路边的李子：树在道边却果实累累，一定是苦的。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p195","k":1,"why":"读《王戎不取道旁李》之前，要先会读短文言文。"},{"id":"cnc_p271","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《陀螺》」，再学「文言文《王戎不取道旁李》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"孩子们看见道边的李树怎样？","answer":"B","explanation":"看道边李树多子折枝，果子多得把树枝都压弯了。","choices":[{"key":"A","text":"一颗李子也没有"},{"key":"B","text":"果实压弯了树枝"},{"key":"C","text":"李子已经被人摘光"},{"key":"D","text":"树上结的是桃子"}]}},"cnc_p273":{"desc":"能把因为和所以、虽然和但是配成一对，不交叉使用。口语交际「安慰」要听出对方心里难受，再说得让人宽一点。习作「我的心儿怦怦跳」要把那件让心跳加快的事和当时的心情写具体。","criteria":["能把句子写通顺","能按要求选用或修改句子"],"root":"","pre":[{"id":"cnc_p206","k":1,"why":"用关联词连接分句之前，要先会把句子写具体。"},{"id":"cnc_p272","k":0,"why":"按统编教材的常见教学顺序，先学「文言文《王戎不取道旁李》」，再学「语文园地七·关联词：因为所以、虽然但是」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「____今天下雨，____运动会改期了。」哪一组填得对？","answer":"C","explanation":"下雨是原因，改期是结果，用因为……所以……。","choices":[{"key":"A","text":"因为……但是……"},{"key":"B","text":"虽然……所以……"},{"key":"C","text":"因为……所以……"},{"key":"D","text":"既……但是……"}]}},"cnc_p274":{"desc":"读懂2019年习近平主席在意大利会见众议长菲科：菲科问当选时的心情，主席以「我将无我，不负人民」作答，并举举重运动员说明能担起建设国家的重担。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p273","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地七·关联词：因为所以、虽然但是」，再学「阅读《我将无我，不负人民》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文写的会见发生在哪里？对方是谁？","answer":"D","explanation":"2019年3月22日下午，会见临近结束时，菲科突然提问。魏校长在下一课。","choices":[{"key":"A","text":"在沈阳的东关模范学校，对方是魏校长"},{"key":"B","text":"在延安的枣园，对方是一位老爷爷"},{"key":"C","text":"在钱塘江边，对方是观潮的人"},{"key":"D","text":"在意大利众议院，对方是众议长菲科"}]}},"cnc_p275":{"desc":"读懂少年周恩来在沈阳东关模范学校立下志向：为中华之崛起而读书。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p274","k":1,"why":"读《为中华之崛起而读书》之前，要先读《我将无我，不负人民》，两篇都在写把国家和人民放在自己前面。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文里立下这个志向的少年是谁？当时在哪所学校？","answer":"A","explanation":"十二岁前后，他在沈阳读书。会见菲科是上一篇，赛马和李子是前面的课文。","choices":[{"key":"A","text":"周恩来。在沈阳的东关模范学校"},{"key":"B","text":"孙膑。在齐国赛马"},{"key":"C","text":"王戎。在道旁的李树下"},{"key":"D","text":"习近平主席。在意大利众议院"}]}},"cnc_p276":{"desc":"读懂祁念曾的诗：像燕子追寻春光那样追寻延安，要的是信念和脊梁，不是把高楼和电器丢掉。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p275","k":1,"why":"读《延安，我把你追寻》之前，要先会读《为中华之崛起而读书》，才不会把少年立志和追寻延安精神记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《延安，我把你追寻》是一首什么？作者追寻的是哪里？","answer":"B","explanation":"像归来的燕子、像成长的小树，都是诗里的比方。兵马俑、豆、李子是另外几篇。","choices":[{"key":"A","text":"说明文。介绍秦兵马俑"},{"key":"B","text":"诗。追寻延安"},{"key":"C","text":"童话。写五粒豆"},{"key":"D","text":"文言文。写王戎"}]}},"cnc_p277":{"desc":"背诵王翰《凉州词》，分清它和王昌龄《出塞》不是同一首。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p252","k":1,"why":"背《凉州词》之前，要先会背本册第三单元的古诗，才不会把雪梅和葡萄美酒装进同一首。"},{"id":"cnc_p276","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《延安，我把你追寻》」，再学「古诗《凉州词》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「葡萄美酒夜光杯」的下一句是哪一句？","answer":"C","explanation":"正要举杯，马上的琵琶已经催人出发。醉卧沙场是后两句。秦时明月是《出塞》。","choices":[{"key":"A","text":"醉卧沙场君莫笑"},{"key":"B","text":"秦时明月汉时关"},{"key":"C","text":"欲饮琵琶马上催"},{"key":"D","text":"生当作人杰"}]}},"cnc_p278":{"desc":"背诵王昌龄《出塞》，分清它和王翰《凉州词》不是同一首。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p251","k":1,"why":"背诵边塞诗之前，要先会背本册更早的古诗。"},{"id":"cnc_p277","k":1,"why":"背《出塞》之前，要先会背同课的《凉州词》，两首边塞诗才不会串句。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「秦时明月汉时关」的下一句是哪一句？","answer":"D","explanation":"出塞先写远征的人还没有回来。是万里，不是千里；是未还，不是未归。","choices":[{"key":"A","text":"但使龙城飞将在"},{"key":"B","text":"万里长征人未归"},{"key":"C","text":"千里长征人未还"},{"key":"D","text":"万里长征人未还"}]}},"cnc_p279":{"desc":"背诵李清照《夏日绝句》，记住人杰、鬼雄和不肯过江东。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p278","k":1,"why":"背《夏日绝句》之前，要先会背《出塞》，才不会把人杰和飞将装进同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「生当作人杰」的下一句是哪一句？","answer":"A","explanation":"先说活着要做人中的豪杰，死了也要做鬼中的英雄。诗中是鬼雄，不是英雄。","choices":[{"key":"A","text":"死亦为鬼雄"},{"key":"B","text":"至今思项羽"},{"key":"C","text":"不肯过江东"},{"key":"D","text":"死亦为英雄"}]}},"cnc_p280":{"desc":"学写一封信：有称呼、正文、祝福语、署名和日期。正文要把想告诉对方的事说清楚，不能只剩一个「你好」。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p279","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《夏日绝句》」，再学「语文园地八·习作：写信」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"一封信开头该怎样写？","answer":"B","explanation":"称呼在前，让收信的人知道这封信是写给谁的。","choices":[{"key":"A","text":"先写自己的名字，再写对方的名字"},{"key":"B","text":"先写对对方的称呼，再写正文"},{"key":"C","text":"只写「信」一个字"},{"key":"D","text":"先把日期写在最上面，称呼可以没有"}]}},"cnc_p281":{"desc":"背诵范成大《四时田园杂兴》（昼出耘田），分清耘田和绩麻的时间。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p251","k":1,"why":"背诵《四时田园杂兴》之前，要先会背四年级上册的古诗。"},{"id":"cnc_p280","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地八·习作：写信」，再学「古诗《四时田园杂兴》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「昼出耘田夜绩麻」的下一句是哪一句？","answer":"C","explanation":"白天耕田、夜里绩麻之后，写村里的孩子各做各的事。","choices":[{"key":"A","text":"童孙未解供耕织"},{"key":"B","text":"也傍桑阴学种瓜"},{"key":"C","text":"村庄儿女各当家"},{"key":"D","text":"村庄儿女各回家"}]}},"cnc_p282":{"desc":"背诵杨万里《宿新市徐公店》，分清追黄蝶和学种瓜不是同一首。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p281","k":1,"why":"背《宿新市徐公店》之前，要先会背《四时田园杂兴》，才不会把种瓜和追黄蝶记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「篱落疏疏一径深」的下一句是哪一句？","answer":"D","explanation":"篱笆稀疏，小路深远，树头的新叶还没有成荫。儿童急走是第三句。","choices":[{"key":"A","text":"儿童急走追黄蝶"},{"key":"B","text":"树头新绿未成荫"},{"key":"C","text":"飞入菜花无处寻"},{"key":"D","text":"树头新绿未成阴"}]}},"cnc_p283":{"desc":"背诵辛弃疾《清平乐·村居》，知道「亡赖」在词里是顽皮的意思。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p281","k":1,"why":"背诵《清平乐·村居》之前，要先会背同册的田园诗。"},{"id":"cnc_p282","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《宿新市徐公店》」，再学「词《清平乐·村居》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「最喜小儿亡赖」的下一句是哪一句？","answer":"A","explanation":"最小的孩子躺在溪边剥莲蓬。不是莲花。","choices":[{"key":"A","text":"溪头卧剥莲蓬"},{"key":"B","text":"溪头卧剥莲花"},{"key":"C","text":"大儿锄豆溪东"},{"key":"D","text":"中儿正织鸡笼"}]}},"cnc_p284":{"desc":"能说出乡下人家屋前屋后、白天晚上各有怎样的景色。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p283","k":0,"why":"按统编教材的常见教学顺序，先学「词《清平乐·村居》」，再学「阅读《乡下人家》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"屋前的瓜藤是怎样的？","answer":"B","explanation":"青、红的瓜，碧绿的藤和叶子，把屋子装饰起来。","choices":[{"key":"A","text":"全部枯萎了"},{"key":"B","text":"攀上屋檐，花和藤构成一幅图画"},{"key":"C","text":"长在河里"},{"key":"D","text":"开在皇宫的墙上"}]}},"cnc_p285":{"desc":"读懂茅盾写的天窗：下雨关窗以后，小小的天窗是孩子们的慰藉，他们能从一点雨、一粒星想象开去。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p284","k":1,"why":"读《天窗》之前，要先会读《乡下人家》，才不会把屋前的瓜藤和雨天从天窗看出去的想象记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《天窗》的作者是谁？","answer":"C","explanation":"这篇是茅盾写的。《乡下人家》是陈醉云的，《三月桃花水》是刘湛秋的。","choices":[{"key":"A","text":"陈醉云"},{"key":"B","text":"刘湛秋"},{"key":"C","text":"茅盾"},{"key":"D","text":"巴金"}]}},"cnc_p286":{"desc":"读懂刘湛秋把三月的桃花水写成春天的竖琴和明镜，表达对春水的喜爱。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p285","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《天窗》」，再学「阅读《三月桃花水》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《三月桃花水》的作者是谁？","answer":"D","explanation":"这篇散文诗是刘湛秋的。《天窗》才是茅盾的。","choices":[{"key":"A","text":"茅盾"},{"key":"B","text":"陈醉云"},{"key":"C","text":"艾青"},{"key":"D","text":"刘湛秋"}]}},"cnc_p287":{"desc":"能按偏旁分辨清、晴、情、请。声旁都是青，意思看形旁。口语交际「转述」要把听到的话说明白，不漏要点，也不把自己的话塞进去。习作「我的乐园」要写出那个地方的样子和在那里做的事。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p090","k":1,"why":"分辨清、晴、情、请之前，要先会按偏旁归类。"},{"id":"cnc_p286","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《三月桃花水》」，再学「语文园地一·形声字：清、晴、情、请」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"和水有关的是哪一个字？","answer":"A","explanation":"清是三点水，和水有关。晴是日字旁，情是竖心旁，请是言字旁。","choices":[{"key":"A","text":"清"},{"key":"B","text":"晴"},{"key":"C","text":"情"},{"key":"D","text":"请"}]}},"cnc_p288":{"desc":"读懂课文怎样根据琥珀里的蜘蛛和苍蝇，推测很久以前发生的事。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p287","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地一·形声字：清、晴、情、请」，再学「阅读《琥珀》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"琥珀里面包住了什么？","answer":"B","explanation":"蜘蛛正扑向苍蝇，松脂滴下来，把它们一起包住了。","choices":[{"key":"A","text":"一条鱼和一只鸟"},{"key":"B","text":"一只苍蝇和一只蜘蛛"},{"key":"C","text":"两块五色石"},{"key":"D","text":"一颗李子"}]}},"cnc_p289":{"desc":"读懂这篇说明文：恐龙的一支经过漫长演化变成了鸟类，证据来自化石，不是神话。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p288","k":1,"why":"读《飞向蓝天的恐龙》之前，要先会读《琥珀》这种根据实物来推测的说明文。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这篇要说明的主要意思是什么？","answer":"C","explanation":"不是每一种恐龙都会飞。是其中一支慢慢变成了鸟。","choices":[{"key":"A","text":"所有恐龙都在同一天飞上了天"},{"key":"B","text":"鸟和恐龙毫无关系"},{"key":"C","text":"恐龙的一支经过漫长演化，变成了鸟类"},{"key":"D","text":"鸟是女娲用五色石捏出来的"}]}},"cnc_p290":{"desc":"知道纳米极小，纳米技术已经用在冰箱、衣物这些日常事物上，也有还没实现的展望。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p289","k":1,"why":"读《纳米技术就在我们身边》之前，要先会读另一篇科学说明文，才不会把恐龙演化和纳米材料记成同一件事。"}],"q":{"type":"choice","difficulty":"basic","prompt":"1纳米有多长？","answer":"D","explanation":"课文说1纳米等于十亿分之一米。肉眼看不见，普通显微镜也看不清。","choices":[{"key":"A","text":"和一根筷子一样长"},{"key":"B","text":"和一条河一样长"},{"key":"C","text":"和地球的直径一样长"},{"key":"D","text":"十亿分之一米，非常非常小"}]}},"cnc_p291":{"desc":"读懂中华民族的飞天梦：从古代的万户，到东方红一号，再到杨利伟进入太空。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p290","k":1,"why":"读《千年梦圆在今朝》之前，要先会读身边的科学技术说明，才不会把飞天梦和纳米材料记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文里，古人尝试飞天的例子是哪一个？","answer":"A","explanation":"万户是课文里讲的古代尝试。杨利伟是今天的航天员，不是古人。","choices":[{"key":"A","text":"明朝的万户把火箭绑在椅子上，想飞向天空"},{"key":"B","text":"杨利伟乘坐神舟五号"},{"key":"C","text":"恐龙演化成鸟"},{"key":"D","text":"车胤用萤火虫照书"}]}},"cnc_p292":{"desc":"能按词选定假、散、便、发的读音。口语交际「说新闻」要把时间、地点和事情说清楚。习作「我的奇思妙想」要大胆想，也要让人听得懂想的是什么。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p291","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《千年梦圆在今朝》」，再学「语文园地二·多音字：假、散、便、发」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「放假」的「假」读哪一个？","answer":"B","explanation":"放假、假期读 jià。真假、假话才读 jiǎ。","choices":[{"key":"A","text":"jiǎ"},{"key":"B","text":"jià"},{"key":"C","text":"jiā"},{"key":"D","text":"xià"}]}},"cnc_p293":{"desc":"能按偏旁选出幕、慕、暮、墓。和多音字一起放在语文园地二。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p292","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·多音字：假、散、便、发」，再学「语文园地二·形近字：幕、慕、暮、墓」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「夜____降临」横线处该写哪一个？","answer":"C","explanation":"夜幕像一块布拉下来，下面是巾。羡慕是心字底。","choices":[{"key":"A","text":"慕"},{"key":"B","text":"暮"},{"key":"C","text":"幕"},{"key":"D","text":"墓"}]}},"cnc_p294":{"desc":"这次读书吧读科普书，去找「为什么」的科学解释，不是把神话当成答案。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p293","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·形近字：幕、慕、暮、墓」，再学「快乐读书吧：十万个为什么」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「十万个为什么」主要读哪一类书？","answer":"D","explanation":"书里用科学知识解释问题。空白本和口诀表不是这次要读的。","choices":[{"key":"A","text":"只抄当天的课程表"},{"key":"B","text":"一本空白笔记本"},{"key":"C","text":"只印着乘法口诀的表"},{"key":"D","text":"回答各种「为什么」的科普书"}]}},"cnc_p295":{"desc":"读冰心《繁星》三首：七一写母亲膝上的回忆，一三一写大海，一五九写心中的风雨只躲进母亲怀里。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p241","k":1,"why":"读冰心短诗《繁星》之前，要先读巴金的散文《繁星》，才不会把海上看星和母亲膝上的回忆记成同一篇。"},{"id":"cnc_p294","k":0,"why":"按统编教材的常见教学顺序，先学「快乐读书吧：十万个为什么」，再学「短诗三首·繁星」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这三首短诗都出自谁的《繁星》？","answer":"A","explanation":"《绿》是艾青的，《白桦》是叶赛宁的，《在天晴了的时候》是戴望舒的。这三首是冰心的。","choices":[{"key":"A","text":"冰心"},{"key":"B","text":"艾青"},{"key":"C","text":"戴望舒"},{"key":"D","text":"叶赛宁"}]}},"cnc_p296":{"desc":"读懂艾青把雨中的绿写得又多又亮，所有的绿挤在一起。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p295","k":0,"why":"按统编教材的常见教学顺序，先学「短诗三首·繁星」，再学「阅读《绿》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《绿》的作者是谁？","answer":"B","explanation":"这首诗是艾青写的。老舍写《猫》，不要记成同一个人。","choices":[{"key":"A","text":"老舍"},{"key":"B","text":"艾青"},{"key":"C","text":"丰子恺"},{"key":"D","text":"苏轼"}]}},"cnc_p297":{"desc":"读懂叶赛宁写窗前的白桦：仿佛涂上银霜，披着一身雪花，字里行间是喜爱。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p296","k":1,"why":"读《白桦》之前，要先读《绿》，才不会把艾青写的绿和叶赛宁写的白桦记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《白桦》的作者是谁？","answer":"C","explanation":"这首诗是叶赛宁的。《绿》才是艾青的，不要把满世界的绿安到白桦上。","choices":[{"key":"A","text":"艾青"},{"key":"B","text":"冰心"},{"key":"C","text":"叶赛宁"},{"key":"D","text":"戴望舒"}]}},"cnc_p298":{"desc":"读懂戴望舒邀人在雨后到小径走走，看不再胆怯的小白菊和抖去水珠的凤蝶。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p297","k":1,"why":"读《在天晴了的时候》之前，要先会读《白桦》，两首写景物的诗才不会串在一起。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《在天晴了的时候》的作者是谁？","answer":"D","explanation":"这首诗是戴望舒的。叶赛宁写《白桦》，冰心写《繁星》。","choices":[{"key":"A","text":"叶赛宁"},{"key":"B","text":"冰心"},{"key":"C","text":"艾青"},{"key":"D","text":"戴望舒"}]}},"cnc_p299":{"desc":"能按后面的说法选用严格、严厉、严密，不互相替换。综合性学习「轻叩诗歌大门」要去收集诗、读诗，还可以筹备朗诵。","criteria":["能理解词语在句子里的意思","能选出搭配恰当的词语"],"root":"","pre":[{"id":"cnc_p298","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《在天晴了的时候》」，再学「语文园地三·词语搭配：严格、严厉、严密」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「老师对作业要求很____。」横线处该填哪一个？","answer":"A","explanation":"要求、规定常用严格。严厉多写态度，严密多写组织或防守。","choices":[{"key":"A","text":"严格"},{"key":"B","text":"严厉"},{"key":"C","text":"严密"},{"key":"D","text":"严肃的天气"}]}},"cnc_p300":{"desc":"读懂老舍笔下的猫又古怪又可爱，满月的小猫更淘气。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p299","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地三·词语搭配：严格、严厉、严密」，再学「阅读《猫》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《猫》的作者是谁？","answer":"B","explanation":"这篇是老舍写的。丰子恺写的是《白鹅》。","choices":[{"key":"A","text":"丰子恺"},{"key":"B","text":"老舍"},{"key":"C","text":"艾青"},{"key":"D","text":"鲁迅"}]}},"cnc_p301":{"desc":"读懂老舍笔下的母鸡：开头讨厌它叫、欺软怕硬，后来因为它护小鸡而不敢再讨厌。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p300","k":1,"why":"读《母鸡》之前，要先会读老舍的《猫》，才不会把古怪可爱和先厌后敬记成同一种感情。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《母鸡》的作者是谁？","answer":"C","explanation":"《猫》也是老舍写的。《白鹅》才是丰子恺的，不要把两篇的作者记混。","choices":[{"key":"A","text":"丰子恺"},{"key":"B","text":"艾青"},{"key":"C","text":"老舍"},{"key":"D","text":"叶圣陶"}]}},"cnc_p302":{"desc":"读懂丰子恺抓住白鹅的高傲，从叫声、步态和吃相来写。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p300","k":1,"why":"读《白鹅》之前，要先会抓住《猫》里动物的特点，才不会把高傲和古怪记成同一种写法。"},{"id":"cnc_p301","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《母鸡》」，再学「阅读《白鹅》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《白鹅》的作者是谁？","answer":"D","explanation":"这篇是丰子恺写的。老舍写的是《猫》。","choices":[{"key":"A","text":"老舍"},{"key":"B","text":"叶圣陶"},{"key":"C","text":"郭沫若"},{"key":"D","text":"丰子恺"}]}},"cnc_p303":{"desc":"能分清夸奖和批评的词语，如团结和勾结、果断和武断。习作「我的动物朋友」要抓住动物的特点来写，用词的感情不要用反。","criteria":["能理解词语在句子里的意思","能选出搭配恰当的词语"],"root":"","pre":[{"id":"cnc_p255","k":1,"why":"体会词语的感情色彩之前，要先会辨析近义词。"},{"id":"cnc_p302","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《白鹅》」，再学「语文园地四·词语的感情色彩」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一个词含有夸奖的意思？","answer":"A","explanation":"团结是一起做好事。勾结、阴谋、狡猾都带有批评的意思。","choices":[{"key":"A","text":"团结"},{"key":"B","text":"勾结"},{"key":"C","text":"阴谋"},{"key":"D","text":"狡猾"}]}},"cnc_p304":{"desc":"读懂巴金在船上按时间看日出：太阳慢慢升起，有云时阳光给黑云镶上金边。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p303","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地四·词语的感情色彩」，再学「阅读《海上日出》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《海上日出》的作者是谁？","answer":"B","explanation":"这篇是巴金写的。《记金华的双龙洞》才是叶圣陶的。","choices":[{"key":"A","text":"叶圣陶"},{"key":"B","text":"巴金"},{"key":"C","text":"老舍"},{"key":"D","text":"冯骥才"}]}},"cnc_p305":{"desc":"按路上、外洞、孔隙、内洞的顺序读叶圣陶的游记，知道孔隙要仰卧乘船才能过。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p304","k":1,"why":"读《记金华的双龙洞》之前，要先会按顺序读《海上日出》，才不会把海上的日出和洞里的石钟乳记成同一处风景。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《记金华的双龙洞》的作者是谁？","answer":"C","explanation":"这篇游记是叶圣陶写的。《海上日出》是巴金的。","choices":[{"key":"A","text":"巴金"},{"key":"B","text":"老舍"},{"key":"C","text":"叶圣陶"},{"key":"D","text":"茅盾"}]}},"cnc_p306":{"desc":"按游览顺序写出看到的景物和当时的动作。例文《颐和园》写长廊、万寿山、昆明湖，《七月的天山》写雪峰、溪流和野花。两篇都是例子，不单独立成课文。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p264","k":1,"why":"写游记、把游览见闻写具体之前，要先会把看到的景物和事情写具体。"},{"id":"cnc_p305","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《记金华的双龙洞》」，再学「习作：游_____ ·把游览中的见闻写具体」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一句把游览时看到的样子写具体了？","answer":"D","explanation":"例文《颐和园》按看见的顺序写。只写「去玩了」，别人看不见那里什么样。","choices":[{"key":"A","text":"我去玩了。"},{"key":"B","text":"颐和园。"},{"key":"C","text":"那里很好。"},{"key":"D","text":"长廊一边是花木，一边是昆明湖，彩画一幅接着一幅"}]}},"cnc_p307":{"desc":"读懂《囊萤夜读》和《铁杵成针》：车胤用练囊装萤火虫照书，老婆婆把铁杵磨成针，都是在说坚持。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p272","k":1,"why":"读文言文二则之前，要先会读懂另一则短文言文。"},{"id":"cnc_p306","k":0,"why":"按统编教材的常见教学顺序，先学「习作：游_____ ·把游览中的见闻写具体」，再学「文言文二则」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"车胤家里穷，晚上用什么照着读书？","answer":"A","explanation":"家贫不常得油，夏天把萤火虫装进薄纱袋。","choices":[{"key":"A","text":"用练囊装萤火虫"},{"key":"B","text":"买来一盏油灯"},{"key":"C","text":"点着一堆木柴"},{"key":"D","text":"只在月亮最亮时才读"}]}},"cnc_p308":{"desc":"把握雨来故事的主要内容：他水性好，保护课本，和敌人周旋。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p240","k":1,"why":"把握较长叙事文的内容之前，要先会按顺序概括课文。"},{"id":"cnc_p307","k":0,"why":"按统编教材的常见教学顺序，先学「文言文二则」，再学「阅读《小英雄雨来》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"雨来最擅长什么？","answer":"B","explanation":"雨来在还乡河里长大，游泳很好。","choices":[{"key":"A","text":"爬山"},{"key":"B","text":"游泳"},{"key":"C","text":"骑马"},{"key":"D","text":"画画"}]}},"cnc_p309":{"desc":"读懂王安忆写的是妹妹的儿子：一个小男孩对食物的兴趣、自己做事的要求和面对挑战时的沉着。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p308","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《小英雄雨来》」，再学「阅读《我们家的男子汉》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《我们家的男子汉》的作者是谁？","answer":"C","explanation":"这篇是王安忆写的。《芦花鞋》是曹文轩的，《小英雄雨来》是管桦的。","choices":[{"key":"A","text":"老舍"},{"key":"B","text":"曹文轩"},{"key":"C","text":"王安忆"},{"key":"D","text":"管桦"}]}},"cnc_p310":{"desc":"读懂曹文轩写的青铜：用芦花编鞋，雪天拿到镇上去卖，最后把脚上那双也脱给了别人。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p309","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《我们家的男子汉》」，再学「阅读《芦花鞋》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《芦花鞋》的作者是谁？写的是谁？","answer":"D","explanation":"这篇选自曹文轩的《青铜葵花》。不要和雨来、那个小男孩记成同一个人。","choices":[{"key":"A","text":"王安忆。写的是妹妹的儿子"},{"key":"B","text":"管桦。写的是雨来"},{"key":"C","text":"老舍。写的是一只母鸡"},{"key":"D","text":"曹文轩。写的是青铜"}]}},"cnc_p311":{"desc":"能分清提示语在前、在后时，双引号和标点该怎样放。口语交际「朋友相处的秘诀」要说出自己怎样和朋友相处。习作「我学会了_____」要把学会的过程写清楚。","criteria":["能把句子写通顺","能按要求选用或修改句子"],"root":"","pre":[{"id":"cnc_p059","k":1,"why":"给对话加引号之前，要先认识句号、问号和感叹号。"},{"id":"cnc_p310","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《芦花鞋》」，再学「语文园地六·对话和双引号」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一句的引号用对了？","answer":"A","explanation":"提示语在前，说的话放进引号里，句号也在引号里面。","choices":[{"key":"A","text":"妈妈说：「该写作业了。」"},{"key":"B","text":"妈妈说：该写作业了。"},{"key":"C","text":"「妈妈说：该写作业了。」"},{"key":"D","text":"妈妈说：「该写作业了」。"}]}},"cnc_p312":{"desc":"背诵王昌龄《芙蓉楼送辛渐》，不要和同一位诗人的《出塞》串句。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p278","k":1,"why":"背诵送别诗之前，要先会背边塞诗里容易记错的句子。"},{"id":"cnc_p311","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地六·对话和双引号」，再学「古诗《芙蓉楼送辛渐》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「寒雨连江夜入吴」的下一句是哪一句？","answer":"B","explanation":"一夜寒雨之后，清晨送客，只见楚山孤零零的。秦时明月是《出塞》。","choices":[{"key":"A","text":"洛阳亲友如相问"},{"key":"B","text":"平明送客楚山孤"},{"key":"C","text":"一片冰心在玉壶"},{"key":"D","text":"秦时明月汉时关"}]}},"cnc_p313":{"desc":"背诵卢纶《塞下曲》（月黑雁飞高），不要和王昌龄的送别诗串句。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p312","k":1,"why":"背《塞下曲》之前，要先会背《芙蓉楼送辛渐》，才不会把冰心玉壶和大雪满弓刀记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「月黑雁飞高」的下一句是哪一句？","answer":"C","explanation":"夜色里大雁飞得高，是因为单于连夜逃走了。大雪满弓刀是第四句。","choices":[{"key":"A","text":"大雪满弓刀"},{"key":"B","text":"平明送客楚山孤"},{"key":"C","text":"单于夜遁逃"},{"key":"D","text":"只留清气满乾坤"}]}},"cnc_p314":{"desc":"背诵王冕《墨梅》，知道「不要人夸好颜色」是不图外表，只留清气。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p312","k":1,"why":"背《墨梅》之前，要先会背《芙蓉楼送辛渐》，才不会把一片冰心和只留清气记成同一首。"},{"id":"cnc_p313","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《塞下曲》」，再学「古诗《墨梅》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「我家洗砚池头树」的下一句是哪一句？","answer":"D","explanation":"洗砚池边的梅，花色浅得像淡淡的墨痕。只留清气是第四句。","choices":[{"key":"A","text":"只留清气满乾坤"},{"key":"B","text":"一片冰心在玉壶"},{"key":"C","text":"也傍桑阴学种瓜"},{"key":"D","text":"朵朵花开淡墨痕"}]}},"cnc_p315":{"desc":"读懂黄继光在上甘岭战役中用胸膛堵住敌人的枪口。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p314","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《墨梅》」，再学「阅读《黄继光》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"黄继光参加的是哪一次战役？","answer":"A","explanation":"课文写的是抗美援朝中的上甘岭。狼牙山是另一篇课文。","choices":[{"key":"A","text":"上甘岭战役"},{"key":"B","text":"狼牙山战斗"},{"key":"C","text":"赤壁之战"},{"key":"D","text":"渑池之会"}]}},"cnc_p316":{"desc":"读懂雨果写的哈尔威船长：船被撞伤后命令妇女先走，自己留在舰桥，与船同沉。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p315","k":1,"why":"读《“诺曼底号”遇难记》之前，要先会读《黄继光》，才不会把堵住枪口和与船共存亡记成同一个人。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《“诺曼底号”遇难记》的作者是谁？","answer":"B","explanation":"这篇是雨果的小说。管桦写雨来，冯骥才写挑山工。","choices":[{"key":"A","text":"管桦"},{"key":"B","text":"雨果"},{"key":"C","text":"冯骥才"},{"key":"D","text":"巴金"}]}},"cnc_p317":{"desc":"读懂冯骥才写的泰山挑山工：走折尺形的路，脚步不停，反而比游人先到。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p316","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《“诺曼底号”遇难记》」，再学「阅读《挑山工》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《挑山工》的作者是谁？","answer":"C","explanation":"这篇是冯骥才写的。叶圣陶写双龙洞，巴金写海上日出。","choices":[{"key":"A","text":"叶圣陶"},{"key":"B","text":"巴金"},{"key":"C","text":"冯骥才"},{"key":"D","text":"雨果"}]}},"cnc_p318":{"desc":"自我介绍要让没见过你的人记住你是谁、有什么特点。习作「我的自画像」要把外貌、性格或一件能看出特点的事写出来。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p317","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《挑山工》」，再学「语文园地七·自我介绍和自画像」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"自我介绍时，哪一种说清楚了？","answer":"D","explanation":"名字加上别人能记住的特点，介绍才有用。只说自己是学生，谁都一样。","choices":[{"key":"A","text":"我是一个学生。"},{"key":"B","text":"大家好。"},{"key":"C","text":"我很好，没什么好说的"},{"key":"D","text":"我叫小林，说话快，爱画画，课间常把同学画进速写本"}]}},"cnc_p319":{"desc":"读四下节选：王葆自己讲，奶奶用故事换他做事，张三、李四得到宝葫芦以后要什么有什么。他一碰到难题就盼着也有一个。三上那一节写到他得到葫芦，这一课细写的是听故事和盼望。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p175","k":1,"why":"读四下的《宝葫芦的秘密》之前，要先读过三上的节选，才不会把两处节选记成同一段。"},{"id":"cnc_p318","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地七·自我介绍和自画像」，再学「阅读《宝葫芦的秘密》（节选）」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"四下这篇节选是谁写的？谁在讲？","answer":"A","explanation":"作者是张天翼。王葆声明自己是少先队员，不是神仙。","choices":[{"key":"A","text":"张天翼写的。王葆用「我」来讲自己的事"},{"key":"B","text":"安徒生写的。小人鱼在讲"},{"key":"C","text":"王尔德写的。巨人在讲"},{"key":"D","text":"曹文轩写的。青铜在讲"}]}},"cnc_p320":{"desc":"读懂巨人砌墙赶走孩子以后园里只有冬天，孩子回来春天才来。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p319","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《宝葫芦的秘密》（节选）」，再学「阅读《巨人的花园》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"巨人出门回来，看见花园里有什么？","answer":"B","explanation":"孩子们原先喜欢到这座花园里玩。巨人看见以后很生气。","choices":[{"key":"A","text":"一片洪水"},{"key":"B","text":"孩子们在里面玩"},{"key":"C","text":"只有一只白鹅"},{"key":"D","text":"西门豹在修渠"}]}},"cnc_p321":{"desc":"读懂安徒生的小人鱼：救了王子，用声音向巫婆换了双腿，最后没有伤害王子，自己变成了泡沫。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p320","k":1,"why":"读《海的女儿》之前，要先会说出《巨人的花园》的道理，才不会把分享春天和牺牲成全记成同一个故事。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《海的女儿》的作者是谁？","answer":"C","explanation":"这篇是安徒生的童话。《巨人的花园》是王尔德的，《宝葫芦的秘密》是张天翼的。","choices":[{"key":"A","text":"王尔德"},{"key":"B","text":"张天翼"},{"key":"C","text":"安徒生"},{"key":"D","text":"雨果"}]}},"cnc_p322":{"desc":"故事新编要借用读过的人物，写出新的情节，不能把原来的道理写反，也不能一字不改地抄课文。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p320","k":1,"why":"给故事新编之前，要先读懂《巨人的花园》这样已经学过的故事，才知道人物不能写反。"},{"id":"cnc_p321","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《海的女儿》」，再学「语文园地八·故事新编」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一种是故事新编？","answer":"D","explanation":"人物还是那个巨人，情节是课文里没有的新事情。抄原文或换成不相干的事，都不是新编。","choices":[{"key":"A","text":"把《巨人的花园》从头到尾抄一遍"},{"key":"B","text":"新写一张和巨人、孩子都无关的购物清单"},{"key":"C","text":"只写题目「故事新编」四个字"},{"key":"D","text":"巨人拆掉围墙以后，又来了一个不敢进门的孩子，巨人亲自把他领进花园"}]}},"cnc_p323":{"desc":"读懂琦君回忆童年摇桂花，桂花落下来像一场雨。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p322","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地八·故事新编」，再学「阅读《桂花雨》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「桂花雨」指的是什么？","answer":"A","explanation":"花落在头发上、衣服上，作者把它叫做桂花雨。","choices":[{"key":"A","text":"摇桂花时落下的花，像下雨"},{"key":"B","text":"夏天下的一场真正的大雨"},{"key":"C","text":"桂花做成的雨伞"},{"key":"D","text":"院子里积的水"}]}},"cnc_p324":{"desc":"读懂许地山借花生说明：要做有用的人，不要只讲体面。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p323","k":1,"why":"读《落花生》之前，要先读《桂花雨》，才不会把摇桂花和种花生记成同一家的事。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《落花生》的作者是谁？","answer":"B","explanation":"这篇是许地山写的。琦君写的是《桂花雨》。","choices":[{"key":"A","text":"琦君"},{"key":"B","text":"许地山"},{"key":"C","text":"梁启超"},{"key":"D","text":"郭沫若"}]}},"cnc_p325":{"desc":"读懂冯骥才写珍珠鸟渐渐亲近人：从笼子里到书桌，最后落到肩上。信赖会创造出美好的境界。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p324","k":1,"why":"读《珍珠鸟》之前，要先读《落花生》，才不会把做人要有用和信赖出美好境界记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《珍珠鸟》的作者是谁？","answer":"C","explanation":"这篇是冯骥才写的。许地山写《落花生》，琦君写《桂花雨》。","choices":[{"key":"A","text":"许地山"},{"key":"B","text":"琦君"},{"key":"C","text":"冯骥才"},{"key":"D","text":"郭沫若"}]}},"cnc_p326":{"desc":"写一件自己心爱的东西：样子要看得见，得到它或和它有关的经过要一步一步写清楚，还要写出为什么舍不得。空说「我很喜欢」不算写清楚。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p306","k":1,"why":"写「我的心爱之物」、把得到它或使用它的经过写清楚之前，要先会把游览中的见闻和动作写具体。"},{"id":"cnc_p325","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《珍珠鸟》」，再学「习作：我的心爱之物」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"写一件心爱之物，经过部分怎样才算清楚？","answer":"D","explanation":"读者要能看见过程，而不是只看见结论。","choices":[{"key":"A","text":"只写「后来我很喜欢」"},{"key":"B","text":"只写题目"},{"key":"C","text":"把结果放在最前面后就结束"},{"key":"D","text":"写出一步一步是怎么得到的、后来又怎样用"}]}},"cnc_p327":{"desc":"读准容易读错的字，不按半边乱猜。口语交际「制定班级公约」要把约定写具体，让大家做得到，不能只写「要团结」三个字。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p137","k":1,"why":"改正易错字音之前，要先会分辨多音字。"},{"id":"cnc_p326","k":0,"why":"按统编教材的常见教学顺序，先学「习作：我的心爱之物」，再学「语文园地一·易读错的字音」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「傍晚」的「傍」读哪一个？","answer":"A","explanation":"傍晚读 bàng。旁是 páng，不能用半边代替。","choices":[{"key":"A","text":"bàng"},{"key":"B","text":"páng"},{"key":"C","text":"bāng"},{"key":"D","text":"pàng"}]}},"cnc_p328":{"desc":"读懂冀中平原的地道：能藏、能走、能打，还有迷惑洞、气孔这些机关。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p327","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地一·易读错的字音」，再学「阅读《冀中的地道战》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"地道战主要发生在哪里？","answer":"B","explanation":"冀中是河北中部。课文写的是抗日战争时期那里的地道。","choices":[{"key":"A","text":"秦国的渑池"},{"key":"B","text":"冀中平原"},{"key":"C","text":"钱塘江边"},{"key":"D","text":"圆明园里"}]}},"cnc_p329":{"desc":"能按完璧归赵、渑池之会、负荆请罪说出蔺相如和廉颇的故事。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p328","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《冀中的地道战》」，再学「阅读《将相和》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"蔺相如带着和氏璧到秦国，后来璧怎样了？","answer":"C","explanation":"他看出秦王没有诚意，让人从路上把璧送回赵国。这就是完璧归赵。","choices":[{"key":"A","text":"献给了秦王，赵国什么也没得到"},{"key":"B","text":"被廉颇扣下了"},{"key":"C","text":"被他派人送回了赵国"},{"key":"D","text":"掉进了渑池"}]}},"cnc_p330":{"desc":"读懂这篇说明文用比较来写速度：猎豹很快，可是还有游隼、飞机、火箭、流星体，最快的是光。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p329","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《将相和》」，再学「阅读《什么比猎豹的速度更快》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文拿猎豹开头，是为了说明什么？","answer":"D","explanation":"先承认猎豹快，再一层层比下去。","choices":[{"key":"A","text":"猎豹是世界上跑得最慢的动物"},{"key":"B","text":"猎豹能在地道里打仗"},{"key":"C","text":"猎豹就是光"},{"key":"D","text":"猎豹已经很快，后面还有更快的"}]}},"cnc_p331":{"desc":"读懂雨果写的哈尔威船长：船被撞伤后命令妇女先走，自己留在舰桥，与船同沉。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p329","k":1,"why":"读《“诺曼底号”遇难记》之前，要先会梳理《将相和》的情节，才不会把负荆请罪和船长留在舰桥记成同一件事。"},{"id":"cnc_p330","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《什么比猎豹的速度更快》」，再学「阅读《“诺曼底号”遇难记》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《“诺曼底号”遇难记》的作者是谁？","answer":"A","explanation":"这篇是雨果的小说。许地山写花生，冯骥才写珍珠鸟。","choices":[{"key":"A","text":"雨果"},{"key":"B","text":"许地山"},{"key":"C","text":"冯骥才"},{"key":"D","text":"梁启超"}]}},"cnc_p332":{"desc":"抓住一位老师最明显的特点来写，用一件具体的事，而不是空话。题目里的「漫画」是说特点要突出，不是真的去画一幅漫画。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p329","k":1,"why":"写「漫画」老师、抓住人物特点之前，要先会从《将相和》里看出两个人物各有各的做法。"},{"id":"cnc_p331","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《“诺曼底号”遇难记》」，再学「习作：“漫画”老师」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「漫画」老师，哪一句抓住了特点？","answer":"B","explanation":"袖口上的白印是能看见的习惯。空说「很好」，谁都一样。","choices":[{"key":"A","text":"老师很好。"},{"key":"B","text":"她讲到兴奋处，粉笔一挥，袖口上总会多一道白印"},{"key":"C","text":"漫画两个字。"},{"key":"D","text":"我们有老师。"}]}},"cnc_p333":{"desc":"能按词读准强、鲜、弹、模，不把不常用的那个音漏掉。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p327","k":1,"why":"遇到多音字的另一个读音之前，要先改掉按半边猜音的习惯。"},{"id":"cnc_p332","k":0,"why":"按统编教材的常见教学顺序，先学「习作：“漫画”老师」，再学「语文园地二·多音字：强、鲜、弹、模」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「勉强」的「强」读哪一个？","answer":"C","explanation":"勉强读 qiǎng。强大读 qiáng，倔强读 jiàng。","choices":[{"key":"A","text":"qiáng"},{"key":"B","text":"jiàng"},{"key":"C","text":"qiǎng"},{"key":"D","text":"qiāng"}]}},"cnc_p334":{"desc":"能按语境选择成语，分清意思相反或容易用反的四字词语。","criteria":["能理解词语在句子里的意思","能选出搭配恰当的词语"],"root":"","pre":[{"id":"cnc_p211","k":1,"why":"在句子里运用成语之前，要先理解寓言成语的意思。"},{"id":"cnc_p333","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·多音字：强、鲜、弹、模」，再学「语文园地二·成语运用」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"做事有始有终，可以用哪一个词语？","answer":"D","explanation":"坚持不懈是一直做下去。半途而废、三心二意都是没有做完。","choices":[{"key":"A","text":"半途而废"},{"key":"B","text":"三心二意"},{"key":"C","text":"守株待兔"},{"key":"D","text":"坚持不懈"}]}},"cnc_p335":{"desc":"读懂海力布为了让乡亲躲开灾难，说出秘密，自己变成了石头。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p334","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·成语运用」，再学「阅读《猎人海力布》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"海力布救下的小白蛇是谁？","answer":"A","explanation":"小白蛇是龙王的女儿。龙王因此要酬谢他。","choices":[{"key":"A","text":"龙王的女儿"},{"key":"B","text":"王母娘娘"},{"key":"C","text":"织女"},{"key":"D","text":"村里的孩子"}]}},"cnc_p336":{"desc":"读懂牛郎和织女被银河隔开，七月初七由喜鹊搭桥相会。《牛郎织女（一）（二）》合为一个 topic。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p335","k":1,"why":"读《牛郎织女》之前，要先读《猎人海力布》，两篇都是民间故事，才不会把变成石头和喜鹊搭桥记成同一个情节。"}],"q":{"type":"choice","difficulty":"basic","prompt":"老牛在牛郎成亲这件事里做了什么？","answer":"B","explanation":"老牛会说话，把下凡的时间和取衣的办法告诉了牛郎。","choices":[{"key":"A","text":"把织女送回天上"},{"key":"B","text":"告诉他织女要下凡，让他去取织女的纱衣"},{"key":"C","text":"划出了银河"},{"key":"D","text":"教他射箭"}]}},"cnc_p337":{"desc":"故事新编要借用读过的民间故事人物，写出新的情节，不能把原来的道理写反，也不能一字不改地抄课文。口语交际「讲民间故事」要把时间、地点和主要情节讲清楚，让人听得下去。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p336","k":1,"why":"给民间故事新编之前，要先读懂《牛郎织女》，才知道人物不能写反。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一种是故事新编？","answer":"C","explanation":"人物还是海力布，情节是课文里没有的新事情。抄原文或换成不相干的事，都不是新编。","choices":[{"key":"A","text":"把《猎人海力布》从头到尾抄一遍"},{"key":"B","text":"新写一张和海力布、牛郎都无关的购物清单"},{"key":"C","text":"海力布变成石头以后，乡亲每年回来看他，又发生了一件新事"},{"key":"D","text":"只写题目「故事新编」四个字"}]}},"cnc_p338":{"desc":"这次读书吧读中国民间故事。开头常常是「从前有座山」，里面是老百姓口头传下来的愿望和情感，不要把它们当成科学实验的记录。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p337","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地三·习作：故事新编」，再学「快乐读书吧：从前有座山」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「从前有座山」主要读哪一类书？","answer":"D","explanation":"从前有座山，是民间故事开头常用的说法。空白本和说明书不是这次要读的。","choices":[{"key":"A","text":"只抄当天的课程表"},{"key":"B","text":"一本空白笔记本"},{"key":"C","text":"只印着速度表的说明书"},{"key":"D","text":"中国民间故事，比如海力布、牛郎织女这一类"}]}},"cnc_p339":{"desc":"背诵陆游《示儿》，记住九州同、乃翁，不把字改掉。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p278","k":1,"why":"背诵《示儿》之前，要先会背四年级的七言绝句。"},{"id":"cnc_p338","k":0,"why":"按统编教材的常见教学顺序，先学「快乐读书吧：从前有座山」，再学「古诗《示儿》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「死去元知万事空」的下一句是哪一句？","answer":"A","explanation":"诗人悲伤的是没能看见国家统一。九州空、家祭都不是这一句的下一句。","choices":[{"key":"A","text":"但悲不见九州同"},{"key":"B","text":"王师北定中原日"},{"key":"C","text":"但悲不见九州空"},{"key":"D","text":"家祭无忘告乃翁"}]}},"cnc_p340":{"desc":"背诵林升《题临安邸》，分清杭州和汴州，也不要把句子装进《示儿》。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p339","k":1,"why":"背《题临安邸》之前，要先会背《示儿》，两首写南宋的诗才不会把杭州和九州同装错。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「山外青山楼外楼」的下一句是哪一句？","answer":"B","explanation":"先问西湖的歌舞什么时候才停止。暖风是第三句，九州同是《示儿》。","choices":[{"key":"A","text":"暖风熏得游人醉"},{"key":"B","text":"西湖歌舞几时休"},{"key":"C","text":"直把杭州作汴州"},{"key":"D","text":"但悲不见九州同"}]}},"cnc_p341":{"desc":"背诵龚自珍《己亥杂诗》（九州生气恃风雷），记住万马齐喑和不拘一格。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p340","k":1,"why":"背《己亥杂诗》之前，要先会背《题临安邸》，才不会把万马齐喑和西湖歌舞装进同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「九州生气恃风雷」的下一句是哪一句？","answer":"C","explanation":"没有风雷，到处都静得可怕。九州同是《示儿》，杭州是《题临安邸》。","choices":[{"key":"A","text":"我劝天公重抖擞"},{"key":"B","text":"但悲不见九州同"},{"key":"C","text":"万马齐喑究可哀"},{"key":"D","text":"直把杭州作汴州"}]}},"cnc_p342":{"desc":"读懂梁启超《少年中国说》里少年和国家的关系，不把作者记成别人。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p308","k":1,"why":"读议论性节选之前，要先会把握叙事文的主要内容。"},{"id":"cnc_p341","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《己亥杂诗》」，再学「阅读《少年中国说》节选」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「少年智则国智」的下一句是哪一句？","answer":"D","explanation":"原文按智、富、强往下说。强在富的后面。","choices":[{"key":"A","text":"少年强则国强"},{"key":"B","text":"少年独立则国独立"},{"key":"C","text":"少年自由则国自由"},{"key":"D","text":"少年富则国富"}]}},"cnc_p343":{"desc":"读懂圆明园的布局与文物，以及它被毁灭是不可估量的损失。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p342","k":1,"why":"读《圆明园的毁灭》之前，要先读《少年中国说》，才不会把少年强则国强和园林被毁记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"圆明园里有怎样的建筑？","answer":"A","explanation":"课文从皇家园林写到各地名胜的缩影，也写到西洋景观。","choices":[{"key":"A","text":"既有金碧辉煌的殿堂，也有山乡村野，还有西洋景观"},{"key":"B","text":"只有一座小小的茅屋"},{"key":"C","text":"只有西洋楼，没有中国建筑"},{"key":"D","text":"全部是后来新建的居民楼"}]}},"cnc_p344":{"desc":"读懂京剧表演艺术家梅兰芳在抗日战争时期留起胡须、拒绝为侵略者演戏，宁可卖房、装病，也不登台。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p343","k":1,"why":"读《梅兰芳蓄须明志》之前，要先读《圆明园的毁灭》，两篇都在写面对外来侵略时不能忘记的事。"}],"q":{"type":"choice","difficulty":"basic","prompt":"梅兰芳是做什么的？平时为什么不能留胡子？","answer":"B","explanation":"旦角是戏里的女角色。蓄须，等于宣布不再登台。","choices":[{"key":"A","text":"赵国的大将，胡子是盔甲的一部分"},{"key":"B","text":"京剧表演艺术家，演的是旦角，留了胡子就没法扮女子"},{"key":"C","text":"圆明园的工匠，胡子会挡住砖"},{"key":"D","text":"诺曼底号的船长，胡子能当绳子"}]}},"cnc_p345":{"desc":"能联系课文推想不可估量、众星拱月、玲珑剔透的意思。习作「二十年后的家乡」要写出变化后的具体样子，不能只写「家乡变好了」。","criteria":["能理解词语在句子里的意思","能选出搭配恰当的词语"],"root":"","pre":[{"id":"cnc_p344","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《梅兰芳蓄须明志》」，再学「语文园地四·联系上下文理解词语」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「不可估量的损失」里，「估量」是什么意思？","answer":"C","explanation":"不可估量，是大到没法估计。不是拿尺子去量。","choices":[{"key":"A","text":"把园子量一遍长度"},{"key":"B","text":"把文物藏起来"},{"key":"C","text":"估计损失有多大"},{"key":"D","text":"把火扑灭"}]}},"cnc_p346":{"desc":"读懂这篇说明文：太阳离我们很远、温度极高，和人类的关系非常密切。本单元没有语文园地。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p345","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地四·联系上下文理解词语」，再学「阅读《太阳》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文先从哪几方面介绍太阳本身？","answer":"D","explanation":"远、大、热，是太阳自身的特点。后面才写和人类的关系。","choices":[{"key":"A","text":"只写它会唱歌"},{"key":"B","text":"只写桂花的香"},{"key":"C","text":"只写船长的职责"},{"key":"D","text":"距离远、体积大、温度高"}]}},"cnc_p347":{"desc":"读懂这篇说明文介绍埃及金字塔：那是古代法老的陵墓，规模很大，建造不易。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p346","k":1,"why":"读《金字塔》之前，要先会读《太阳》这样按方面介绍事物的说明文。"}],"q":{"type":"choice","difficulty":"basic","prompt":"金字塔主要在哪个国家？是做什么用的？","answer":"A","explanation":"三角形的塔，是古埃及国王的墓。地道、西湖、和氏璧是另外几课。","choices":[{"key":"A","text":"在埃及，是古代法老的陵墓"},{"key":"B","text":"在冀中，是打仗的地道"},{"key":"C","text":"在杭州，是看西湖的楼"},{"key":"D","text":"在赵国，是存放和氏璧的库"}]}},"cnc_p348":{"desc":"介绍一种事物，要分几个方面写清楚。例文《鲸》从大小、种类、吃食和生活习性来写；《风向袋的制作》按步骤写出材料和做法。两篇都是例子，不单独立成课文。本单元没有语文园地。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p347","k":1,"why":"介绍一种事物之前，要先会看出《金字塔》是从哪几方面写的。"}],"q":{"type":"choice","difficulty":"basic","prompt":"介绍鲸，哪一句写出了它不是鱼？","answer":"B","explanation":"例文《鲸》会写呼吸和类别。只说很大，特点还没立住。","choices":[{"key":"A","text":"鲸很大。"},{"key":"B","text":"鲸用肺呼吸，是哺乳动物，不是用鳃的鱼"},{"key":"C","text":"海里有鲸。"},{"key":"D","text":"介绍一种事物。"}]}},"cnc_p349":{"desc":"读懂梁晓声写母亲在噪声很大的车间里干活，仍给「我」钱去买书。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p348","k":0,"why":"按统编教材的常见教学顺序，先学「习作：介绍一种事物」，再学「阅读《慈母情深》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《慈母情深》的作者是谁？","answer":"C","explanation":"这篇是梁晓声的回忆。吴冠中写《父爱之舟》，冰心写《忆读书》。","choices":[{"key":"A","text":"吴冠中"},{"key":"B","text":"冰心"},{"key":"C","text":"梁晓声"},{"key":"D","text":"刘洋"}]}},"cnc_p350":{"desc":"读懂吴冠中用姑爹的小渔船，写出父亲为求学付出的那些钱和夜路。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p349","k":1,"why":"读《父爱之舟》之前，要先读《慈母情深》，才不会把母亲买书和父亲送考记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《父爱之舟》的作者是谁？","answer":"D","explanation":"这篇是吴冠中的回忆。梁晓声写《慈母情深》。","choices":[{"key":"A","text":"梁晓声"},{"key":"B","text":"刘洋"},{"key":"C","text":"老舍"},{"key":"D","text":"吴冠中"}]}},"cnc_p351":{"desc":"读懂航天员刘洋在神舟十四号出征前写给孩子的信：既是妈妈，也是军人；孩子是铠甲，也是软肋。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p350","k":1,"why":"读《航天员写给孩子的信》之前，要先会读《父爱之舟》，两篇都在写父母为孩子付出。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这封信是谁写给谁的？","answer":"A","explanation":"出征神舟十四号之前，她在酒泉给孩子写信。","choices":[{"key":"A","text":"航天员刘洋写给自己的孩子"},{"key":"B","text":"哈尔威写给乘客"},{"key":"C","text":"梁启超写给少年"},{"key":"D","text":"梅兰芳写给戏园子"}]}},"cnc_p352":{"desc":"给父母或其他长辈写一段话，把想说的事和当时的心情写具体。可以感谢、可以道歉，也可以讲一件一直没说出口的事，不能只写「谢谢您」。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p351","k":1,"why":"写「我想对您说」之前，要先读过《航天员写给孩子的信》，才知道信里要把牵挂说具体。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一段更像「我想对您说」？","answer":"B","explanation":"要有事，也要有当时的感觉。只写谢谢或只写题目，对方还是不知道你想说什么。","choices":[{"key":"A","text":"谢谢您。"},{"key":"B","text":"妈，那次您在车间把钱塞给我，我到现在还记得纸币边是热的"},{"key":"C","text":"我想对您说。"},{"key":"D","text":"父母之爱。"}]}},"cnc_p353":{"desc":"能按意思选用戴、载、裁，不看半边就写错。口语交际「父母之爱」要结合本单元的课文，说出自己体会到的爱，不要只重复「父母很爱我」。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p352","k":0,"why":"按统编教材的常见教学顺序，先学「习作：我想对您说」，再学「语文园地六·形近字：戴、载、裁」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「____帽子」横线处该写哪一个？","answer":"C","explanation":"戴帽子是加在头上。装载、记载用载，裁剪用裁。","choices":[{"key":"A","text":"载"},{"key":"B","text":"裁"},{"key":"C","text":"戴"},{"key":"D","text":"栽"}]}},"cnc_p354":{"desc":"背诵王维《山居秋暝》，记住空山、清泉和浣女，不和夜泊的句子串起来。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p341","k":1,"why":"背《山居秋暝》之前，要先会背本册第四单元的古诗，才不会把不拘一格和空山新雨记成同一首。"},{"id":"cnc_p353","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地六·形近字：戴、载、裁」，再学「古诗《山居秋暝》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「空山新雨后」的下一句是哪一句？","answer":"D","explanation":"空山刚下过雨，天气已是秋天的傍晚。松间照是第三句。客船是《枫桥夜泊》。","choices":[{"key":"A","text":"明月松间照"},{"key":"B","text":"清泉石上流"},{"key":"C","text":"夜半钟声到客船"},{"key":"D","text":"天气晚来秋"}]}},"cnc_p355":{"desc":"背诵张继《枫桥夜泊》，记住渔火、夜半和客船，不把字改掉。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p354","k":1,"why":"背《枫桥夜泊》之前，要先会背同课的《山居秋暝》，才不会把清泉石上和江枫渔火装进同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「月落乌啼霜满天」的下一句是哪一句？","answer":"A","explanation":"对着愁眠的是渔火。鱼火是错字。寒山寺是第三句。","choices":[{"key":"A","text":"江枫渔火对愁眠"},{"key":"B","text":"姑苏城外寒山寺"},{"key":"C","text":"江枫鱼火对愁眠"},{"key":"D","text":"月落乌啼霜满地"}]}},"cnc_p356":{"desc":"背诵韩愈这首写早春的诗，记住润如酥、近却无，不和秋暝、夜泊串句。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p355","k":1,"why":"背《早春呈水部张十八员外》之前，要先会背同课的《枫桥夜泊》，才不会把夜半钟声和草色遥看记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「天街小雨润如酥」的下一句是哪一句？","answer":"B","explanation":"远看有一层绿，走近却好像没有。空山新雨是《山居秋暝》。","choices":[{"key":"A","text":"最是一年春好处"},{"key":"B","text":"草色遥看近却无"},{"key":"C","text":"草色遥看近还无"},{"key":"D","text":"空山新雨后"}]}},"cnc_p357":{"desc":"读懂峻青写胶东的一场大雪：下雪时是动态，雪后是静态，这场雪对麦子有好处。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p356","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《早春呈水部张十八员外》」，再学「阅读《第一场雪》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《第一场雪》的作者是谁？写的是哪里的雪？","answer":"C","explanation":"这篇是峻青的散文。白鹭、秋暝、夜泊是另外几课。","choices":[{"key":"A","text":"郭沫若。写的是一只白鹭"},{"key":"B","text":"王维。写的是山中的秋雨"},{"key":"C","text":"峻青。写的是胶东一带"},{"key":"D","text":"张继。写的是枫桥的夜"}]}},"cnc_p358":{"desc":"读懂郭沫若笔下的白鹭色素、身段都恰好，本身就像一首诗。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p357","k":1,"why":"读《白鹭》之前，要先会读《第一场雪》，才不会把一场大雪和一只白鹭记成同一篇写景。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《白鹭》的作者是谁？","answer":"D","explanation":"这篇是郭沫若写的。《第一场雪》是峻青的，《落花生》是许地山的。","choices":[{"key":"A","text":"峻青"},{"key":"B","text":"许地山"},{"key":"C","text":"王维"},{"key":"D","text":"郭沫若"}]}},"cnc_p359":{"desc":"能找出搭配不当和前后重复的毛病，并选出改对的句子。习作「我最喜爱的季节」要把这个季节的景物和自己的感受写具体，不能只写「我喜欢春天」。","criteria":["能把句子写通顺","能按要求选用或修改句子"],"root":"","pre":[{"id":"cnc_p273","k":1,"why":"修改搭配不当和重复啰嗦之前，要先会使用关联词。"},{"id":"cnc_p358","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《白鹭》」，再学「语文园地七·修改病句」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一句没有毛病？","answer":"A","explanation":"大概和左右重复，书包不能戴，忍不住和不禁也重复。","choices":[{"key":"A","text":"小鸟在树上唱歌。"},{"key":"B","text":"我大概用了半小时左右。"},{"key":"C","text":"他戴上了帽子和书包。"},{"key":"D","text":"我忍不住不禁笑了起来。"}]}},"cnc_p360":{"desc":"读懂三则短文：论语里的敏而好学，朱熹的心到、眼到、口到，曾国藩的有志、有识、有恒。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p359","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地七·修改病句」，再学「阅读《古人谈读书》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「敏而好学，不耻下问」出自哪一部书？是什么意思？","answer":"B","explanation":"这是第一则，选自《论语》。下问是向不如自己的人问。","choices":[{"key":"A","text":"朱熹的读书三到。只准问老师"},{"key":"B","text":"《论语》。聪明好学，不以向不如自己的人请教为耻"},{"key":"C","text":"曾国藩家书。有志就可以不问"},{"key":"D","text":"《示儿》。只准问儿子"}]}},"cnc_p361":{"desc":"读懂冰心回忆自己从小读书：读书好，多读书，读好书。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p360","k":1,"why":"读冰心《忆读书》之前，要先会读《古人谈读书》，才不会把三到、有志和自己七岁读《三国》记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《忆读书》的作者是谁？","answer":"C","explanation":"这篇是冰心写自己读书的经历。朱熹、曾国藩出现在《古人谈读书》里。","choices":[{"key":"A","text":"朱熹"},{"key":"B","text":"曾国藩"},{"key":"C","text":"冰心"},{"key":"D","text":"尤安·艾肯"}]}},"cnc_p362":{"desc":"读懂尤安·艾肯：如果只能带一样东西去荒岛，她要带书；一本书可以反复读，像一位不会厌烦的朋友。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p361","k":1,"why":"读《走遍天下书为侣》之前，要先会读《忆读书》，才不会把冰心的书单和荒岛上只带一本书记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《走遍天下书为侣》的作者是谁？","answer":"D","explanation":"这篇是尤安·艾肯写的。冰心写《忆读书》。","choices":[{"key":"A","text":"冰心"},{"key":"B","text":"朱熹"},{"key":"C","text":"梁晓声"},{"key":"D","text":"尤安·艾肯"}]}},"cnc_p363":{"desc":"推荐一本书，要写出书名、大概写了什么、哪一处最打动你、为什么值得读。不能只写「这本书很好」。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p362","k":1,"why":"推荐一本书之前，要先会说出《走遍天下书为侣》里书为什么能当伴侣。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一段更像在推荐一本书？","answer":"A","explanation":"要有书名，也要有内容或理由。只说很好，别人还是不知道推荐的是哪本、为什么。","choices":[{"key":"A","text":"《忆读书》写冰心从小读书的经历，读了会想自己也去找一本真正喜欢的书"},{"key":"B","text":"这本书很好。"},{"key":"C","text":"推荐一本书。"},{"key":"D","text":"书。"}]}},"cnc_p364":{"desc":"再背范成大《四时田园杂兴》（其三十一），认准昼出耘田、夜绩麻、学种瓜，不和《稚子弄冰》《村晚》串句。四下已经背过这一首。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p281","k":1,"why":"再背《四时田园杂兴》（其三十一）之前，要先会背四下学过的这一首，分清昼出耘田和夜绩麻。"},{"id":"cnc_p363","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地八·习作：推荐一本书」，再学「古诗《四时田园杂兴》（其三十一）」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"五下《古诗三首》里，哪一首是范成大的《四时田园杂兴》（其三十一）？","answer":"B","explanation":"其三十一从「昼出耘田」写起。脱晓冰是《稚子弄冰》，池塘是《村晚》，篱落是《宿新市徐公店》。","choices":[{"key":"A","text":"稚子金盆脱晓冰"},{"key":"B","text":"昼出耘田夜绩麻"},{"key":"C","text":"草满池塘水满陂"},{"key":"D","text":"篱落疏疏一径深"}]}},"cnc_p365":{"desc":"背诵杨万里《稚子弄冰》，记住银钲、玻璃，不写成银钟、琉璃，也不和昼出耘田、村晚串句。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p364","k":1,"why":"背《稚子弄冰》之前，要先分清《四时田园杂兴》（其三十一），才不会把学种瓜和银钲记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「稚子金盆脱晓冰」的下一句是哪一句？","answer":"C","explanation":"孩子把冰穿起来当银钲敲。银钟不是这句诗。","choices":[{"key":"A","text":"敲成玉磬穿林响"},{"key":"B","text":"彩丝穿取当银钟"},{"key":"C","text":"彩丝穿取当银钲"},{"key":"D","text":"忽作玻璃碎地声"}]}},"cnc_p366":{"desc":"背诵雷震《村晚》，记住横牛背、信口吹，不和弄冰、耘田的句子串起来。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p365","k":1,"why":"背《村晚》之前，要先会背《稚子弄冰》，才不会把银钲和短笛记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「草满池塘水满陂」的下一句是哪一句？","answer":"D","explanation":"落日沉在寒波里，像被山衔住。牧童是第三句。诗中是寒漪。","choices":[{"key":"A","text":"牧童归去横牛背"},{"key":"B","text":"短笛无腔信口吹"},{"key":"C","text":"山衔落日浸寒波"},{"key":"D","text":"山衔落日浸寒漪"}]}},"cnc_p367":{"desc":"读懂萧红笔下的园子里，倭瓜、蝴蝶和「我」都是自由的。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p366","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《村晚》」，再学「阅读《祖父的园子》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《祖父的园子》选自哪本书？","answer":"A","explanation":"这篇是萧红《呼兰河传》里的章节。不是古典小说。","choices":[{"key":"A","text":"《呼兰河传》"},{"key":"B","text":"《三国演义》"},{"key":"C","text":"《水浒传》"},{"key":"D","text":"《朝花夕拾》"}]}},"cnc_p368":{"desc":"读懂季羡林借月亮写思乡：别处的月亮再大，也不如故乡那轮小月亮亲。题目出自杜甫的诗句。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p367","k":1,"why":"读《月是故乡明》之前，要先读《祖父的园子》，两篇都写童年和故乡，才不会把园子和月亮记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《月是故乡明》的作者是谁？","answer":"B","explanation":"这篇散文是季羡林写的。杜甫写过「月是故乡明」这句诗，但不是这篇课文的作者。","choices":[{"key":"A","text":"萧红"},{"key":"B","text":"季羡林"},{"key":"C","text":"陈慧瑛"},{"key":"D","text":"杜甫"}]}},"cnc_p369":{"desc":"读懂陈慧瑛写外祖父：人在海外，心向祖国，把梅花看成中华民族的气节。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p368","k":1,"why":"读《梅花魂》之前，要先读《月是故乡明》，才不会把思乡的月亮和外祖父的梅花记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《梅花魂》的作者是谁？","answer":"C","explanation":"这篇是陈慧瑛写外祖父的。季羡林写月亮，萧红写园子。","choices":[{"key":"A","text":"季羡林"},{"key":"B","text":"萧红"},{"key":"C","text":"陈慧瑛"},{"key":"D","text":"冯骥才"}]}},"cnc_p370":{"desc":"写一个自己突然觉得长大了的时刻：当时在哪里、谁做了什么、自己心里怎样变的，都要看得见。口语交际「走进他们的童年岁月」要向长辈问具体的事，听的时候不要打断。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p369","k":1,"why":"写「那一刻，我长大了」之前，要先读过一篇回忆童年的课文，才知道那一刻的场景要写具体。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一段更像「那一刻，我长大了」？","answer":"D","explanation":"要有那一刻的事，也要有心里的变化。只说长大了，读者看不见。","choices":[{"key":"A","text":"我长大了。"},{"key":"B","text":"那一刻三个字。"},{"key":"C","text":"童年很美好。"},{"key":"D","text":"奶奶发烧那天，我自己烧好粥端过去。她喝了一口，我才觉得自己不再只是被照顾的人。"}]}},"cnc_p371":{"desc":"读准削、骨、血、处在不同词里的读音，不按半边乱猜。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p370","k":0,"why":"按统编教材的常见教学顺序，先学「习作：那一刻，我长大了」，再学「语文园地一·易错字音（削、骨、血、处）」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「削铅笔」的「削」读哪一个？","answer":"A","explanation":"削苹果、削铅笔读 xiāo。剥削才读 xuē。","choices":[{"key":"A","text":"xiāo"},{"key":"B","text":"xuē"},{"key":"C","text":"xiào"},{"key":"D","text":"qiāo"}]}},"cnc_p372":{"desc":"读懂诸葛亮向周瑜立下军令状，用草船向曹操借箭。故事出自《三国演义》。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p329","k":1,"why":"读古典名著节选之前，要先会梳理《将相和》这类历史故事的情节。"},{"id":"cnc_p371","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地一·易错字音（削、骨、血、处）」，再学「阅读《草船借箭》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"诸葛亮向谁立下了军令状？","answer":"B","explanation":"周瑜用造箭的事为难他，他向周瑜立下军令状。","choices":[{"key":"A","text":"曹操"},{"key":"B","text":"周瑜"},{"key":"C","text":"鲁肃"},{"key":"D","text":"刘备"}]}},"cnc_p373":{"desc":"读懂武松不听「三碗不过冈」的劝告，仍然过冈，并打死老虎。故事出自《水浒传》。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p372","k":1,"why":"读《景阳冈》之前，要先会梳理名著故事的情节。"}],"q":{"type":"choice","difficulty":"basic","prompt":"店家在招旗上提醒什么？","answer":"C","explanation":"店家说三碗以后就不能再过冈，因为冈上有虎。","choices":[{"key":"A","text":"冈上没有老虎"},{"key":"B","text":"喝酒不要给钱"},{"key":"C","text":"三碗不过冈"},{"key":"D","text":"景阳冈已经封路"}]}},"cnc_p374":{"desc":"读懂石猴从仙石中迸出，跳进瀑布，发现水帘洞。故事出自《西游记》。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p372","k":1,"why":"读《猴王出世》之前，要先会抓住名著节选里的主要事件。"},{"id":"cnc_p373","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《景阳冈》」，再学「阅读《猴王出世》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"石猴是从哪里出来的？","answer":"D","explanation":"仙石迸裂，产下一个石卵，化作石猴。","choices":[{"key":"A","text":"一只桃子"},{"key":"B","text":"海边的贝壳"},{"key":"C","text":"仙人用手捏出来"},{"key":"D","text":"一块仙石迸裂"}]}},"cnc_p375":{"desc":"读懂《红楼梦》里这次放风筝：宝玉、黛玉等人在园中把风筝放上天，和借箭、打虎、石猴出世不是同一个故事。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p374","k":1,"why":"读《红楼春趣》之前，要先会读《猴王出世》，才不会把放风筝和石猴跳瀑布记成同一篇。"},{"id":"cnc_p373","k":1,"why":"读《红楼春趣》之前，要先会读《景阳冈》，才不会把大观园和打虎记成同一个故事。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《红楼春趣》选自哪部书？","answer":"A","explanation":"放风筝这一回出自《红楼梦》。草船在《三国演义》，打虎在《水浒传》，石猴在《西游记》。","choices":[{"key":"A","text":"《红楼梦》"},{"key":"B","text":"《三国演义》"},{"key":"C","text":"《水浒传》"},{"key":"D","text":"《西游记》"}]}},"cnc_p376":{"desc":"写读后感：先说出读的是哪一篇，再用几句点出情节，重点写自己的感受。不能把课文从头抄到尾。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p375","k":1,"why":"写读后感之前，要先读过一篇古典名著节选，才知道感受要从读过的情节里来。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一段更像读后感？","answer":"B","explanation":"要有篇名，也要有自己的想法。只说很好，别人不知道好在哪里。","choices":[{"key":"A","text":"草船借箭四个字。"},{"key":"B","text":"读了《草船借箭》，我记住诸葛亮把大雾和船都算进去了。自己做事也要先把困难想清楚。"},{"key":"C","text":"这本书很好。"},{"key":"D","text":"周瑜。"}]}},"cnc_p377":{"desc":"能把神机妙算、完好无缺用在合适的句子里。口语交际「怎么表演课本剧」并入本园地：先分清人物，再把主要情节演出来，不能只站着把课文读一遍。","criteria":["能理解词语在句子里的意思","能选出搭配恰当的词语"],"root":"","pre":[{"id":"cnc_p376","k":0,"why":"按统编教材的常见教学顺序，先学「习作：写读后感」，再学「语文园地二·成语（神机妙算、完好无缺等）」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"诸葛亮算出大雾、借到箭，可以用哪一个成语？","answer":"C","explanation":"神机妙算是计谋高明、算得准。完好无缺是没有损坏。","choices":[{"key":"A","text":"完好无缺"},{"key":"B","text":"半途而废"},{"key":"C","text":"神机妙算"},{"key":"D","text":"守株待兔"}]}},"cnc_p378":{"desc":"这次读书吧读中国古典名著。课文里的草船借箭、景阳冈、猴王出世、红楼春趣，分别来自《三国演义》《水浒传》《西游记》《红楼梦》。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p376","k":1,"why":"读整本古典名著之前，要先会把一篇节选的读后想法说清楚。"},{"id":"cnc_p377","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·成语（神机妙算、完好无缺等）」，再学「快乐读书吧：读古典名著，品百味人生」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「读古典名著，品百味人生」主要读哪一类书？","answer":"D","explanation":"四部都是长篇小说。课程表、说明书和一首绝句不是这次要读的。","choices":[{"key":"A","text":"只抄当天的课程表"},{"key":"B","text":"只介绍金字塔有多高的说明书"},{"key":"C","text":"只背《稚子弄冰》"},{"key":"D","text":"《三国演义》《水浒传》《西游记》《红楼梦》这一类中国古典名著"}]}},"cnc_p379":{"desc":"能根据偏旁推想字义和字的类别。这是「遨游汉字王国」里「汉字真有趣」要练的方法。本单元没有语文园地。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p162","k":1,"why":"根据偏旁推想字义之前，要先会用部首查字。"},{"id":"cnc_p378","k":0,"why":"按统编教材的常见教学顺序，先学「快乐读书吧：读古典名著，品百味人生」，再学「综合性学习·汉字真有趣」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「江、河、湖、海」都有三点水，说明它们多和什么有关？","answer":"A","explanation":"三点水的字大多和水有关。","choices":[{"key":"A","text":"水"},{"key":"B","text":"树木"},{"key":"C","text":"金属"},{"key":"D","text":"言语"}]}},"cnc_p380":{"desc":"能分清象形是照样子造字，会意是把几个意思合起来。这是「我爱你，汉字」里要分辨的两种造字法。本单元没有语文园地。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p379","k":1,"why":"区分象形和会意之前，要先会看偏旁表示的意思。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「日」「月」这一类字主要是什么造字法？","answer":"B","explanation":"日、月的古文字就像太阳和月亮的样子，是象形。","choices":[{"key":"A","text":"会意"},{"key":"B","text":"象形"},{"key":"C","text":"只是随便画的圆圈，不是汉字"},{"key":"D","text":"反义词"}]}},"cnc_p381":{"desc":"背诵王昌龄《从军行》（青海长云），不和《出塞》串句，也不和同课另外两首装错。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p278","k":1,"why":"背王昌龄《从军行》之前，要先会背他的《出塞》，两首边塞诗才不会串句。"},{"id":"cnc_p380","k":0,"why":"按统编教材的常见教学顺序，先学「综合性学习·我爱你，汉字」，再学「古诗《从军行》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「青海长云暗雪山」的下一句是哪一句？","answer":"C","explanation":"雪山被长云遮暗，前面是遥望玉门关的孤城。秦时明月是《出塞》。","choices":[{"key":"A","text":"黄沙百战穿金甲"},{"key":"B","text":"不破楼兰终不还"},{"key":"C","text":"孤城遥望玉门关"},{"key":"D","text":"秦时明月汉时关"}]}},"cnc_p382":{"desc":"背诵陆游这首诗，记住三万里河是黄河、五千仞岳是华山，遗民还在南望王师。不要和《示儿》《从军行》串句。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p381","k":1,"why":"背《秋夜将晓出篱门迎凉有感》之前，要先会背同课的《从军行》，才不会把楼兰和遗民泪尽记成同一首。"},{"id":"cnc_p339","k":1,"why":"背陆游《秋夜将晓出篱门迎凉有感》之前，要先会背他的《示儿》，才不会把南望王师和王师北定中原日记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「三万里河东入海」的下一句是哪一句？","answer":"D","explanation":"河是黄河，岳是华山，高得直上青天。遗民是第三句。摩云不是这句。","choices":[{"key":"A","text":"遗民泪尽胡尘里"},{"key":"B","text":"五千仞岳上摩云"},{"key":"C","text":"南望王师又一年"},{"key":"D","text":"五千仞岳上摩天"}]}},"cnc_p383":{"desc":"背诵杜甫这首诗：听到收复蓟北，喜极而泣，想立刻还乡。妻子在这里指妻和子女。不要和陆游那首盼王师的诗记混。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p382","k":1,"why":"背《闻官军收河南河北》之前，要先分清《秋夜将晓出篱门迎凉有感》，一首是喜极而泣，一首是遗民还在盼。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「剑外忽传收蓟北」的下一句是哪一句？","answer":"A","explanation":"刚听到消息就流泪，泪湿了衣裳。喜欲狂是第四句。南望王师是陆游的诗。","choices":[{"key":"A","text":"初闻涕泪满衣裳"},{"key":"B","text":"漫卷诗书喜欲狂"},{"key":"C","text":"初闻涕泪满衣襟"},{"key":"D","text":"南望王师又一年"}]}},"cnc_p384":{"desc":"读懂毛岸英在朝鲜牺牲后，毛主席既悲痛，仍决定把儿子安葬在朝鲜。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p383","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《闻官军收河南河北》」，再学「阅读《青山处处埋忠骨》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文里牺牲在朝鲜的是谁？","answer":"B","explanation":"毛主席收到的是儿子毛岸英牺牲的消息。刘伯承是《军神》里做手术的人。","choices":[{"key":"A","text":"刘伯承"},{"key":"B","text":"毛岸英"},{"key":"C","text":"方志敏"},{"key":"D","text":"武松"}]}},"cnc_p385":{"desc":"读懂刘伯承拒绝麻药，沃克医生称他为军神。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p384","k":1,"why":"读《军神》之前，要先读《青山处处埋忠骨》，才不会把刘伯承拒绝麻药和毛岸英安葬在朝鲜记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"接受手术的军人是谁？","answer":"C","explanation":"右眼受伤、不肯用麻药的是刘伯承。黄继光是堵枪口的英雄，不是这篇的主人公。","choices":[{"key":"A","text":"黄继光"},{"key":"B","text":"廉颇"},{"key":"C","text":"刘伯承"},{"key":"D","text":"武松"}]}},"cnc_p386":{"desc":"读懂方志敏被俘后，敌人想搜出钱财，他身上却没有积下的财物。清贫是革命者的廉洁。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p385","k":1,"why":"读《清贫》之前，要先读《军神》，两篇都写革命者，才不会把手术和搜身记成同一件事。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《清贫》的作者是谁？","answer":"D","explanation":"这篇是方志敏写自己被俘以后的事。刘伯承在《军神》里。","choices":[{"key":"A","text":"刘伯承"},{"key":"B","text":"季羡林"},{"key":"C","text":"冯骥才"},{"key":"D","text":"方志敏"}]}},"cnc_p387":{"desc":"把题目补完整，如他笑了、他愣住了、他明白了。用前后的动作和语言写出这个变化，不能只把题目抄一遍。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p386","k":1,"why":"写「他____了」之前，要先会从课文里看出人物心情发生了什么变化。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「他____了」哪一种补法能写成一篇习作？","answer":"A","explanation":"横线上要补出人的变化。天气和课本不是这个「他」。","choices":[{"key":"A","text":"他犹豫了"},{"key":"B","text":"他了"},{"key":"C","text":"天气了"},{"key":"D","text":"课本了"}]}},"cnc_p388":{"desc":"能选用表现神态、动作的词语，不把夸奖和批评用反。这些词后面写人时用得上。第五单元没有语文园地，描写人物的词语收在这里。","criteria":["能理解词语在句子里的意思","能选出搭配恰当的词语"],"root":"","pre":[{"id":"cnc_p387","k":0,"why":"按统编教材的常见教学顺序，先学「习作：他____了」，再学「语文园地四·描写人物的词语」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"写人做事果断、让人佩服，该用哪一个？","answer":"B","explanation":"斩钉截铁是说话、做事不拖泥带水。犹豫不决正好相反。","choices":[{"key":"A","text":"犹豫不决"},{"key":"B","text":"斩钉截铁"},{"key":"C","text":"东张西望"},{"key":"D","text":"漫不经心"}]}},"cnc_p389":{"desc":"读懂三则写人：《摔跤》里小嘎子和胖墩儿，《他像一棵挺脱的树》里的祥子，《两茎灯草》里的严监生。三则合成一个点。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p388","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地四·描写人物的词语」，再学「阅读《人物描写一组》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《摔跤》里和胖墩儿比赛的是谁？结果怎样？","answer":"C","explanation":"小嘎子选自《小兵张嘎》。围着转、用腿勾，反而被胖墩儿摔倒。","choices":[{"key":"A","text":"武松。他把老虎摔倒了"},{"key":"B","text":"祥子。他把车摔倒了"},{"key":"C","text":"小嘎子。他围着对方转，想占便宜，结果被摔倒了"},{"key":"D","text":"严监生。他赢了两根灯草"}]}},"cnc_p390":{"desc":"读懂冯骥才笔下的刷子李：黑衣服上要是有一个白点，工钱就不要。徒弟曹小三看见的白点，其实是烟火烧的小洞。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p389","k":1,"why":"读《刷子李》之前，要先会读《人物描写一组》，才不会把黑衣白点和两茎灯草记成同一种细节。"}],"q":{"type":"choice","difficulty":"basic","prompt":"刷子李干活时有什么规矩？","answer":"D","explanation":"白点是他不许出现的差错。这篇是冯骥才写的。","choices":[{"key":"A","text":"衣服上必须沾满白点才算刷完"},{"key":"B","text":"他只在夜里刷墙"},{"key":"C","text":"他刷墙以前要先去打虎"},{"key":"D","text":"黑衣服上要是有一个白点，工钱就不要了"}]}},"cnc_p391":{"desc":"写一个人最明显的特点，用一件看得见的事来表现，不要只说「他很好」。例文《我的朋友容容》《小守门员和他的观众们》只学写法，不单建课文点。本单元没有语文园地。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p326","k":1,"why":"写人抓住特点之前，要先会把一件心爱之物和相关事情的经过写清楚。"},{"id":"cnc_p332","k":1,"why":"写人抓住特点之前，要先会像写「漫画」老师那样用一件具体的事把特点写出来。"},{"id":"cnc_p390","k":1,"why":"把一个人的特点写具体之前，要先会看出《刷子李》是怎样用一件事把技艺写出来的。"},{"id":"cnc_p388","k":1,"why":"写人之前，要先会选用表现神态和动作的词语。"}],"q":{"type":"choice","difficulty":"basic","prompt":"写「粉刷很在行的人」，哪一句抓住了特点？","answer":"A","explanation":"又平又亮、黑衣无白点，能看出手艺。空说好人，谁都一样。","choices":[{"key":"A","text":"他一刷下去，墙面又平又亮，黑衣服上却找不出一个白点。"},{"key":"B","text":"他是一个好人。"},{"key":"C","text":"师傅两个字很好写。"},{"key":"D","text":"墙上有墙。"}]}},"cnc_p392":{"desc":"读懂卖矛和盾的人为什么答不上来。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p307","k":1,"why":"读《自相矛盾》之前，要先会读懂浅易文言文的大意。"},{"id":"cnc_p391","k":0,"why":"按统编教材的常见教学顺序，先学「习作：把一个人的特点写具体」，再学「文言文《自相矛盾》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"那个人先怎样夸自己的盾？","answer":"B","explanation":"吾盾之坚，物莫能陷也。","choices":[{"key":"A","text":"它能刺破任何东西"},{"key":"B","text":"没有什么能刺破它"},{"key":"C","text":"它和矛一样锋利"},{"key":"D","text":"它是别人送的"}]}},"cnc_p393":{"desc":"读懂孙膑调换马的出场顺序，让田忌两胜一负。这是文言文，和四年级学过的同一件事不要当成两件。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p392","k":1,"why":"读《田忌赛马》之前，要先会读《自相矛盾》，两则文言文才不会把矛盾和赛马记成同一则。"},{"id":"cnc_p247","k":1,"why":"读文言文《田忌赛马》之前，要先读过四年级的《田忌赛马》，才知道这是同一件事的文言写法。"}],"q":{"type":"choice","difficulty":"basic","prompt":"给田忌出主意的人是谁？","answer":"C","explanation":"孙膑看出马的脚力差得不多，出场顺序可以改。不要和孙武记成同一个人。","choices":[{"key":"A","text":"孙武"},{"key":"B","text":"蔺相如"},{"key":"C","text":"孙膑"},{"key":"D","text":"诸葛亮"}]}},"cnc_p394":{"desc":"读懂孩子爬上桅杆以后，船长为什么用枪逼他跳水。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p373","k":1,"why":"读《跳水》并推断人物做法之前，要先会梳理故事情节。"},{"id":"cnc_p393","k":0,"why":"按统编教材的常见教学顺序，先学「文言文《田忌赛马》」，再学「阅读《跳水》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"孩子是怎样到桅杆顶端的？","answer":"D","explanation":"猴子把他的帽子挂到桅杆高处，他追了上去。故事是托尔斯泰写的。","choices":[{"key":"A","text":"船长把他抱上去的"},{"key":"B","text":"他从海里爬上桅杆"},{"key":"C","text":"水手用绳子拉他上去"},{"key":"D","text":"追猴子，一步步爬上去的"}]}},"cnc_p395":{"desc":"写一次想象中的探险：走到了哪里、遇到什么困难、谁怎样解决，都要一步一步写清楚。可以虚构，但不能只有「然后我们赢了」。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p394","k":1,"why":"写探险之前，要先会读《跳水》，才知道危险来时要把人物的做法写清楚。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一段更像在写探险？","answer":"A","explanation":"侧身、咬手电、碎石一滑，读者能跟着走。只说去了，旅程还没有开始。","choices":[{"key":"A","text":"洞口只容一个人侧身。我把手电咬在嘴里，脚下的碎石忽然滑了一下。"},{"key":"B","text":"我们去探险了。"},{"key":"C","text":"探险很神奇。"},{"key":"D","text":"神奇两个字。"}]}},"cnc_p396":{"desc":"缩句留下谁干什么，扩句加上合适的修饰，不改变主要意思。园地里还有弱冠、而立这些说年纪的词，这里先练句子的长短。","criteria":["能把句子写通顺","能按要求选用或修改句子"],"root":"","pre":[{"id":"cnc_p359","k":1,"why":"缩句、扩句之前，要先会修改重复和搭配不当的句子。"},{"id":"cnc_p395","k":0,"why":"按统编教材的常见教学顺序，先学「习作：神奇的探险之旅」，再学「语文园地六·缩句和扩句」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「可爱的熊猫在竹林里慢慢地吃鲜嫩的竹子。」缩句应是哪一句？","answer":"B","explanation":"缩句留下主干：谁，干什么。可爱、慢慢、鲜嫩都是修饰。","choices":[{"key":"A","text":"可爱的熊猫。"},{"key":"B","text":"熊猫吃竹子。"},{"key":"C","text":"慢慢地吃。"},{"key":"D","text":"竹林很美。"}]}},"cnc_p397":{"desc":"读懂马克·吐温怎样写小艇的样子、船夫的技术和夜晚的安静。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p396","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地六·缩句和扩句」，再学「阅读《威尼斯的小艇》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《威尼斯的小艇》的作者是谁？","answer":"C","explanation":"这篇是马克·吐温写的。《跳水》是托尔斯泰的，《牧场之国》是恰佩克的。","choices":[{"key":"A","text":"列夫·托尔斯泰"},{"key":"B","text":"卡雷尔·恰佩克"},{"key":"C","text":"马克·吐温"},{"key":"D","text":"穆青"}]}},"cnc_p398":{"desc":"读懂卡雷尔·恰佩克写的荷兰牧场：白天牛马羊很悠闲，夜晚沉入安静。课文里反复说「这就是真正的荷兰」。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p397","k":1,"why":"读《牧场之国》之前，要先读《威尼斯的小艇》，才不会把荷兰的牧场和威尼斯的小艇记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《牧场之国》写的是哪里？作者是谁？","answer":"D","explanation":"牧场、运河和成群的牛羊，写的是荷兰。小艇是威尼斯，金字塔是埃及。","choices":[{"key":"A","text":"威尼斯。作者是马克·吐温"},{"key":"B","text":"埃及。作者是穆青"},{"key":"C","text":"冀中。作者是谁都不是这篇"},{"key":"D","text":"荷兰。作者是卡雷尔·恰佩克"}]}},"cnc_p399":{"desc":"五下《金字塔》有两篇：《金字塔夕照》是穆青写的散文，夕阳下一片金色；《不可思议的金字塔》用图和数字介绍胡夫金字塔。不要和五年级上册那篇说明文记成同一篇。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p398","k":1,"why":"读五下《金字塔》之前，要先读《牧场之国》，两篇都写异域景物，才不会把牧场和金字塔记成同一处。"},{"id":"cnc_p347","k":1,"why":"读五下《金字塔夕照》和《不可思议的金字塔》之前，要先读过五上的说明文《金字塔》，才不会把夕照和上册那篇记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"五下《金字塔》包含哪两篇？","answer":"A","explanation":"一课两篇。上册的《金字塔》是另一篇说明文，小艇和牧场是同单元另外两课。","choices":[{"key":"A","text":"《金字塔夕照》和《不可思议的金字塔》"},{"key":"B","text":"只有上册那篇按方面介绍陵墓的说明文"},{"key":"C","text":"《威尼斯的小艇》和《牧场之国》"},{"key":"D","text":"《草船借箭》和《景阳冈》"}]}},"cnc_p400":{"desc":"选一处中国的世界文化遗产，写出它在哪里、是什么样子、为什么重要。口语交际「我是小小讲解员」也并在这里：要按顺序讲清楚，让没去过的人听得明白。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p399","k":1,"why":"介绍中国的世界文化遗产之前，要先会读五下《金字塔》这种把一处古迹写具体的课文。"},{"id":"cnc_p267","k":1,"why":"介绍中国的世界文化遗产之前，要先读过《秦兵马俑》，才知道这一类古迹可以怎样介绍。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一处适合作为这次习作的对象？","answer":"B","explanation":"长城在中国，也是世界文化遗产。牧场、小艇、埃及金字塔都不是这次要介绍的中国遗产。","choices":[{"key":"A","text":"荷兰的一片牧场"},{"key":"B","text":"长城"},{"key":"C","text":"威尼斯的一条小艇"},{"key":"D","text":"埃及的金字塔"}]}},"cnc_p401":{"desc":"能像《金字塔夕照》那样，用同一种色彩把一处景物写具体。园地里还有翁卷的《乡村四月》，这里先练色彩。","criteria":["能把句子写通顺","能按要求选用或修改句子"],"root":"","pre":[{"id":"cnc_p399","k":1,"why":"用色彩把景物写具体之前，要先读过《金字塔夕照》里成片的金色。"},{"id":"cnc_p400","k":0,"why":"按统编教材的常见教学顺序，先学「习作：中国的世界文化遗产」，再学「语文园地七·用色彩把景物写具体」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《金字塔夕照》为什么反复写金色？","answer":"C","explanation":"同一个颜色反复出现，画面才连成一片。借箭和小艇不是这句的意思。","choices":[{"key":"A","text":"因为金子可以借来当箭"},{"key":"B","text":"因为作者不会写别的字"},{"key":"C","text":"把夕阳下的田野、沙漠、河水和金字塔连成一片金色"},{"key":"D","text":"因为威尼斯的小艇是一匹金色的马"}]}},"cnc_p402":{"desc":"读懂《世说新语》里的孩子：孔君平用杨梅拿他的姓开玩笑，他用孔雀回敬，又没有失礼。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p393","k":1,"why":"读《杨氏之子》之前，要先会读《田忌赛马》这样的短文言文。"},{"id":"cnc_p401","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地七·用色彩把景物写具体」，再学「文言文《杨氏之子》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「孔君平诣其父，父不在，乃呼儿出。」是什么意思？","answer":"D","explanation":"诣是到某人那里去。父不在，所以见的是孩子。","choices":[{"key":"A","text":"孔君平不在，父亲出门去找他"},{"key":"B","text":"孩子去孔君平家里"},{"key":"C","text":"两个人一起去赛马"},{"key":"D","text":"孔君平来访，父亲不在，就把孩子叫出来"}]}},"cnc_p403":{"desc":"读懂丰子恺写五根手指：各有各的样子和用处，合在一起才能做事。大拇指最肯吃苦。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p402","k":1,"why":"读《手指》之前，要先读《杨氏之子》，才不会把孔君平的玩笑和五根手指记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《手指》的作者是谁？文章在写什么？","answer":"A","explanation":"五根手指被分开来写。月亮、金字塔、小艇是另外几课。","choices":[{"key":"A","text":"丰子恺。写一只手上五根手指不同的样子和用处"},{"key":"B","text":"季羡林。写五轮月亮"},{"key":"C","text":"穆青。写五座金字塔"},{"key":"D","text":"马克·吐温。写五只小艇"}]}},"cnc_p404":{"desc":"读懂费奥多罗夫写的童年：他觉得人在胚胎里的发育，好像把生物进化又走了一遍；上课时想笑，被老师误会。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p403","k":1,"why":"读《童年的发现》之前，要先读《手指》，才不会把五根手指和胚胎发育记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《童年的发现》的作者是谁？","answer":"B","explanation":"这篇是费奥多罗夫写自己童年的一次发现。丰子恺写《手指》。","choices":[{"key":"A","text":"丰子恺"},{"key":"B","text":"费奥多罗夫"},{"key":"C","text":"萧红"},{"key":"D","text":"季羡林"}]}},"cnc_p405":{"desc":"先写画面上有谁、在做什么，再写从这幅画里明白的道理。道理要和画面扣得上。它和五年级上册写老师特点的「漫画」不是同一篇习作。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p391","k":1,"why":"写漫画的启示之前，要先会把一个人的特点写具体，才知道道理要落在看得见的画面上。"},{"id":"cnc_p404","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《童年的发现》」，再学「习作：漫画的启示」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"写漫画的启示，第一步要怎样？","answer":"C","explanation":"读者没看见原画。不写画面，启示就没有来处。","choices":[{"key":"A","text":"不看画面，直接写一个无关的道理"},{"key":"B","text":"只写启示两个字"},{"key":"C","text":"先把画面上有谁、在做什么写清楚"},{"key":"D","text":"把漫画涂掉"}]}},"cnc_p406":{"desc":"读懂园地里的几句名言：君子看重道义，要有同情心，不义的事做多了会害自己。口语交际「我们都来讲笑话」并入本园地：要把事情讲完整，让人听出哪里可笑。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p405","k":0,"why":"按统编教材的常见教学顺序，先学「习作：漫画的启示」，再学「语文园地八·日积月累名言」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「君子喻于义，小人喻于利」是什么意思？","answer":"D","explanation":"喻是明白、看重。义和利是对面的。这句话出自《论语》。","choices":[{"key":"A","text":"君子只看重钱"},{"key":"B","text":"小人不会计较利益"},{"key":"C","text":"两句都在夸赚钱"},{"key":"D","text":"君子看重道义，小人看重利益"}]}},"cnc_p407":{"desc":"读懂老舍写的草原：一碧千里的景色，和蒙汉情深何忍别。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p406","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地八·日积月累名言」，再学「阅读《草原》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《草原》的作者是谁？","answer":"A","explanation":"这篇是老舍写的。《丁香结》才是宗璞的。","choices":[{"key":"A","text":"老舍"},{"key":"B","text":"宗璞"},{"key":"C","text":"朱自清"},{"key":"D","text":"鲁迅"}]}},"cnc_p408":{"desc":"读懂宗璞写城里城外的丁香，并把丁香结比成解不开的愁绪。课后的阅读链接《花之歌》不单列。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p407","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《草原》」，再学「阅读《丁香结》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《丁香结》的作者是谁？","answer":"B","explanation":"这篇散文是宗璞写的。老舍写的是《草原》。","choices":[{"key":"A","text":"老舍"},{"key":"B","text":"宗璞"},{"key":"C","text":"朱自清"},{"key":"D","text":"史铁生"}]}},"cnc_p409":{"desc":"背诵辛弃疾《西江月·夜行黄沙道中》，记住蛙声和忽见。同课还有《宿建德江》和《望湖楼醉书》，三首不要串句。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p355","k":1,"why":"背诵《西江月》之前，要先会背五年级的诗词。"},{"id":"cnc_p408","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《丁香结》」，再学「古诗《西江月·夜行黄沙道中》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「明月别枝惊鹊」的下一句是哪一句？","answer":"C","explanation":"先写月色惊起鹊鸟，再写半夜的蝉鸣。丰年是下片之前的第三句。","choices":[{"key":"A","text":"稻花香里说丰年"},{"key":"B","text":"七八个星天外"},{"key":"C","text":"清风半夜鸣蝉"},{"key":"D","text":"路转溪桥忽见"}]}},"cnc_p410":{"desc":"背诵孟浩然《宿建德江》，分清月近人和蛙声一片不是同一首。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p409","k":1,"why":"背《宿建德江》之前，要先会背《西江月》，才不会把蛙声和月近人记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「移舟泊烟渚」的下一句是哪一句？","answer":"D","explanation":"船停在烟雾里的小洲边，旅途的愁又涌上来。野旷是第三句。","choices":[{"key":"A","text":"野旷天低树"},{"key":"B","text":"江清月近人"},{"key":"C","text":"日暮客愁深"},{"key":"D","text":"日暮客愁新"}]}},"cnc_p411":{"desc":"背诵苏轼这首写骤雨的诗，记住跳珠和望湖楼。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p409","k":1,"why":"背《望湖楼醉书》之前，要先会背《西江月》，才不会把忽见和跳珠装错。"},{"id":"cnc_p410","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《宿建德江》」，再学「古诗《六月二十七日望湖楼醉书》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「黑云翻墨未遮山」的下一句是哪一句？","answer":"A","explanation":"雨点像珍珠，乱跳进船里。不是跳进湖里。卷地风是第三句。","choices":[{"key":"A","text":"白雨跳珠乱入船"},{"key":"B","text":"卷地风来忽吹散"},{"key":"C","text":"白雨跳珠乱入湖"},{"key":"D","text":"望湖楼下水如天"}]}},"cnc_p412":{"desc":"想象自己变成了另一种东西，把变化以后的所见所感写具体，重点部分写详细。只写「我变成了，然后很开心」不算。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p411","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《六月二十七日望湖楼醉书》」，再学「习作：变形记」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"变成一滴雨，哪一句把变化后的经历写出来了？","answer":"B","explanation":"顺着叶尖滚、砸在干土上，是变成雨以后才有的动作。空说开心还没有经历。","choices":[{"key":"A","text":"我变成了雨，很开心。"},{"key":"B","text":"我顺着叶尖滚下去，砸在干土上，土缝里立刻暗了一点。"},{"key":"C","text":"雨是水。"},{"key":"D","text":"变形记三个字。"}]}},"cnc_p413":{"desc":"读准屹、悼、炽、湃，不按半边猜。园地里的日积月累是孟浩然《过故人庄》，不要和同册《宿建德江》串成一首。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p327","k":1,"why":"读准六年级的易错字之前，要先改掉按半边猜的读音。"},{"id":"cnc_p412","k":0,"why":"按统编教材的常见教学顺序，先学「习作：变形记」，再学「语文园地一·易错字音：屹、悼、炽、湃」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「屹立」的「屹」读哪一个？","answer":"C","explanation":"屹立读 yì。不能读成气。","choices":[{"key":"A","text":"qì"},{"key":"B","text":"qǐ"},{"key":"C","text":"yì"},{"key":"D","text":"yǐ"}]}},"cnc_p414":{"desc":"背诵毛泽东《七律·长征》，记住只等闲、泥丸和尽开颜。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p409","k":1,"why":"背诵《七律·长征》之前，要先会背本册的词。"},{"id":"cnc_p413","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地一·易错字音：屹、悼、炽、湃」，再学「古诗《七律·长征》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「红军不怕远征难」的下一句是哪一句？","answer":"D","explanation":"远征的艰难在红军眼里只是平常事。是万水千山，不是千山万水。","choices":[{"key":"A","text":"五岭逶迤腾细浪"},{"key":"B","text":"金沙水拍云崖暖"},{"key":"C","text":"千山万水只等闲"},{"key":"D","text":"万水千山只等闲"}]}},"cnc_p415":{"desc":"读懂五位战士把敌人引上狼牙山顶峰，完成掩护任务后跳崖。这一课在第二单元，不要和后面的邱少云记成同一件事。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p414","k":1,"why":"读《狼牙山五壮士》之前，要先会背《七律·长征》，两篇都写革命岁月，才不会把五岭和跳崖记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"班长是谁？","answer":"A","explanation":"班长是马宝玉。葛振林是副班长。邱少云是同单元另一课里的战士。","choices":[{"key":"A","text":"马宝玉"},{"key":"B","text":"黄继光"},{"key":"C","text":"邱少云"},{"key":"D","text":"葛振林"}]}},"cnc_p416":{"desc":"能按时间说出一九四九年十月一日天安门典礼上的几件大事。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p415","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《狼牙山五壮士》」，再学「阅读《开国大典》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"开国大典是哪一天？","answer":"B","explanation":"课文写的是一九四九年十月一日。不要和别的历史日子记混。","choices":[{"key":"A","text":"一九一九年五月四日"},{"key":"B","text":"一九四九年十月一日"},{"key":"C","text":"一九二一年七月"},{"key":"D","text":"一九五零年十月"}]}},"cnc_p417":{"desc":"读懂邱少云潜伏时被火烧着，为了不暴露部队，直到牺牲也没有动。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p415","k":1,"why":"读《我的战友邱少云》之前，要先读《狼牙山五壮士》，才不会把烈火中一动不动和砸枪跳崖记成同一件事。"},{"id":"cnc_p416","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《开国大典》」，再学「阅读《我的战友邱少云》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"邱少云和战友们当时在做什么？","answer":"C","explanation":"他们潜伏在敌人前沿。跳崖是五壮士，钓鱼是《金色的鱼钩》。","choices":[{"key":"A","text":"在狼牙山顶跳崖"},{"key":"B","text":"在天安门参加典礼"},{"key":"C","text":"潜伏在山坡上，准备傍晚进攻"},{"key":"D","text":"在草地上钓鱼"}]}},"cnc_p418":{"desc":"写一次集体活动：既有全场的场面，也有一两个人的具体动作。只写「大家很高兴」还没有场面。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p417","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《我的战友邱少云》」，再学「习作：多彩的活动」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"写拔河，哪一句是在写全场？","answer":"D","explanation":"两边喊、红绳套晃，是整个场面。同桌蹬地是其中一个人，要另外写。","choices":[{"key":"A","text":"我的同桌咬着牙，脚往土里蹬。"},{"key":"B","text":"拔河两个字。"},{"key":"C","text":"星期一有体育课。"},{"key":"D","text":"操场两边都在喊，绳子中间的红绳套左右晃。"}]}},"cnc_p419":{"desc":"记熟园地里的爱国名言，分清是谁说的。口语「演讲」要先亮出观点，再用具体的事说明；写场面则把全场和其中一个人结合起来。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p418","k":0,"why":"按统编教材的常见教学顺序，先学「习作：多彩的活动」，再学「语文园地二·爱国名言」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「捐躯赴国难，视死忽如归」是谁的诗句？","answer":"A","explanation":"这一句出自曹植《白马篇》。陆游的是「位卑未敢忘忧国」。","choices":[{"key":"A","text":"曹植"},{"key":"B","text":"陆游"},{"key":"C","text":"李纲"},{"key":"D","text":"孔子"}]}},"cnc_p420":{"desc":"读懂同学们用毛笔杆做竹节人，老师没收以后自己也玩上了。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p419","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·爱国名言」，再学「阅读《竹节人》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"竹节人是用什么做的？","answer":"B","explanation":"破旧的毛笔杆被锯成一段段，装上头，就成了会斗的竹节人。","choices":[{"key":"A","text":"用竹子刻成真人大小"},{"key":"B","text":"毛笔杆锯成小段，用线连起来"},{"key":"C","text":"用泥捏的"},{"key":"D","text":"用纸折的飞机"}]}},"cnc_p421":{"desc":"能从这篇说明文里找出生命存在的条件，并知道火星上还没有确切证据。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p420","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《竹节人》」，再学「阅读《宇宙生命之谜》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文分析生命能不能存在，依据的是什么？","answer":"C","explanation":"说明文是按条件讨论的，不是按故事情节，也不是按游览路线。","choices":[{"key":"A","text":"谁先写完古诗"},{"key":"B","text":"宫殿从南到北的路线"},{"key":"C","text":"温度、水分、大气、光和热这些条件"},{"key":"D","text":"人物对话长不长"}]}},"cnc_p422":{"desc":"能按从南到北的中轴线说出太和殿的位置和用途。这一课在第三单元，读的时候要带着「故宫的建筑」这个目的去找路线。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p421","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《宇宙生命之谜》」，再学「阅读《故宫博物院》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文介绍故宫，主要按什么顺序？","answer":"D","explanation":"从天安门往里，沿着中轴线一座一座写过去。开国大典才是时间顺序。","choices":[{"key":"A","text":"从早到晚的时间顺序"},{"key":"B","text":"按建筑的造价从低到高"},{"key":"C","text":"只写传说，不写路线"},{"key":"D","text":"从南到北的空间顺序"}]}},"cnc_p423":{"desc":"横线上填阅读、音乐、运动这一类，写出它怎样改变了你的一件具体的事，并说出你的看法。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p422","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《故宫博物院》」，再学「习作：____让生活更美好」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"题目是「阅读让生活更美好」。哪一句是在写自己的看法？","answer":"A","explanation":"把步骤写下来，是阅读带给你的看法。书厚和楼层还没有看法。","choices":[{"key":"A","text":"读完那本传记，我才觉得遇到难事可以先把步骤写下来。"},{"key":"B","text":"阅读两个字。"},{"key":"C","text":"书很厚。"},{"key":"D","text":"图书馆在二楼。"}]}},"cnc_p424":{"desc":"能按偏旁分清慨、概、溉，不把慷慨写成慷概。园地的日积月累是朱熹《观书有感》（其二），不是《春日》。读说明文时还要按目的去选材料。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p379","k":1,"why":"分辨慨、概、溉之前，要先会看偏旁表示的意思。"},{"id":"cnc_p423","k":0,"why":"按统编教材的常见教学顺序，先学「习作：____让生活更美好」，再学「语文园地三·形近字：慨、概、溉」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「慷____」横线处该写哪一个？","answer":"B","explanation":"慷慨和心情有关，是竖心旁的慨。凯没有竖心。","choices":[{"key":"A","text":"概"},{"key":"B","text":"慨"},{"key":"C","text":"溉"},{"key":"D","text":"凯"}]}},"cnc_p425":{"desc":"读懂洪水来时，老支书让村民先过桥，自己和儿子留在后面。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p394","k":1,"why":"体会小说结尾之前，要先会根据情节理解人物做法。"},{"id":"cnc_p424","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地三·形近字：慨、概、溉」，再学「阅读《桥》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"洪水冲来时，老支书让谁先过桥？","answer":"C","explanation":"他把生的希望让给村民，指挥大家按顺序过桥。","choices":[{"key":"A","text":"他自己"},{"key":"B","text":"只让他的儿子"},{"key":"C","text":"村民"},{"key":"D","text":"谁也不许过"}]}},"cnc_p426":{"desc":"读懂桑娜抱回西蒙的孩子以后，渔夫说要一起把孩子养活。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p425","k":1,"why":"理解人物对话的含义之前，要先会读懂小说的情节。"}],"q":{"type":"choice","difficulty":"basic","prompt":"桑娜推开西蒙的门，看见了什么？","answer":"D","explanation":"西蒙死了，孩子还在她身边。这篇是列夫·托尔斯泰写的。","choices":[{"key":"A","text":"西蒙带着孩子来做客"},{"key":"B","text":"渔夫已经把孩子抱走了"},{"key":"C","text":"屋子里一个人也没有"},{"key":"D","text":"西蒙已经死去，两个孩子还活着"}]}},"cnc_p427":{"desc":"读懂老班长在草地上把鱼留给三个小战士，自己最后没能走出草地。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p426","k":1,"why":"读《金色的鱼钩》之前，要先读《穷人》，两篇都写把生的希望留给别人，才不会把西蒙的孩子和老班长的鱼钩记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"老班长接受的任务是什么？","answer":"A","explanation":"指导员把战士交给他。过桥是《桥》，抱孩子是《穷人》。","choices":[{"key":"A","text":"把三个生病的小战士带出草地"},{"key":"B","text":"指挥村民过桥"},{"key":"C","text":"把邻居的孩子抱回家"},{"key":"D","text":"潜伏在山坡上"}]}},"cnc_p428":{"desc":"编一个有起因、经过和结果的故事，让人物在具体的环境里行动。只写「从前有个人」还不是故事。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p427","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《金色的鱼钩》」，再学「习作：笔尖流出的故事」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"一个故事至少要有什么？","answer":"B","explanation":"起因、经过、结果连起来，才叫故事。题目和生字表还没有情节。","choices":[{"key":"A","text":"只有一个题目"},{"key":"B","text":"事情怎样开始、中间出了什么状况、最后怎样"},{"key":"C","text":"只写天气很好"},{"key":"D","text":"把生字表抄下来"}]}},"cnc_p429":{"desc":"能联系上下文推想一个词在句子里的意思，而不是只背词典义。口语「请你支持我」要把理由说清楚，并说出希望对方怎样做。","criteria":["能理解词语在句子里的意思","能选出搭配恰当的词语"],"root":"","pre":[{"id":"cnc_p334","k":1,"why":"品味含义深刻的词句之前，要先会联系上下文理解词语。"},{"id":"cnc_p428","k":0,"why":"按统编教材的常见教学顺序，先学「习作：笔尖流出的故事」，再学「语文园地四·品味含义深刻的词句」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「桥在洪水里发抖。」这里的「发抖」是什么意思？","answer":"C","explanation":"桥不会真的冷。发抖写出它在洪水中摇晃。","choices":[{"key":"A","text":"桥觉得很冷"},{"key":"B","text":"桥在说话"},{"key":"C","text":"桥被洪水冲击，好像站不稳"},{"key":"D","text":"桥已经断了"}]}},"cnc_p430":{"desc":"读写人物成长的书时，记下让人发笑或难过的经历，并看出人物后来有什么变化。这和五下读古典名著不是同一次阅读。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p429","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地四·品味含义深刻的词句」，再学「快乐读书吧：笑与泪，经历与成长」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这次阅读最该留意的是什么？","answer":"D","explanation":"书名里的笑、泪、经历、成长，就是阅读时要抓住的四件事。","choices":[{"key":"A","text":"只记作者的国籍"},{"key":"B","text":"只看封面颜色"},{"key":"C","text":"把目录抄成生字"},{"key":"D","text":"人物经历了哪些笑与泪，后来怎样长大"}]}},"cnc_p431":{"desc":"读懂王愿坚写的郝副营长：他向往图上孩子在灯下读书的生活，战斗中点燃书本为后续部队照路，自己牺牲了。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p416","k":1,"why":"读《灯光》之前，要先读《开国大典》，才不会把郝副营长梦见的灯和一九四九年的典礼记成同一件事。"},{"id":"cnc_p430","k":0,"why":"按统编教材的常见教学顺序，先学「快乐读书吧：笑与泪，经历与成长」，再学「阅读《灯光》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"郝副营长在战斗前看的画上有什么？","answer":"A","explanation":"他指着插图说，以后也要让孩子们在这样的灯光下学习。","choices":[{"key":"A","text":"孩子在电灯下读书"},{"key":"B","text":"一场洪水里的木桥"},{"key":"C","text":"天安门城楼上的典礼"},{"key":"D","text":"一只金色的鱼钩"}]}},"cnc_p432":{"desc":"读懂铁凝写的「我」盼着穿上新雨衣：从得到雨衣、盼下雨，到想借买酱油出门，终于如愿。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p431","k":1,"why":"读《盼》之前，要先读《灯光》，才不会把盼穿雨衣和郝副营长牺牲记成同一个中心。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「我」盼的是什么？","answer":"B","explanation":"整篇都绕着这件新雨衣。电灯是《灯光》的中心。","choices":[{"key":"A","text":"郝副营长能看见电灯"},{"key":"B","text":"穿上妈妈买的新雨衣，到雨里走一走"},{"key":"C","text":"雨衣能卖个好价钱"},{"key":"D","text":"明天不用上学"}]}},"cnc_p433":{"desc":"先定下一个中心意思，再选能表现它的材料，最能表现中心的部分写详细。例文《爸爸的计划》《小站》不单列。本单元没有语文园地。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p391","k":1,"why":"围绕中心意思写之前，要先会抓住人或事的特点来写。"},{"id":"cnc_p432","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《盼》」，再学「习作：围绕中心意思写」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"中心是「这次拔河我们班没有松手」。哪一项该写得最详细？","answer":"C","explanation":"往后坐、绳子过来，最能表现没有松手。鸡蛋和窗户跟这个中心无关。","choices":[{"key":"A","text":"早上我吃了一个鸡蛋。"},{"key":"B","text":"教室有四扇窗。"},{"key":"C","text":"最后十几秒，好几个人一起往后坐，绳子才过来。"},{"key":"D","text":"拔河两个字。"}]}},"cnc_p434":{"desc":"抓住关键句：地球美丽又渺小，资源有限，人类还不能移居别的星球，所以要精心保护这一个地球。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p421","k":1,"why":"读《只有一个地球》之前，要先读《宇宙生命之谜》，才不会把火星上有没有生命和必须保护地球记成同一个结论。"},{"id":"cnc_p433","k":0,"why":"按统编教材的常见教学顺序，先学「习作：围绕中心意思写」，再学「阅读《只有一个地球》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文把地球比作什么？","answer":"D","explanation":"母亲和摇篮都在说：离开它，人类无法生活。","choices":[{"key":"A","text":"一艘可以随便换的新船"},{"key":"B","text":"一座取之不尽的仓库"},{"key":"C","text":"火星的卫星"},{"key":"D","text":"人类的母亲，生命的摇篮"}]}},"cnc_p435":{"desc":"读懂一位老人在晋西北种了十几年树，窗外的青山说明人可以留下一片绿。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p434","k":1,"why":"读《青山不老》之前，要先读《只有一个地球》，才不会把一位老人种树和整颗星球的资源记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"老人长期在哪里种树？","answer":"A","explanation":"风沙大的晋西北，是他种树的地方。不要和草原、故宫记混。","choices":[{"key":"A","text":"晋西北的山沟"},{"key":"B","text":"北京的天安门"},{"key":"C","text":"内蒙古的草原"},{"key":"D","text":"故宫的御花园"}]}},"cnc_p436":{"desc":"读懂苏金伞这首诗：农民三黑重新得到土地，恨不得自己变成种子躺进去。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p435","k":1,"why":"读《三黑和土地》之前，要先读《青山不老》，才不会把农民重新得到土地和老人种树记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"三黑为什么那么高兴？","answer":"B","explanation":"诗写的是土地失而复得。种树是《青山不老》，雨衣是《盼》。","choices":[{"key":"A","text":"他在晋西北种活了一片林"},{"key":"B","text":"土地重新回到了农民手里"},{"key":"C","text":"他发现地球可以搬家"},{"key":"D","text":"他得到了一件新雨衣"}]}},"cnc_p437":{"desc":"背诵刘禹锡《浪淘沙》（其一），记住九曲黄河和牵牛织女家，不要和《江南春》串句。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p436","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《三黑和土地》」，再学「古诗《浪淘沙》（其一）」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「九曲黄河万里沙」的下一句是哪一句？","answer":"C","explanation":"黄河裹着泥沙，从极远的地方风浪颠簸而来。直上银河是第三句。","choices":[{"key":"A","text":"如今直上银河去"},{"key":"B","text":"千里莺啼绿映红"},{"key":"C","text":"浪淘风簸自天涯"},{"key":"D","text":"浪淘风簸到天涯"}]}},"cnc_p438":{"desc":"背诵杜牧《江南春》，记住千里莺啼和四百八十寺，不要和《浪淘沙》串句。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p437","k":1,"why":"背《江南春》之前，要先分清《浪淘沙》（其一），才不会把九曲黄河和千里莺啼记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「千里莺啼绿映红」的下一句是哪一句？","answer":"D","explanation":"莺啼、绿树、红花之后，是水村、山城和风里的酒旗。四百八十寺是第三句。","choices":[{"key":"A","text":"南朝四百八十寺"},{"key":"B","text":"九曲黄河万里沙"},{"key":"C","text":"水村山郭酒旗中"},{"key":"D","text":"水村山郭酒旗风"}]}},"cnc_p439":{"desc":"背诵王安石《书湖阴先生壁》，记住一水护田和两山排闼。不要和《江南春》记混。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p438","k":1,"why":"背《书湖阴先生壁》之前，要先分清《江南春》，才不会把南朝四百八十寺和两山排闼记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「茅檐长扫净无苔」写的是什么？","answer":"A","explanation":"净无苔是主人把小院照料得很干净。黄河和烟雨是另外两首。","choices":[{"key":"A","text":"屋檐下经常打扫，干净得不长青苔"},{"key":"B","text":"黄河从天边滚来"},{"key":"C","text":"南朝的寺庙隐在烟雨里"},{"key":"D","text":"茅屋被大雨冲垮了"}]}},"cnc_p440":{"desc":"写倡议书要有称呼、为什么要做、一两件具体的做法，以及署名和日期。只写「请大家保护环境」六个字还不像倡议书。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p439","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《书湖阴先生壁》」，再学「习作：学写倡议书」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"倡议书开头通常先写什么？","answer":"B","explanation":"对同学、对邻居，称呼不一样。没有对象，倡议就不知道说给谁。","choices":[{"key":"A","text":"先画一幅画"},{"key":"B","text":"称呼，写清你在对谁说"},{"key":"C","text":"先抄一首古诗"},{"key":"D","text":"先写自己的学号就结束"}]}},"cnc_p441":{"desc":"第五单元是习作单元，没有语文园地，关联词收到园地六来练。能把不但和而且、只要和就、只有和才配成对。口语「意见不同怎么办」要先说清自己的看法，再听对方的理由。","criteria":["能把句子写通顺","能按要求选用或修改句子"],"root":"","pre":[{"id":"cnc_p273","k":1,"why":"学习不但而且、只要就之前，要先会把因为所以、虽然但是配成对。"},{"id":"cnc_p440","k":0,"why":"按统编教材的常见教学顺序，先学「习作：学写倡议书」，再学「语文园地六·关联词：不但而且、只要就」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「他____修好了桌子，____把工具放回了原处。」哪一组填得对？","answer":"C","explanation":"两件事都做到了，后一件更进一步，用不但……而且……。","choices":[{"key":"A","text":"不但……就……"},{"key":"B","text":"只要……而且……"},{"key":"C","text":"不但……而且……"},{"key":"D","text":"虽然……而且……"}]}},"cnc_p442":{"desc":"读懂两个孩子争论太阳早晚远近，孔子不能判断谁对。不要和同课的《曹冲称象》记成同一则。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p392","k":1,"why":"读《两小儿辩日》之前，要先会读懂《自相矛盾》这样的浅易文言文。"},{"id":"cnc_p441","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地六·关联词：不但而且、只要就」，再学「文言文《两小儿辩日》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"两个孩子争论的是什么？","answer":"D","explanation":"一个说早晨近，一个说中午近。称象是下一则。","choices":[{"key":"A","text":"大象到底有多重"},{"key":"B","text":"谁的车盖更大"},{"key":"C","text":"孔子今天去不去上学"},{"key":"D","text":"太阳什么时候离人近，什么时候离人远"}]}},"cnc_p443":{"desc":"读懂曹冲把大象赶上船，记下吃水的印子，再称同样吃水的东西。不要和《两小儿辩日》记成同一则。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p442","k":1,"why":"读《曹冲称象》之前，要先读《两小儿辩日》，两则文言文才不会把称象和辩日记成同一则。"}],"q":{"type":"choice","difficulty":"basic","prompt":"曹操想知道什么？","answer":"A","explanation":"大象太大，直接称不了。太阳远近是上一则的问题。","choices":[{"key":"A","text":"大象有多重"},{"key":"B","text":"太阳早上近还是中午近"},{"key":"C","text":"船上有多少人"},{"key":"D","text":"石头是什么颜色"}]}},"cnc_p444":{"desc":"读懂冯至写的童年：凡是自己会响的都被当成活物，父亲说怀表里有一只小蝎子。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p443","k":0,"why":"按统编教材的常见教学顺序，先学「文言文《曹冲称象》」，再学「阅读《表里的生物》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"小时候的「我」以为什么才会自己发出声音？","answer":"B","explanation":"鸟叫、狗吠、蝉鸣，都是活的。所以表自己滴答响，他就觉得里面有生物。","choices":[{"key":"A","text":"所有的石头"},{"key":"B","text":"活的生物"},{"key":"C","text":"只有风"},{"key":"D","text":"只有人说话"}]}},"cnc_p445":{"desc":"读懂阿西莫夫这篇科幻：二一五五年玛琪在家跟机器老师学，却向往过去孩子们一起上学的日子。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p444","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《表里的生物》」，再学「阅读《他们那时候多有趣啊》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"故事发生在哪一年？","answer":"C","explanation":"开头写二一五五年五月十七日，说明这是想象中的未来。","choices":[{"key":"A","text":"一九四九年"},{"key":"B","text":"故事里没有年份"},{"key":"C","text":"二一五五年"},{"key":"D","text":"孔子的时代"}]}},"cnc_p446":{"desc":"从一个好奇的问题写起，大胆想象，也要把想象里的步骤写清楚，让人跟得上。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p445","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《他们那时候多有趣啊》」，再学「习作：插上科学的翅膀飞」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一个题目更适合这次习作？","answer":"D","explanation":"书包送信是科学想象。口算、抄写和住址没有翅膀可飞。","choices":[{"key":"A","text":"今天的数学口算"},{"key":"B","text":"抄写五行和五谷"},{"key":"C","text":"我的家庭住址"},{"key":"D","text":"假如书包能自己把忘带的笔送回教室"}]}},"cnc_p447":{"desc":"能在《两小儿辩日》和《曹冲称象》的句子里分清之、其、而。园地的日积月累还有五行、五谷、五音、五彩，这里先把虚词读准。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p442","k":1,"why":"理解之、其、而之前，要先读懂《两小儿辩日》，这些字就在句子里。"},{"id":"cnc_p446","k":0,"why":"按统编教材的常见教学顺序，先学「习作：插上科学的翅膀飞」，再学「语文园地七·文言虚词：之、其、而」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「问其故」里的「其」指什么？","answer":"A","explanation":"孔子问的是两个孩子为什么一个说近、一个说远。其在这里指那件事的原因。","choices":[{"key":"A","text":"他们这样说的缘故"},{"key":"B","text":"大象的重量"},{"key":"C","text":"孔子的名字"},{"key":"D","text":"一只小蝎子"}]}},"cnc_p448":{"desc":"读懂鲁迅在《故乡》里记住的闰土：项带银圈，手捏钢叉，讲雪地捕鸟、看瓜刺猹。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p447","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地七·文言虚词：之、其、而」，再学「阅读《少年闰土》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《少年闰土》选自谁的哪篇作品？","answer":"B","explanation":"「我」回忆的玩伴是闰土。伯父那篇的作者是周晔。","choices":[{"key":"A","text":"周晔写伯父"},{"key":"B","text":"鲁迅的《故乡》"},{"key":"C","text":"臧克家的《有的人》"},{"key":"D","text":"老舍的《草原》"}]}},"cnc_p449":{"desc":"读懂鲁迅写的一个梦：昏沉的夜里，梦境美丽、幽雅、有趣，醒来还记得。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p448","k":1,"why":"读《好的故事》之前，要先读《少年闰土》，才不会把梦里的山水和海边刺猹记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《好的故事》是谁写的？","answer":"C","explanation":"这篇是鲁迅的散文诗。周晔写的是伯父，臧克家写的是《有的人》。","choices":[{"key":"A","text":"周晔"},{"key":"B","text":"臧克家"},{"key":"C","text":"鲁迅"},{"key":"D","text":"冯至"}]}},"cnc_p450":{"desc":"读懂周晔写的伯父：谈《水浒传》问倒了「我」，说「碰壁」，又救助车夫、关心女佣。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p449","k":1,"why":"读《我的伯父鲁迅先生》之前，要先读《好的故事》，一篇是鲁迅写的梦，一篇是侄女写鲁迅，才不会把梦境和救助车夫记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文的作者是谁，伯父又是谁？","answer":"D","explanation":"侄女回忆伯父。不要把作者和鲁迅换成同一个人。","choices":[{"key":"A","text":"作者是鲁迅，伯父是闰土"},{"key":"B","text":"作者是臧克家，伯父是周晔"},{"key":"C","text":"作者是老舍，伯父是鲁迅"},{"key":"D","text":"作者是周晔，伯父是鲁迅"}]}},"cnc_p451":{"desc":"读懂臧克家纪念鲁迅的诗：有的人死了还活着，有的人活着却已经死了。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p450","k":1,"why":"读《有的人》之前，要先读《我的伯父鲁迅先生》，才不会把「俯下身子给人民当牛马」只记成诗句、忘了课文里的事。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《有的人》是谁写的，纪念谁？","answer":"A","explanation":"副题是纪念鲁迅有感。作者不是鲁迅本人。","choices":[{"key":"A","text":"臧克家纪念鲁迅"},{"key":"B","text":"鲁迅纪念闰土"},{"key":"C","text":"周晔纪念车夫"},{"key":"D","text":"老舍纪念草原"}]}},"cnc_p452":{"desc":"用一两件家里真实的事写出一种家风。只写「我家家风很好」还看不见家风。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p451","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《有的人》」，再学「习作：传承好家风」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一句写出了家风，而不只是口号？","answer":"B","explanation":"周四夜里补凳腿，是说到做到。空说很好，读者不知道好在哪里。","choices":[{"key":"A","text":"我家家风很好。"},{"key":"B","text":"爷爷答应邻居周五修好凳子，周四夜里还在灯下补那条腿。"},{"key":"C","text":"家风两个字。"},{"key":"D","text":"我们是一家人。"}]}},"cnc_p453":{"desc":"记熟园地里的鲁迅名言，分清出自《答客诮》《自题小像》《故乡》还是杂文。园地还练给文章拟题，并了解柳公权《玄秘塔碑》柳体瘦硬。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p452","k":0,"why":"按统编教材的常见教学顺序，先学「习作：传承好家风」，再学「语文园地八·鲁迅名言」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「无情未必真豪杰」的下一句是哪一句？","answer":"C","explanation":"出自《答客诮》。真正的豪杰也可以疼爱孩子。荐轩辕是《自题小像》。","choices":[{"key":"A","text":"我以我血荐轩辕"},{"key":"B","text":"走的人多了，也便成了路"},{"key":"C","text":"怜子如何不丈夫"},{"key":"D","text":"俯首甘为孺子牛"}]}},"cnc_p454":{"desc":"能按时间顺序说出老舍写到的腊八、腊月二十三、除夕、正月初一和元宵。除夕和元宵写得更详细。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p357","k":1,"why":"按时间顺序把握《北京的春节》之前，要先会区分《第一场雪》里下雪时的动态和下雪后的静态，才不会把一场雪和一整个春节的日子记成同一篇。"},{"id":"cnc_p453","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地八·鲁迅名言」，再学「阅读《北京的春节》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"老舍写春节，最先写到哪一天？","answer":"D","explanation":"文章从腊八粥写起，再往后写。这篇是老舍写的。","choices":[{"key":"A","text":"除夕"},{"key":"B","text":"正月初一"},{"key":"C","text":"元宵"},{"key":"D","text":"腊八"}]}},"cnc_p455":{"desc":"读懂沈从文笔下的八儿怎样盼着那锅又稠又甜的腊八粥。不要和老舍《北京的春节》记成同一篇。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p454","k":1,"why":"读《腊八粥》里八儿怎样盼粥之前，要先读过《北京的春节》，两篇写腊八的课文才不会记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文里一直盼着吃粥的孩子叫什么？","answer":"A","explanation":"八儿围着灶台转，问粥什么时候才好。","choices":[{"key":"A","text":"八儿"},{"key":"B","text":"雨来"},{"key":"C","text":"牛郎"},{"key":"D","text":"闰土"}]}},"cnc_p456":{"desc":"背诵韩翃《寒食》，记住飞花、御柳和五侯家。同课还有《迢迢牵牛星》和《十五夜望月》。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p409","k":1,"why":"背诵《寒食》之前，要先会背六年级上册的诗词。"},{"id":"cnc_p455","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《腊八粥》」，再学「古诗《寒食》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「春城无处不飞花」的下一句是哪一句？","answer":"B","explanation":"寒食节的东风吹斜了宫柳。飞花不能记成飞雪或飞絮。","choices":[{"key":"A","text":"日暮汉宫传蜡烛"},{"key":"B","text":"寒食东风御柳斜"},{"key":"C","text":"春城无处不飞雪"},{"key":"D","text":"春城无处不飞絮"}]}},"cnc_p457":{"desc":"背诵《古诗十九首》里的《迢迢牵牛星》，记住脉脉，不写成默默。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p456","k":1,"why":"背《迢迢牵牛星》之前，要先会背《寒食》，才不会把飞花和脉脉不得语记混。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「迢迢牵牛星」的下一句是哪一句？","answer":"C","explanation":"牵牛星对的是织女。纤纤、札札是后面写织布的句子。","choices":[{"key":"A","text":"纤纤擢素手"},{"key":"B","text":"盈盈一水间"},{"key":"C","text":"皎皎河汉女"},{"key":"D","text":"札札弄机杼"}]}},"cnc_p458":{"desc":"背诵王建《十五夜望月》，记住秋思落谁家，不要写成愁思。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p456","k":1,"why":"背《十五夜望月》之前，要先会背《寒食》，才不会把御柳斜和秋思落谁家记成同一首。"},{"id":"cnc_p457","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《迢迢牵牛星》」，再学「古诗《十五夜望月》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「中庭地白树栖鸦」的下一句是哪一句？","answer":"D","explanation":"院子被月光照亮，接着写露水悄悄打湿桂花。不是有声。","choices":[{"key":"A","text":"不知秋思落谁家"},{"key":"B","text":"冷露有声湿桂花"},{"key":"C","text":"今夜月明人尽望"},{"key":"D","text":"冷露无声湿桂花"}]}},"cnc_p459":{"desc":"读懂藏戏戴面具、没有舞台、一部戏可以连演几天，并知道唐东杰布为修桥开创了藏戏。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p455","k":1,"why":"读《藏戏》之前，要先读过《腊八粥》，两篇都写民俗，才不会把盼粥和面具记成同一篇。"},{"id":"cnc_p458","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《十五夜望月》」，再学「阅读《藏戏》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文开头用三个反问，强调藏戏的哪三个特点？","answer":"A","explanation":"面具、没有舞台、演出时间长，是开篇就点出的特点。","choices":[{"key":"A","text":"戴着面具演出，没有舞台，一部戏可以演三五天还没结束"},{"key":"B","text":"必须在剧院里演一夜"},{"key":"C","text":"不许戴面具，必须有华丽布景"},{"key":"D","text":"只能由一个人演唱"}]}},"cnc_p460":{"desc":"介绍一种家乡风俗，把人们怎么过写清楚，最有特点的部分写详细，并写出自己的感受。只写「我们那里过节很热闹」还不够。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p454","k":1,"why":"写家乡的风俗之前，要先读过《北京的春节》，才知道习俗要按人们怎么过写清楚。"},{"id":"cnc_p459","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《藏戏》」，再学「习作：家乡的风俗」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"写家乡的风俗，哪一段把过程写出来了？","answer":"B","explanation":"抹灶糖、说好话，是这一天具体怎么过。空说热闹，别人看不出是哪种风俗。","choices":[{"key":"A","text":"我的家乡风俗很多。"},{"key":"B","text":"腊月二十三晚上，奶奶把灶糖化开，抹在灶王像的嘴上，说好话上天。"},{"key":"C","text":"过节很热闹，非常有意思。"},{"key":"D","text":"北京的春节是老舍写的。"}]}},"cnc_p461":{"desc":"读准腊八粥、元宵、饺子、祭灶里容易读错的字。口语「即兴发言」要先看清对谁说，抓住一两点就说完。园地还要分清内容的主次。日积月累背汉乐府《长歌行》，记住少壮不努力，老大徒伤悲。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p413","k":1,"why":"读准下册的易错字之前，要先改掉上册那些按半边猜的读音。"},{"id":"cnc_p460","k":0,"why":"按统编教材的常见教学顺序，先学「习作：家乡的风俗」，再学「语文园地一·易错字音：粥、宵、饺、祭」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「腊八粥」的「粥」读哪一个？","answer":"C","explanation":"粥读 zhōu。不能读成住。","choices":[{"key":"A","text":"zhù"},{"key":"B","text":"yù"},{"key":"C","text":"zhōu"},{"key":"D","text":"zhǒu"}]}},"cnc_p462":{"desc":"读懂笛福写的鲁滨逊流落荒岛后怎样安排生活，并把坏处和好处对照着看。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p372","k":1,"why":"读外国名著节选之前，要先会抓住古典名著里的主要事件。"},{"id":"cnc_p461","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地一·易错字音：粥、宵、饺、祭」，再学「阅读《鲁滨逊漂流记》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《鲁滨逊漂流记》的作者是谁？","answer":"D","explanation":"作者是英国作家笛福。马克·吐温写的是汤姆·索亚。","choices":[{"key":"A","text":"马克·吐温"},{"key":"B","text":"托尔斯泰"},{"key":"C","text":"老舍"},{"key":"D","text":"笛福"}]}},"cnc_p463":{"desc":"读懂拉格洛芙写的尼尔斯被变成小人以后骑鹅旅行，后来变得善良。不要和鲁滨逊记成同一个故事。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p462","k":1,"why":"读《骑鹅旅行记》之前，要先会梳理《鲁滨逊漂流记》的情节，才不会把荒岛和骑鹅记成同一个故事。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《骑鹅旅行记》的作者是谁？","answer":"A","explanation":"作者是瑞典的拉格洛芙。笛福写的是鲁滨逊，不要记混。","choices":[{"key":"A","text":"拉格洛芙"},{"key":"B","text":"笛福"},{"key":"C","text":"马克·吐温"},{"key":"D","text":"安徒生"}]}},"cnc_p464":{"desc":"读懂马克·吐温写的汤姆把刷墙说成稀罕事，小伙伴反而抢着来刷。这一课在第二单元，不要和鲁滨逊、尼尔斯记成同一个故事。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p462","k":1,"why":"读《汤姆·索亚历险记》之前，要先会读懂另一篇外国名著节选的情节。"},{"id":"cnc_p463","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《骑鹅旅行记》」，再学「阅读《汤姆·索亚历险记》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《汤姆·索亚历险记》的作者是谁？","answer":"B","explanation":"作者是马克·吐温。他也写过《威尼斯的小艇》。鲁滨逊的作者是笛福。","choices":[{"key":"A","text":"笛福"},{"key":"B","text":"马克·吐温"},{"key":"C","text":"托尔斯泰"},{"key":"D","text":"拉格洛芙"}]}},"cnc_p465":{"desc":"用简洁的话写出书的主要人物和主要情节，按顺序写，删掉大段的景物和心理描写。不能把结局改掉。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p462","k":1,"why":"写作品梗概之前，要先会梳理《鲁滨逊漂流记》的主要情节。"},{"id":"cnc_p464","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《汤姆·索亚历险记》」，再学「习作：写作品梗概」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"作品梗概最该留下什么？","answer":"C","explanation":"梗概是把故事的骨架说清楚。风景和好词可以留在原文里。","choices":[{"key":"A","text":"每一处风景的颜色"},{"key":"B","text":"作者用了多少个比喻"},{"key":"C","text":"主要人物做了哪些关键的事，事情怎样发展"},{"key":"D","text":"自己抄下来的好词好句"}]}},"cnc_p466":{"desc":"能按词读准泊、漂、载、难。口语「同读一本书」要说出书名、印象深的人物和自己的看法。日积月累有「读书须用意，一字值千金」。","criteria":["能分辨形近字和同音字","能按偏旁和结构识记生字"],"root":"","pre":[{"id":"cnc_p333","k":1,"why":"按词读准泊、漂、载、难之前，要先会分辨多音字的不同读音。"},{"id":"cnc_p465","k":0,"why":"按统编教材的常见教学顺序，先学「习作：写作品梗概」，再学「语文园地二·多音字：泊、漂、载、难」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「停泊」的「泊」读哪一个？","answer":"D","explanation":"停泊、漂泊读 bó。湖泊、血泊才读 pō。","choices":[{"key":"A","text":"pō"},{"key":"B","text":"bò"},{"key":"C","text":"pò"},{"key":"D","text":"bó"}]}},"cnc_p467":{"desc":"能判断同一个词在不同句子里的意思。读名著时评价人物，也要联系他做的事，不能拿一个词套所有人。","criteria":["能理解词语在句子里的意思","能选出搭配恰当的词语"],"root":"","pre":[{"id":"cnc_p429","k":1,"why":"推想词语在语境中的意思，要先会品味词句。"},{"id":"cnc_p466","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·多音字：泊、漂、载、难」，再学「语文园地二·词语的语境义」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「这道题有意思」里的「意思」是什么？","answer":"A","explanation":"说题目有意思，是说它有趣味，不是要送礼。","choices":[{"key":"A","text":"有趣味"},{"key":"B","text":"有意见"},{"key":"C","text":"有礼物"},{"key":"D","text":"有别的含义要解释"}]}},"cnc_p468":{"desc":"接着读世界名著。可以选和本单元同一类的书，记下人物、关键情节和自己的看法。这不是把课文再抄一遍。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p464","k":1,"why":"漫步世界名著花园之前，要先读过本单元的名著节选，才知道要抓住人物和情节。"},{"id":"cnc_p467","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地二·词语的语境义」，再学「快乐读书吧：漫步世界名著花园」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这个读书吧主要读哪一类书？","answer":"B","explanation":"花园里是各国的名著。生字表和数学题不是这次阅读的对象。","choices":[{"key":"A","text":"只读本册生字表"},{"key":"B","text":"世界名著"},{"key":"C","text":"只读中国古典诗"},{"key":"D","text":"只读数学应用题"}]}},"cnc_p469":{"desc":"读懂朱自清用洗手、吃饭这些日常小事写出日子在悄悄过去。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p426","k":1,"why":"体会散文里的情感之前，要先会理解叙事文中的人物心情。"},{"id":"cnc_p468","k":0,"why":"按统编教材的常见教学顺序，先学「快乐读书吧：漫步世界名著花园」，再学「阅读《匆匆》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"洗手的时候，日子从哪里过去？","answer":"C","explanation":"作者说洗手时，日子从水盆里过去。","choices":[{"key":"A","text":"从窗户里过去"},{"key":"B","text":"从书包里过去"},{"key":"C","text":"从水盆里过去"},{"key":"D","text":"从门缝里过去"}]}},"cnc_p470":{"desc":"读懂史铁生笔下的孩子从早晨盼到下午，母亲一直在忙，盼望最后变成失望。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p469","k":0,"why":"按统编教材的常见教学顺序，先学「阅读《匆匆》」，再学「阅读《那个星期天》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《那个星期天》的作者是谁？","answer":"D","explanation":"这篇是史铁生写的。朱自清写的是《匆匆》。","choices":[{"key":"A","text":"朱自清"},{"key":"B","text":"老舍"},{"key":"C","text":"鲁迅"},{"key":"D","text":"史铁生"}]}},"cnc_p471":{"desc":"写一件让自己动心的事，把当时的动作、语言和心情写具体。只写「我很感动」还不像这篇习作。本单元的例文不单列。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p470","k":1,"why":"让真情自然流露之前，要先读《那个星期天》，才知道心情要落在具体的等待上。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一段是把感情落在事情上？","answer":"A","explanation":"热菜、没把话说出口，读者能看见当时的人。空喊感动，还没有事情。","choices":[{"key":"A","text":"她把凉了的菜又热了一遍，我张了张嘴，那句「你答应过」到底没说出来。"},{"key":"B","text":"我很感动，非常感动。"},{"key":"C","text":"真情自然流露六个字。"},{"key":"D","text":"星期天是一周的第一天。"}]}},"cnc_p472":{"desc":"写「让真情自然流露」时会用到这两种标点：话没说完或列举省略用省略号；解释说明或声音延长用破折号。","criteria":["能把句子写通顺","能按要求选用或修改句子"],"root":"","pre":[{"id":"cnc_p311","k":1,"why":"学习省略号和破折号之前，要先会给对话加引号。"},{"id":"cnc_p471","k":0,"why":"按统编教材的常见教学顺序，先学「习作：让真情自然流露」，再学「省略号和破折号」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"话没有说完，该用哪一个？","answer":"B","explanation":"话断了、后面还有没说出的内容，用省略号。","choices":[{"key":"A","text":"破折号"},{"key":"B","text":"省略号"},{"key":"C","text":"书名号"},{"key":"D","text":"间隔号"}]}},"cnc_p473":{"desc":"背诵李贺《马诗》，记住沙如雪、月似钩和金络脑。同课还有《石灰吟》和《竹石》，不要串句。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p456","k":1,"why":"背《马诗》之前，要先会背《寒食》，才不会把五侯家和金络脑记成同一首。"},{"id":"cnc_p472","k":0,"why":"按统编教材的常见教学顺序，先学「省略号和破折号」，再学「古诗《马诗》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「大漠沙如雪」的下一句是哪一句？","answer":"C","explanation":"大漠的沙像雪，燕山的月像弯钩。如钩不是这一联的下句，似钩才是。","choices":[{"key":"A","text":"何当金络脑"},{"key":"B","text":"燕山月如钩"},{"key":"C","text":"燕山月似钩"},{"key":"D","text":"快走踏清秋"}]}},"cnc_p474":{"desc":"背诵于谦《石灰吟》，记住粉骨碎身、浑不怕和清白。同课还有《马诗》和《竹石》，不要串句。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p473","k":1,"why":"背《石灰吟》之前，要先会背同课的《马诗》，才不会把金络脑和清白装进同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「千锤万凿出深山」的下一句是哪一句？","answer":"D","explanation":"先写石灰被凿出深山，再写它不怕烈火。粉骨碎身是第三句。千磨万击是《竹石》。","choices":[{"key":"A","text":"粉骨碎身浑不怕"},{"key":"B","text":"要留清白在人间"},{"key":"C","text":"千磨万击还坚劲"},{"key":"D","text":"烈火焚烧若等闲"}]}},"cnc_p475":{"desc":"背诵郑燮《竹石》，不要和于谦《石灰吟》、李贺《马诗》串句。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p474","k":1,"why":"背《竹石》之前，要先会背《石灰吟》，两首咏物诗才不会把粉骨碎身和咬定青山记混。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「咬定青山不放松」的下一句是哪一句？","answer":"A","explanation":"竹根长在破裂的岩石中。诗中是破岩，不是破崖。","choices":[{"key":"A","text":"立根原在破岩中"},{"key":"B","text":"立根原在破崖中"},{"key":"C","text":"立根原在岩石中"},{"key":"D","text":"千磨万击还坚劲"}]}},"cnc_p476":{"desc":"读懂李星华回忆父亲李大钊：一九二七年四月二十八日是被难日，父亲烧掉文件，法庭上仍然安定、沉着。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p475","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《竹石》」，再学「阅读《十六年前的回忆》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这篇回忆是谁写的，写的是谁？","answer":"B","explanation":"作者是李大钊的女儿。张思德在《为人民服务》里，董存瑞是下一篇。","choices":[{"key":"A","text":"李大钊写女儿李星华"},{"key":"B","text":"李星华写父亲李大钊"},{"key":"C","text":"毛泽东写张思德"},{"key":"D","text":"董存瑞写自己的战友"}]}},"cnc_p477":{"desc":"读懂毛泽东在张思德追悼会上的讲演：为人民利益而死，就比泰山还重。不要和李大钊、董存瑞记成同一个人。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p476","k":1,"why":"读《为人民服务》之前，要先读《十六年前的回忆》，才不会把李大钊和张思德记成同一个人。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这篇讲演是为了悼念谁？","answer":"C","explanation":"一九四四年九月八日，毛泽东在张思德追悼会上讲话。另外几位是别的课文里的人。","choices":[{"key":"A","text":"李大钊"},{"key":"B","text":"董存瑞"},{"key":"C","text":"张思德"},{"key":"D","text":"邱少云"}]}},"cnc_p478":{"desc":"读懂一九四八年解放隆化时，董存瑞手托炸药包炸毁暗堡，喊的是「为了新中国，前进」。不要和邱少云、黄继光记成同一件事。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p477","k":1,"why":"读《董存瑞舍身炸暗堡》之前，要先读《为人民服务》，才不会把托炸药包和比泰山还重记成同一件事。"},{"id":"cnc_p417","k":1,"why":"读《董存瑞舍身炸暗堡》之前，要先读《我的战友邱少云》，才不会把炸暗堡和在烈火中一动不动记成同一种牺牲。"}],"q":{"type":"choice","difficulty":"basic","prompt":"董存瑞炸的是什么？","answer":"D","explanation":"部队被桥型暗堡的火力压住，前进不了。","choices":[{"key":"A","text":"敌人的一艘军舰"},{"key":"B","text":"一座石灰窑"},{"key":"C","text":"狼牙山上的机枪"},{"key":"D","text":"封锁道路的暗堡"}]}},"cnc_p479":{"desc":"收集一位革命者的事迹，讲清楚他做了什么、为什么值得记住。可以讲故事，也可以办小报。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p478","k":1,"why":"做「奋斗的历程」之前，要先读过《董存瑞舍身炸暗堡》，才有具体的事迹可讲。"}],"q":{"type":"choice","difficulty":"basic","prompt":"这项活动要了解的是什么？","answer":"A","explanation":"第四单元的课文就是材料。春节、梗概、标点是别的单元的任务。","choices":[{"key":"A","text":"革命者奋斗的事迹"},{"key":"B","text":"家乡春节吃什么"},{"key":"C","text":"外国名著的梗概怎么写"},{"key":"D","text":"省略号和破折号的区别"}]}},"cnc_p480":{"desc":"能看出文章开头和结尾怎样呼应，也能说出诗里的事物被写成了人的志向。日积月累有「良药苦口利于病，忠言逆耳利于行」。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p476","k":1,"why":"体会开头和结尾之前，要先读《十六年前的回忆》，这篇开头和结尾都落在同一天上。"},{"id":"cnc_p479","k":0,"why":"按统编教材的常见教学顺序，先学「综合性学习：奋斗的历程」，再学「语文园地四·开头结尾与借物言志」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"《十六年前的回忆》的开头和结尾都落到哪一天？","answer":"B","explanation":"开头说永远忘不了这一天，结尾又回到父亲的被难。这就是前后呼应。","choices":[{"key":"A","text":"腊月二十三"},{"key":"B","text":"一九二七年四月二十八日"},{"key":"C","text":"一九四九年十月一日"},{"key":"D","text":"一个普通的星期天"}]}},"cnc_p481":{"desc":"读懂《孟子》里的《学弈》：弈秋同时教两个人下棋，一个专心，一个心里想着射鸿鹄，所以后者不如前者。这不是智力的差别。不要和上册《两小儿辩日》记成同一则。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p442","k":1,"why":"读《学弈》之前，要先读过上册《两小儿辩日》。学弈选自《孟子》，辩日选自《列子》，不要记成同一则。"},{"id":"cnc_p480","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地四·开头结尾与借物言志」，再学「文言文《学弈》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"弈秋是怎样的人？","answer":"C","explanation":"通国之善弈者，就是全国棋下得最好的人。他是老师，不是学生。","choices":[{"key":"A","text":"两个学生里成绩好的那个"},{"key":"B","text":"孔子的学生"},{"key":"C","text":"全国最擅长下棋的人"},{"key":"D","text":"来辩太阳远近的孩子"}]}},"cnc_p482":{"desc":"读懂叶永烈用波义耳、魏格纳、阿瑟林斯基三个事例说明：真理诞生于一百个问号之后。见了现象还要追问，并坚持研究。","criteria":["能根据短文选出和文字一致的信息","能说出故事或短文的主要意思"],"root":"","pre":[{"id":"cnc_p481","k":1,"why":"读《真理诞生于一百个问号之后》之前，要先读《学弈》，才不会把专心下棋和科学家追问记成同一篇。"}],"q":{"type":"choice","difficulty":"basic","prompt":"课文要证明的观点是哪一句？","answer":"D","explanation":"题目就是观点。偶然的现象只是问号的开头。","choices":[{"key":"A","text":"只要碰到偶然现象，真理就自动出现"},{"key":"B","text":"科学家不需要做实验"},{"key":"C","text":"真理只存在于书本上"},{"key":"D","text":"真理诞生于一百个问号之后"}]}},"cnc_p483":{"desc":"确定中心以后，留下能表现中心的材料，删掉无关的内容。上册已经练习过围绕一个中心把事情写清楚。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p482","k":1,"why":"围绕中心选择材料之前，要先看出《真理诞生于一百个问号之后》是怎样用三个事例说明一个观点的。"},{"id":"cnc_p433","k":1,"why":"围绕中心选择材料之前，要先会在上册习作里围绕一个中心把事情写清楚。"}],"q":{"type":"choice","difficulty":"basic","prompt":"中心是「同学之间互相帮助」。哪一项材料该留下？","answer":"A","explanation":"借笔记、讲题能表现互相帮助。电影、猫和风与这个中心无关。","choices":[{"key":"A","text":"同桌把笔记借给我，并讲了那道题。"},{"key":"B","text":"星期天我看了一场电影。"},{"key":"C","text":"我家的猫很胖。"},{"key":"D","text":"昨天的风很大。"}]}},"cnc_p484":{"desc":"口语「辩论」收到这个园地。观点要一句话说清，理由要落到事例上，听完对方再反驳，不嘲笑人。","criteria":["能把句子写通顺","能按要求选用或修改句子"],"root":"","pre":[{"id":"cnc_p482","k":1,"why":"辩论之前，要先会读一篇用事例说明观点的课文，才知道理由要落到事实上。"},{"id":"cnc_p483","k":0,"why":"按统编教材的常见教学顺序，先学「习作：围绕中心选择材料」，再学「语文园地五·辩论」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"辩论开头最好先怎样？","answer":"B","explanation":"听众要先知道你站在哪一边。笑话和空提高声音都还没有观点。","choices":[{"key":"A","text":"先讲一个和题目无关的笑话"},{"key":"B","text":"用一句话表明自己同意还是反对"},{"key":"C","text":"先请对方承认自己错了"},{"key":"D","text":"先把声音提高，不说内容"}]}},"cnc_p485":{"desc":"从小学生活里选一件真实的事，写出时间、地点、谁做了什么，以及当时的心情。只写「小学生活很快乐」还不是回忆。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p476","k":1,"why":"回忆往事之前，要先读过《十六年前的回忆》，才知道回忆要有具体的一天和具体的人。"},{"id":"cnc_p484","k":0,"why":"按统编教材的常见教学顺序，先学「语文园地五·辩论」，再学「综合性学习：回忆往事」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"回忆往事，材料应该怎样选？","answer":"C","explanation":"真实、具体，读的人才知道是你的小学生活。编故事和抄课文都不是回忆。","choices":[{"key":"A","text":"把六年的课程表都写上"},{"key":"B","text":"编一个没有发生过的英雄故事"},{"key":"C","text":"选一件自己真正经历过、现在还记得住细节的事"},{"key":"D","text":"抄一篇课文当自己的回忆"}]}},"cnc_p486":{"desc":"给老师或同学写惜别的话，要有一件共同经历过的事，再说出不舍和祝福。空喊前程似锦，看不出是对谁说的。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p485","k":1,"why":"写依依惜别之前，要先会回忆一件具体的事，离别才不会只剩空话。"}],"q":{"type":"choice","difficulty":"basic","prompt":"依依惜别的话主要说给谁？","answer":"D","explanation":"惜别是因为马上要分开。名人和试卷都不是一起度过小学生活的人。","choices":[{"key":"A","text":"从没见过的名人"},{"key":"B","text":"课文里的鲁滨逊"},{"key":"C","text":"考试试卷"},{"key":"D","text":"朝夕相处的老师或同学"}]}},"cnc_p487":{"desc":"写给同学或老师的赠言要真诚，最好带上一件共同经历的事。它是「依依惜别」里可以留下来的话。","criteria":["能按要求把话写完整","能判断哪一句更符合题目"],"root":"","pre":[{"id":"cnc_p486","k":1,"why":"写毕业赠言之前，要先会把离别说具体。"},{"id":"cnc_p483","k":1,"why":"写毕业赠言之前，要先会围绕一个意思选择材料。"}],"q":{"type":"choice","difficulty":"basic","prompt":"哪一句更像认真写过的赠言？","answer":"A","explanation":"带着那块橡皮的事，读的人知道你在说他。只剩四个字的祝愿太宽，谁都可以用。","choices":[{"key":"A","text":"你借我橡皮的那天，我才发现你总是先看见别人的难处。"},{"key":"B","text":"前程似锦。"},{"key":"C","text":"万事如意。"},{"key":"D","text":"好好学习。"}]}},"cnc_p488":{"desc":"背诵《诗经·小雅》里的《采薇》节选，分清昔我往矣对杨柳依依，今我来思对雨雪霏霏。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p475","k":1,"why":"背《采薇》之前，要先会背《竹石》，才不会把咬定青山和杨柳依依记成同一首。"},{"id":"cnc_p487","k":0,"why":"按统编教材的常见教学顺序，先学「活动：毕业赠言要具体」，再学「古诗《采薇》（节选）」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「昔我往矣」的下一句是哪一句？","answer":"B","explanation":"出发的时候是春天，柳枝轻柔。雨雪是回来的时候。","choices":[{"key":"A","text":"雨雪霏霏"},{"key":"B","text":"杨柳依依"},{"key":"C","text":"今我来思"},{"key":"D","text":"行道迟迟"}]}},"cnc_p489":{"desc":"背诵王维《送元二使安西》，记住浥轻尘、柳色新和西出阳关无故人。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p488","k":1,"why":"背《送元二使安西》之前，要先会背《采薇》，才不会把杨柳依依和渭城柳色记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「渭城朝雨浥轻尘」的下一句是哪一句？","answer":"C","explanation":"清晨的雨沾湿了尘土，客舍边的柳色显得新。无故人是最后一句。","choices":[{"key":"A","text":"劝君更尽一杯酒"},{"key":"B","text":"客舍青青柳色青"},{"key":"C","text":"客舍青青柳色新"},{"key":"D","text":"西出阳关无故人"}]}},"cnc_p490":{"desc":"背诵杜甫《春夜喜雨》，记住当春乃发生、润物细无声和花重锦官城。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p489","k":1,"why":"背《春夜喜雨》之前，要先会背《送元二使安西》，才不会把渭城朝雨和润物细无声记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「好雨知时节」的下一句是哪一句？","answer":"D","explanation":"雨知道季节，春天到了就来了。诗中是乃，不是才。潜入夜是第二联。","choices":[{"key":"A","text":"随风潜入夜"},{"key":"B","text":"当春才发生"},{"key":"C","text":"润物细无声"},{"key":"D","text":"当春乃发生"}]}},"cnc_p491":{"desc":"背诵王安石《泊船瓜洲》，记住春风又绿江南岸、明月何时照我还。不要和上册《书湖阴先生壁》串成一首。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p439","k":1,"why":"背《泊船瓜洲》之前，要先背过王安石的《书湖阴先生壁》，两首才不会把排闼送青和春风又绿记成同一首。"},{"id":"cnc_p490","k":1,"why":"背《泊船瓜洲》之前，要先会背《春夜喜雨》，才不会把润物无声和春风又绿记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「京口瓜洲一水间」的下一句是哪一句？","answer":"A","explanation":"京口和瓜洲隔着一条江，钟山也不过隔着几重山。照我还是最后一句。","choices":[{"key":"A","text":"钟山只隔数重山"},{"key":"B","text":"春风又绿江南岸"},{"key":"C","text":"钟山只隔数重山外"},{"key":"D","text":"明月何时照我还"}]}},"cnc_p492":{"desc":"背诵叶绍翁《游园不值》，记住小扣柴扉、春色满园关不住、一枝红杏出墙来。不值是没有遇到主人。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p491","k":1,"why":"背《游园不值》之前，要先会背《泊船瓜洲》，才不会把春风又绿和红杏出墙记成同一首。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「应怜屐齿印苍苔」的下一句是哪一句？","answer":"B","explanation":"大概是爱惜地上的苍苔，所以柴门敲了很久也不开。诗中是小扣、柴扉，不是小叩、柴门。","choices":[{"key":"A","text":"春色满园关不住"},{"key":"B","text":"小扣柴扉久不开"},{"key":"C","text":"小叩柴门久不开"},{"key":"D","text":"一枝红杏出墙来"}]}},"cnc_p493":{"desc":"背诵王观这首送别词，记住水是眼波横、山是眉峰聚，以及若到江南赶上春，千万和春住。不要和《送元二使安西》串句。","criteria":["能背出本册要求积累的诗句","能分清作者和诗句，不把字句记错"],"root":"","pre":[{"id":"cnc_p489","k":1,"why":"背《卜算子·送鲍浩然之浙东》之前，要先会背《送元二使安西》，两首送别才不会把阳关和赶上春记成同一首。"},{"id":"cnc_p492","k":0,"why":"按统编教材的常见教学顺序，先学「古诗《游园不值》」，再学「词《卜算子·送鲍浩然之浙东》」。"}],"q":{"type":"choice","difficulty":"basic","prompt":"「水是眼波横」的下一句是哪一句？","answer":"C","explanation":"水像横着的眼波，山像聚着的眉峰。去那边是再后面的问句。","choices":[{"key":"A","text":"山是眉峰竖"},{"key":"B","text":"欲问行人去那边"},{"key":"C","text":"山是眉峰聚"},{"key":"D","text":"眉眼盈盈处"}]}}},"standards":{"ccs-2022:1.PY.01":{"id":"ccs-2022:1.PY.01","text":"能读准声母、韵母、声调和整体认读音节，借助拼音认读汉字，拼读音节。","domain":"拼音","subject":"chinese"},"ccs-2022:1.SZ.01":{"id":"ccs-2022:1.SZ.01","text":"喜欢学习汉字，有主动识字、写字的愿望。能按笔画和偏旁分辨常见汉字，认识常用汉字，其中一部分会写。","domain":"识字写字","subject":"chinese"},"ccs-2022:1.CY.01":{"id":"ccs-2022:1.CY.01","text":"能在语境中理解常见词语，并尝试积累量词、重叠词和反义词。","domain":"词语","subject":"chinese"},"ccs-2022:1.JZ.01":{"id":"ccs-2022:1.JZ.01","text":"能把话说完整，认识逗号、句号、问号和感叹号，愿意用完整的句子表达。","domain":"句子","subject":"chinese"},"ccs-2022:1.YD.01":{"id":"ccs-2022:1.YD.01","text":"能读懂浅近的童话、寓言和故事，借助图画和生活经验说出主要内容。","domain":"阅读理解","subject":"chinese"},"ccs-2022:1.GS.01":{"id":"ccs-2022:1.GS.01","text":"诵读儿歌和浅近的古诗，展开想象，背诵本学段要求积累的优秀诗文，不把诗句张冠李戴。","domain":"古诗文积累","subject":"chinese"},"ccs-2022:1.XZ.01":{"id":"ccs-2022:1.XZ.01","text":"对写话有兴趣，能留心观察，按顺序把想说的话写下来，写完后愿意读给别人听。","domain":"习作基础","subject":"chinese"},"ccs-2022:2.SZ.01":{"id":"ccs-2022:2.SZ.01","text":"能用音序检字法和部首检字法查字典，有初步的独立识字能力，并注意形近字、同音字和多音字。","domain":"识字写字","subject":"chinese"},"ccs-2022:2.CY.01":{"id":"ccs-2022:2.CY.01","text":"能联系上下文理解词语，积累成语和课文中的词语，并初步体会词语的感情色彩。","domain":"词语","subject":"chinese"},"ccs-2022:2.JZ.01":{"id":"ccs-2022:2.JZ.01","text":"能把句子写具体，区分比喻和拟人，正确使用常见关联词和引号。","domain":"句子","subject":"chinese"},"ccs-2022:2.YD.01":{"id":"ccs-2022:2.YD.01","text":"能初步把握文章的主要内容，复述叙事性作品的大意，并借助注释读懂本学段的浅易文言文。","domain":"阅读理解","subject":"chinese"},"ccs-2022:2.GS.01":{"id":"ccs-2022:2.GS.01","text":"诵读优秀诗文，注意语气和节奏，背诵本学段要求积累的古诗，理解诗句中最容易记错的字。","domain":"古诗文积累","subject":"chinese"},"ccs-2022:2.XZ.01":{"id":"ccs-2022:2.XZ.01","text":"能观察周围世界，不拘形式地写下见闻和感受，把一段话的意思写清楚，并学着写日记。","domain":"习作基础","subject":"chinese"},"ccs-2022:3.SZ.01":{"id":"ccs-2022:3.SZ.01","text":"有较强的独立识字能力，能根据偏旁和语境辨析字义，并读准易错字音。","domain":"识字写字","subject":"chinese"},"ccs-2022:3.CY.01":{"id":"ccs-2022:3.CY.01","text":"能联系上下文和自己的积累，推想词语在文中的意思，并体会含义比较深刻的词句。","domain":"词语","subject":"chinese"},"ccs-2022:3.JZ.01":{"id":"ccs-2022:3.JZ.01","text":"能修改明显的语病，做到语句通顺，并按表达需要使用省略号、破折号等常用标点。","domain":"句子","subject":"chinese"},"ccs-2022:3.YD.01":{"id":"ccs-2022:3.YD.01","text":"能阅读叙事性作品和说明性文章，把握主要内容，体会作者的思想感情。","domain":"阅读理解","subject":"chinese"},"ccs-2022:3.YD.02":{"id":"ccs-2022:3.YD.02","text":"能借助注释读懂浅易文言文，说出文章大意，不把人物做的事记错。","domain":"阅读理解","subject":"chinese"},"ccs-2022:3.GS.01":{"id":"ccs-2022:3.GS.01","text":"诵读优秀诗文，注意通过语气和节奏体会情感，背诵本学段古诗，分辨容易记混的字句。","domain":"古诗文积累","subject":"chinese"},"ccs-2022:3.XZ.01":{"id":"ccs-2022:3.XZ.01","text":"能写简单的记实作文，内容具体，感情真实，围绕中心选择材料，并分段把事情写清楚。","domain":"习作基础","subject":"chinese"}}};
